def _brevo_role_sender_email(role="INFO"):
    """Return an explicitly enabled role sender, otherwise the verified default."""
    role = str(role or "INFO").strip().upper()
    override = {
        "TENDER": BREVO_TENDER_SENDER_EMAIL,
        "ACCOUNTS": BREVO_ACCOUNTS_SENDER_EMAIL,
        "SUPPORT": BREVO_SUPPORT_SENDER_EMAIL,
    }.get(role, "")
    return override or BREVO_SENDER_EMAIL


def _brevo_sender_payload(role="INFO"):
    return {"name": BREVO_SENDER_NAME, "email": _brevo_role_sender_email(role)}


def _brevo_reply_to_payload(role="INFO"):
    role = str(role or "INFO").strip().upper()
    email = {
        "TENDER": IBROWS_TENDER_EMAIL,
        "ACCOUNTS": IBROWS_ACCOUNTS_EMAIL,
        "SUPPORT": IBROWS_SUPPORT_EMAIL,
    }.get(role, IBROWS_BUSINESS_EMAIL)
    return {"name": IBROWS_BUSINESS_NAME, "email": email}


