def _effective_fixed_service_price(service, estimated_value, paid_total):
    """Honor an already-paid legacy fixed-price entitlement without repricing it."""
    canonical = canonicalize_service(service)
    current = CAREER_SERVICE_DEFAULT_PRICES_MWK.get(canonical)
    if current is None:
        return None
    paid = Decimal(paid_total or 0)
    try:
        estimated = Decimal(estimated_value) if estimated_value is not None else None
    except Exception:
        estimated = None
    legacy = LEGACY_CAREER_SERVICE_PRICES_MWK.get(canonical)
    if legacy is not None and estimated == legacy and paid >= legacy:
        return legacy
    return Decimal(current)

# Career Assist is a time-limited monthly entitlement. A verified payment
# makes the service eligible for activation; the paid month starts only when an
# authenticated IBROWS admin activates it. One activation lasts one calendar
# month from the activation timestamp, after which that entitlement is consumed.
CAREER_ASSIST_MONTHLY_PRICE_MWK = CAREER_SERVICE_DEFAULT_PRICES_MWK["Career Assist"]

