def upsert_career_assist_application_record(
    customer_number, vacancy, status="PREPARING", authorization_note=""
):
    """Create/update a real per-vacancy Career Assist application record.

    Workflow state is monotonic for delivered/submitted applications: once a pack
    has reached DRAFT_READY, a later preparation retry or QA failure must not
    silently downgrade it to PREPARING/NEEDS_INFO. Likewise SUBMITTED can never
    regress. A genuinely new vacancy still receives its requested initial state.
    """
    allowed_statuses = {"PREPARING", "NEEDS_INFO", "DRAFT_READY", "SUBMITTED", "CANCELLED"}
    status = str(status or "PREPARING").upper().strip()
    if status not in allowed_statuses:
        raise ValueError("Unsupported Career Assist application status")
    vacancy = vacancy or {}
    title = str(vacancy.get("title") or "").strip()
    employer = str(vacancy.get("employer") or "").strip()
    application_url = str(vacancy.get("application_url") or "").strip()
    if not title or not employer or not application_url:
        raise ValueError("Career Assist application requires an exact verified vacancy identity")
    state = get_career_assist_lifecycle_state(customer_number)
    lead_id = state.get("lead_id") if state.get("state") == "ACTIVE" else None

    submitted_sql = (
        "NOW()" if status == "SUBMITTED"
        else "career_assist_applications.submitted_at"
    )
    insert_submitted_sql = "NOW()" if status == "SUBMITTED" else "NULL"
    insert_drafts_sql = "NOW()" if status == "DRAFT_READY" else "NULL"

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                INSERT INTO career_assist_applications
                    (customer_number, career_assist_lead_id, vacancy_title, employer,
                     application_url, status, authorization_note, updated_at,
                     submitted_at, drafts_delivered_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, NOW(),
                        {insert_submitted_sql}, {insert_drafts_sql})
                ON CONFLICT (customer_number, application_url)
                DO UPDATE SET career_assist_lead_id=EXCLUDED.career_assist_lead_id,
                              vacancy_title=EXCLUDED.vacancy_title,
                              employer=EXCLUDED.employer,
                              status=CASE
                                  WHEN career_assist_applications.status='SUBMITTED'
                                      THEN 'SUBMITTED'
                                  WHEN career_assist_applications.status='DRAFT_READY'
                                       AND EXCLUDED.status IN ('PREPARING','NEEDS_INFO')
                                      THEN 'DRAFT_READY'
                                  ELSE EXCLUDED.status
                              END,
                              authorization_note=CASE
                                  WHEN career_assist_applications.status IN ('DRAFT_READY','SUBMITTED')
                                       AND EXCLUDED.status IN ('PREPARING','NEEDS_INFO')
                                      THEN career_assist_applications.authorization_note
                                  WHEN EXCLUDED.authorization_note <> ''
                                      THEN EXCLUDED.authorization_note
                                  ELSE career_assist_applications.authorization_note
                              END,
                              updated_at=NOW(),
                              submitted_at={submitted_sql},
                              drafts_delivered_at=CASE
                                  WHEN EXCLUDED.status='DRAFT_READY'
                                      THEN COALESCE(career_assist_applications.drafts_delivered_at, NOW())
                                  ELSE career_assist_applications.drafts_delivered_at
                              END
                RETURNING id, status
                """,
                (
                    customer_number, lead_id, title[:180], employer[:180],
                    application_url[:2000], status, str(authorization_note or "")[:1200],
                ),
            )
            row = cur.fetchone()
        conn.commit()
    if not row:
        return None
    if row[1] != status:
        print(
            f"CAREER ASSIST APPLICATION STATE PRESERVED: requested={status} actual={row[1]}",
            flush=True,
        )
    return row[0]


def get_career_assist_application_for_submission(customer_number, customer_message=""):
    """Return the intended prepared Career Assist application for final-submission handling.

    Prefer an exact URL in the approval message. Otherwise inspect the customer's recent
    application records and prefer one whose vacancy title/employer is explicitly named in
    the approval message. This prevents an unrelated DRAFT_READY vacancy from winning merely
    because it has a stronger workflow state.
    """
    direct_urls = extract_public_urls_from_text(customer_message)
    direct_url = direct_urls[0] if len(direct_urls) == 1 else ""

    def _row_to_application(row):
        if not row:
            return None
        return {
            "id": row[0],
            "career_assist_lead_id": row[1],
            "title": str(row[2] or "").strip(),
            "employer": str(row[3] or "").strip(),
            "application_url": str(row[4] or "").strip(),
            "status": str(row[5] or "").strip().upper(),
            "drafts_delivered_at": row[6],
            "submission_authorized_at": row[7],
            "started_at": row[8],
            "updated_at": row[9],
        }

    with get_db() as conn:
        with conn.cursor() as cur:
            if direct_url:
                cur.execute(
                    """
                    SELECT id, career_assist_lead_id, vacancy_title, employer,
                           application_url, status, drafts_delivered_at,
                           submission_authorized_at, started_at, updated_at
                    FROM career_assist_applications
                    WHERE customer_number=%s AND LOWER(application_url)=LOWER(%s)
                    ORDER BY updated_at DESC, id DESC
                    LIMIT 1
                    """,
                    (customer_number, direct_url),
                )
                return _row_to_application(cur.fetchone())

            cur.execute(
                """
                SELECT id, career_assist_lead_id, vacancy_title, employer,
                       application_url, status, drafts_delivered_at,
                       submission_authorized_at, started_at, updated_at
                FROM career_assist_applications
                WHERE customer_number=%s
                  AND status IN ('DRAFT_READY','NEEDS_INFO','PREPARING')
                ORDER BY updated_at DESC, id DESC
                LIMIT 12
                """,
                (customer_number,),
            )
            rows = cur.fetchall()

    if not rows:
        return None

    message_norm = " ".join(
        str(customer_message or "")
        .casefold()
        .replace("–", "-")
        .replace("—", "-")
        .split()
    )

    scored = []
    for order, row in enumerate(rows):
        app = _row_to_application(row)
        title_norm = " ".join(app["title"].casefold().replace("–", "-").replace("—", "-").split())
        employer_norm = " ".join(app["employer"].casefold().split())
        url_norm = app["application_url"].casefold()
        score = 0
        if url_norm and url_norm in message_norm:
            score += 100
        if title_norm and title_norm in message_norm:
            score += 30
        if employer_norm and employer_norm in message_norm:
            score += 10
        if app["status"] == "DRAFT_READY":
            score += 2
        # rows are newest-first; tiny tie-break preference for newer rows
        score -= order * 0.001
        scored.append((score, app))

    # If the approval names a vacancy, choose that vacancy even if an unrelated record
    # is already DRAFT_READY. Otherwise use the newest record, preferring DRAFT_READY.
    named = [item for item in scored if item[0] >= 10]
    if named:
        named.sort(key=lambda item: item[0], reverse=True)
        return named[0][1]

    draft_rows = [app for _, app in scored if app["status"] == "DRAFT_READY"]
    if draft_rows:
        return draft_rows[0]
    return scored[0][1]


def recover_legacy_career_assist_draft_ready(customer_number, application):
    """Repair only the old state-regression case after drafts were actually delivered.

    Durable evidence is preferred. For records created before drafts_delivered_at existed,
    recover only when the stored conversation proves both (1) the customer requested this
    exact vacancy (URL or title) and (2) the assistant subsequently emitted the deterministic
    review-ready message produced by the successful pack path. This avoids promoting a real
    NEEDS_INFO application merely because the customer asks to submit it.
    """
    if not application:
        return application
    if application.get("status") not in {"PREPARING", "NEEDS_INFO"}:
        return application

    app_id = application.get("id")
    title = str(application.get("title") or "").strip()
    application_url = str(application.get("application_url") or "").strip()
    started_at = application.get("started_at")

    if not app_id or not started_at:
        print("CAREER ASSIST LEGACY RECOVERY SKIPPED: missing_record_identity", flush=True)
        return application

    delivered_at = application.get("drafts_delivered_at")

    with get_db() as conn:
        with conn.cursor() as cur:
            # Newer records already have durable proof that the drafts were delivered.
            if delivered_at is None:
                # Older builds did not have drafts_delivered_at. Tie the successful assistant
                # message to a preceding user request that names this exact vacancy.
                cur.execute(
                    """
                    SELECT a.created_at
                    FROM conversations a
                    WHERE a.customer_number=%s
                      AND a.role='assistant'
                      AND a.created_at >= %s
                      AND (
                            a.content ILIKE %s
                         OR a.content ILIKE %s
                      )
                      AND EXISTS (
                          SELECT 1
                          FROM conversations u
                          WHERE u.customer_number=a.customer_number
                            AND u.role='user'
                            AND u.created_at >= %s - INTERVAL '10 minutes'
                            AND u.created_at <= a.created_at
                            AND (
                                  (%s <> '' AND u.content ILIKE %s)
                               OR (%s <> '' AND u.content ILIKE %s)
                            )
                      )
                    ORDER BY a.created_at DESC, a.id DESC
                    LIMIT 1
                    """,
                    (
                        customer_number,
                        started_at,
                        "%Draft application files have been prepared for review before submission.%",
                        "%Please review every detail before submitting%",
                        started_at,
                        application_url,
                        f"%{application_url}%" if application_url else "%__NO_URL__%",
                        title,
                        f"%{title}%" if title else "%__NO_TITLE__%",
                    ),
                )
                delivered = cur.fetchone()
                if not delivered:
                    print(
                        f"CAREER ASSIST LEGACY RECOVERY SKIPPED: no_delivery_evidence record={app_id}",
                        flush=True,
                    )
                    return application
                delivered_at = delivered[0]

            cur.execute(
                """
                UPDATE career_assist_applications
                SET status='DRAFT_READY',
                    drafts_delivered_at=COALESCE(drafts_delivered_at, %s),
                    updated_at=NOW()
                WHERE id=%s
                  AND customer_number=%s
                  AND status IN ('PREPARING','NEEDS_INFO')
                RETURNING id
                """,
                (delivered_at, app_id, customer_number),
            )
            recovered = cur.fetchone()
        conn.commit()

    if recovered:
        application = dict(application)
        application["status"] = "DRAFT_READY"
        application["drafts_delivered_at"] = delivered_at
        print(
            f"CAREER ASSIST LEGACY DRAFT STATE RECOVERED: record={application['id']}",
            flush=True,
        )
    return application


def record_career_assist_submission_handoff(customer_number, application, customer_name=""):
    """Record vacancy-specific approval for final employer-form handling exactly once.

    Approval is an idempotent handoff, not an employer submission. Repeated approval
    messages must not create duplicate notes, follow-ups, or alert emails. The
    application remains DRAFT_READY until a real employer-side submission succeeds.
    Returns ``(application_id, newly_recorded)``.
    """
    if not application or application.get("status") != "DRAFT_READY":
        raise ValueError("Career Assist application is not draft-ready")

    app_id = application["id"]
    lead_id = application.get("career_assist_lead_id")
    title = application.get("title") or "selected vacancy"
    employer = application.get("employer") or "employer"
    url = application.get("application_url") or ""
    note = (
        f"Customer approved final submission handling for {title} at {employer}. "
        f"Prepared drafts are approved; manual/browser employer-form submission is pending. "
        f"Do not mark SUBMITTED until the employer confirms successful submission. URL: {url}"
    )

    newly_recorded = False
    with get_db() as conn:
        with conn.cursor() as cur:
            # Serialize approval for this application so repeated WhatsApp deliveries or
            # repeated customer messages cannot create duplicate handoff records.
            cur.execute(
                """
                SELECT submission_authorized_at
                FROM career_assist_applications
                WHERE id=%s AND customer_number=%s AND status='DRAFT_READY'
                FOR UPDATE
                """,
                (app_id, customer_number),
            )
            approval_row = cur.fetchone()
            if not approval_row:
                raise ValueError("Draft-ready application changed before handoff")

            if approval_row[0] is None:
                cur.execute(
                    """
                    UPDATE career_assist_applications
                    SET authorization_note=%s,
                        submission_authorized_at=NOW(),
                        updated_at=NOW()
                    WHERE id=%s AND customer_number=%s AND status='DRAFT_READY'
                      AND submission_authorized_at IS NULL
                    """,
                    (note[:1200], app_id, customer_number),
                )
                if cur.rowcount != 1:
                    raise ValueError("Submission approval changed during handoff")
                newly_recorded = True

                if lead_id:
                    cur.execute(
                        "INSERT INTO lead_notes (lead_id, note_text) VALUES (%s, %s)",
                        (lead_id, note[:1800]),
                    )
                    cur.execute(
                        """
                        UPDATE leads
                        SET follow_up_at=NOW(),
                            handover_reason=%s,
                            updated_at=NOW()
                        WHERE id=%s
                        """,
                        (
                            f"Customer approved final employer submission for {title}; actual submission pending confirmation."[:800],
                            lead_id,
                        ),
                    )
        conn.commit()

    # Notify Jones only on the first recorded approval. Repeated approval messages are
    # acknowledged but must not spam email or duplicate CRM notes/follow-ups.
    if newly_recorded and lead_id:
        try:
            send_career_submission_approval_email(
                lead_id=lead_id,
                customer_name=customer_name,
                customer_number=customer_number,
                title=title,
                employer=employer,
                application_url=url,
            )
        except Exception as notify_error:
            print(f"CAREER ASSIST SUBMISSION HANDOFF EMAIL ERROR: {type(notify_error).__name__}", flush=True)

    return app_id, newly_recorded


