def get_latest_open_lead_service(customer_number):
    """
    Keep an explicit human takeover attached to the customer's current service
    when possible. "Human Handover" is a workflow state, not a service category.
    """
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT service
                FROM leads
                WHERE customer_number = %s
                  AND status IN ('NEW', 'CONTACTED')
                  AND merged_into_lead_id IS NULL
                  AND privacy_deleted_at IS NULL
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 1
                """,
                (customer_number,)
            )
            row = cur.fetchone()

    if row and row[0]:
        return canonicalize_service(row[0])
    return "General Enquiry"


def get_verified_service_payment_state(customer_number, service, fallback_required_mwk=None):
    """Return authoritative ledger status for the latest open lead of one service.

    Only rows entered into lead_payments by the authenticated admin workflow count
    as verified money received. Customer messages, screenshots and references do not.
    """
    wanted = canonicalize_service(service)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    l.id, l.service, l.estimated_value, COALESCE(l.value_currency, 'MWK'),
                    l.quote_status, l.status, l.updated_at,
                    COALESCE(SUM(CASE WHEN p.currency = COALESCE(l.value_currency, 'MWK')
                                      THEN p.amount ELSE 0 END), 0) AS paid_total
                FROM leads l
                LEFT JOIN lead_payments p ON p.lead_id = l.id
                WHERE l.customer_number = %s
                  AND l.status IN ('NEW', 'CONTACTED')
                  AND l.merged_into_lead_id IS NULL
                  AND l.privacy_deleted_at IS NULL
                  AND l.entitlement_consumed_at IS NULL
                GROUP BY l.id, l.service, l.estimated_value, l.value_currency,
                         l.quote_status, l.status, l.updated_at
                ORDER BY l.updated_at DESC, l.id DESC
                """,
                (customer_number,),
            )
            rows = cur.fetchall()

    row = next((r for r in rows if canonicalize_service(r[1]) == wanted), None)
    if not row:
        required = Decimal(str(fallback_required_mwk)) if fallback_required_mwk is not None else None
        return {
            "lead_id": None, "service": wanted, "currency": "MWK",
            "required": required, "paid": Decimal("0"), "balance": required,
            "status": "NOT_VERIFIED", "quote_status": "NOT_STARTED",
        }

    lead_id, _service, estimated, currency, quote_status, _status, _updated, paid_total = row
    paid = Decimal(paid_total or 0)
    required = Decimal(estimated) if estimated is not None else None
    if required is None and currency == "MWK" and fallback_required_mwk is not None:
        required = Decimal(str(fallback_required_mwk))

    balance = None if required is None else max(required - paid, Decimal("0"))
    if paid <= 0:
        state = "NOT_PAID"
    elif required is None:
        state = "RECEIVED_UNPRICED"
    elif paid < required:
        state = "PART_PAID"
    else:
        state = "PAID"

    return {
        "lead_id": lead_id, "service": wanted, "currency": currency,
        "required": required, "paid": paid, "balance": balance,
        "status": state, "quote_status": quote_status or "NOT_STARTED",
    }


def expire_career_assist_entitlements(customer_number=None):
    """Consume expired Career Assist monthly entitlements.

    Expiry is enforced whenever the customer interacts, the admin dashboard is
    opened, or the scheduled reminder task runs. Financial payment rows are kept
    intact for audit/accounting; only the service entitlement is closed/consumed.
    """
    params = []
    customer_clause = ""
    if customer_number:
        customer_clause = " AND customer_number = %s"
        params.append(customer_number)

    expired = []
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT id, customer_number, service_expires_at
                FROM leads
                WHERE LOWER(TRIM(COALESCE(service, ''))) = 'career assist'
                  AND service_expires_at IS NOT NULL
                  AND service_expires_at <= NOW()
                  AND entitlement_consumed_at IS NULL
                  AND merged_into_lead_id IS NULL
                  AND privacy_deleted_at IS NULL
                  {customer_clause}
                FOR UPDATE
                """,
                tuple(params),
            )
            rows = cur.fetchall()
            for lead_id, number, expires_at in rows:
                cur.execute(
                    """
                    UPDATE leads
                    SET entitlement_consumed_at = COALESCE(service_expires_at, NOW()),
                        entitlement_consumed_reason = %s,
                        status = 'CLOSED',
                        handover_reason = %s,
                        follow_up_at = NULL,
                        follow_up_notified_at = NULL,
                        follow_up_notification_claimed_at = NULL,
                        follow_up_notification_error = NULL,
                        updated_at = NOW()
                    WHERE id = %s
                      AND entitlement_consumed_at IS NULL
                    """,
                    (
                        "Career Assist monthly entitlement consumed when its one-month service term expired.",
                        "Career Assist term expired. A new MK60,000 payment and new activation are required for renewal.",
                        lead_id,
                    ),
                )
                if cur.rowcount == 1:
                    cur.execute(
                        """
                        INSERT INTO lead_notes (lead_id, note_text)
                        VALUES (%s, %s)
                        """,
                        (
                            lead_id,
                            "Career Assist monthly term expired. Entitlement consumed; renewal requires a new MK60,000 payment.",
                        ),
                    )
                    _activity_insert(
                        cur,
                        lead_id,
                        "SERVICE_EXPIRED",
                        "Career Assist one-month entitlement expired and was consumed; renewal requires a new payment.",
                    )
                    expired.append((lead_id, number, expires_at))
        conn.commit()

    for lead_id, number, expires_at in expired:
        print(
            f"CAREER ASSIST ENTITLEMENT EXPIRED: lead={lead_id} customer={number} expires_at={expires_at}",
            flush=True,
        )
    return len(expired)


def normalize_open_career_assist_pricing(customer_number=None):
    """Repair stale legacy Career Assist pricing to the approved MK60,000 monthly fee.

    Older test/legacy leads can carry an unrelated estimated value even after the
    correct Career Assist payment is recorded. Career Assist is a fixed-price
    service, so open/unconsumed operational leads must display and account for the
    approved monthly amount. Historical consumed/expired leads are left untouched.
    """
    required = CAREER_ASSIST_MONTHLY_PRICE_MWK
    params = [required]
    customer_clause = ""
    if customer_number:
        customer_clause = " AND customer_number = %s"
        params.append(customer_number)

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                UPDATE leads
                SET estimated_value = %s,
                    value_currency = 'MWK'
                WHERE LOWER(TRIM(COALESCE(service, ''))) = 'career assist'
                  AND merged_into_lead_id IS NULL
                  AND privacy_deleted_at IS NULL
                  AND entitlement_consumed_at IS NULL
                  AND status IN ('NEW', 'CONTACTED')
                  {customer_clause}
                  AND (
                        estimated_value IS NULL
                        OR estimated_value <= 0
                        OR UPPER(COALESCE(value_currency, 'MWK')) <> 'MWK'
                  )
                """,
                tuple(params),
            )
            repaired = cur.rowcount
        conn.commit()

    if repaired:
        print(
            f"CAREER ASSIST PRICE NORMALIZED: leads={repaired} standard_mwk={required}",
            flush=True,
        )
    return repaired


def get_career_assist_lifecycle_state(customer_number):
    """Return authoritative Career Assist activation/expiry state."""
    expire_career_assist_entitlements(customer_number)
    normalize_open_career_assist_pricing(customer_number)
    required = CAREER_ASSIST_MONTHLY_PRICE_MWK

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    l.id, l.status, l.entitlement_consumed_at,
                    l.service_started_at, l.service_expires_at,
                    l.estimated_value,
                    COALESCE(l.value_currency, 'MWK'),
                    COALESCE((
                        SELECT SUM(p.amount)
                        FROM lead_payments p
                        WHERE p.lead_id = l.id
                          AND p.currency = 'MWK'
                    ), 0) AS paid_total
                FROM leads l
                WHERE l.customer_number = %s
                  AND LOWER(TRIM(COALESCE(l.service, ''))) = 'career assist'
                  AND l.merged_into_lead_id IS NULL
                  AND l.privacy_deleted_at IS NULL
                ORDER BY l.updated_at DESC, l.id DESC
                LIMIT 1
                """,
                (customer_number,),
            )
            row = cur.fetchone()

    if not row:
        return {
            "lead_id": None, "state": "NOT_ENROLLED", "paid": Decimal("0"),
            "required": required, "started_at": None, "expires_at": None,
        }

    lead_id, status, consumed_at, started_at, expires_at, estimated_value, currency, paid_total = row
    paid = Decimal(paid_total or 0)
    required = _effective_fixed_service_price("Career Assist", estimated_value, paid)
    now_utc = datetime.now(UTC_TIMEZONE)

    if consumed_at is not None:
        state = "EXPIRED" if started_at is not None else "CONSUMED"
    elif started_at is not None and expires_at is not None and expires_at > now_utc:
        state = "ACTIVE"
    elif paid >= required and currency == "MWK":
        state = "PAID_AWAITING_ACTIVATION"
    elif paid > 0:
        state = "PART_PAID"
    else:
        state = "NOT_PAID"

    return {
        "lead_id": lead_id, "state": state, "paid": paid, "required": required,
        "started_at": started_at, "expires_at": expires_at, "status": status,
    }


def activate_career_assist_entitlement(lead_id):
    """Activate one verified MK60,000 Career Assist payment for one month.

    Activation is an explicit authenticated-admin action. It never happens from a
    customer payment claim or screenshot. The term begins at activation and ends
    one calendar month later. The same payment cannot be reactivated after expiry.
    """
    required = CAREER_ASSIST_MONTHLY_PRICE_MWK

    # Consume any already-expired term first so an old payment cannot be revived.
    expire_career_assist_entitlements()

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT l.customer_number, l.service, l.status,
                       l.entitlement_consumed_at, l.service_started_at,
                       l.service_expires_at, l.estimated_value,
                       COALESCE(l.value_currency, 'MWK'),
                       COALESCE((
                           SELECT SUM(p.amount)
                           FROM lead_payments p
                           WHERE p.lead_id = l.id
                             AND p.currency = 'MWK'
                       ), 0) AS paid_total
                FROM leads l
                WHERE l.id = %s
                  AND l.merged_into_lead_id IS NULL
                  AND l.privacy_deleted_at IS NULL
                FOR UPDATE OF l
                """,
                (lead_id,),
            )
            row = cur.fetchone()
            if not row:
                raise ValueError("Career Assist lead not found.")

            (customer_number, service, status, consumed_at, started_at,
             expires_at, estimated_value, currency, paid_total) = row

            if canonicalize_service(service) != "Career Assist":
                raise ValueError("Lead is not a Career Assist service.")
            if consumed_at is not None:
                raise ValueError("This Career Assist monthly entitlement is already consumed/expired.")
            if str(status or "").strip().upper() == "CLOSED":
                raise ValueError("A closed Career Assist lead cannot be activated. Reopen or create a new service lead first.")

            now_utc = datetime.now(UTC_TIMEZONE)
            if started_at is not None and expires_at is not None and expires_at > now_utc:
                return {
                    "lead_id": lead_id, "already_active": True,
                    "started_at": started_at, "expires_at": expires_at,
                }

            paid_total = Decimal(paid_total or 0)
            required = _effective_fixed_service_price("Career Assist", estimated_value, paid_total)
            if currency != "MWK":
                raise ValueError("Career Assist entitlement currency is not MWK.")
            if paid_total < required:
                raise ValueError("Career Assist entitlement is not fully paid.")

            cur.execute(
                """
                UPDATE leads
                SET estimated_value = %s,
                    value_currency = 'MWK',
                    quote_status = 'ACCEPTED',
                    service_started_at = NOW(),
                    service_expires_at = NOW() + INTERVAL '1 month',
                    status = 'CONTACTED',
                    handover_reason = %s,
                    updated_at = NOW()
                WHERE id = %s
                  AND entitlement_consumed_at IS NULL
                RETURNING service_started_at, service_expires_at
                """,
                (
                    required,
                    "Career Assist activated for one month. Provide search/application support within the agreed customer scope until expiry.",
                    lead_id,
                ),
            )
            activated = cur.fetchone()
            if not activated:
                raise ValueError("Career Assist activation could not be recorded.")
            started_at, expires_at = activated

            cur.execute(
                """
                INSERT INTO lead_notes (lead_id, note_text)
                VALUES (%s, %s)
                """,
                (
                    lead_id,
                    "Admin activated Career Assist after verified MK60,000 payment. One-month service term started.",
                ),
            )
            _activity_insert(
                cur,
                lead_id,
                "SERVICE_ACTIVATED",
                "Career Assist activated after verified MK60,000 payment; one-month entitlement started.",
            )
        conn.commit()

    print(
        f"CAREER ASSIST ACTIVATED: lead={lead_id} customer={customer_number} expires_at={expires_at}",
        flush=True,
    )
    return {
        "lead_id": lead_id, "already_active": False,
        "started_at": started_at, "expires_at": expires_at,
    }


def build_verified_payment_context(customer_number):
    """Supply model-visible payment facts without exposing references or bank data."""
    # Enforce monthly expiry before exposing payment/service state to the model.
    expire_career_assist_entitlements(customer_number)
    lines = [
        "INTERNAL VERIFIED PAYMENT STATUS. This is authoritative business ledger context, "
        "not a customer claim. A screenshot/message/reference alone is never VERIFIED. "
        "For paid career services not listed as PAID below, do not say payment is confirmed."
    ]
    any_open = False
    for service, default_price in CAREER_SERVICE_DEFAULT_PRICES_MWK.items():
        state = get_verified_service_payment_state(customer_number, service, default_price)
        if state["lead_id"] is None:
            continue
        any_open = True
        required = state["required"]
        required_text = (
            f"{state['currency']} {required:,.0f}" if required is not None else "not priced in ledger"
        )
        lines.append(
            f"- {service}: {state['status']}; verified received "
            f"{state['currency']} {state['paid']:,.0f}; required {required_text}."
        )
    if not any_open:
        lines.append("- No open paid-career-service ledger record is currently available for this customer.")

    career_assist = get_career_assist_lifecycle_state(customer_number)
    ca_state = career_assist["state"]
    if ca_state == "ACTIVE":
        started = career_assist["started_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y %H:%M")
        expires = career_assist["expires_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y %H:%M")
        lines.append(
            f"- Career Assist activation: ACTIVE; started {started} Malawi time; "
            f"expires {expires} Malawi time. This active term includes vacancy discovery plus job-application support/execution "
            "within the customer's agreed scope. Do NOT require a separate MK3,000 Single Job Application payment for an "
            "application handled under this active Career Assist term. Customer consent and any genuinely missing sensitive "
            "or mandatory declarations are still required before submission."
        )
    elif ca_state == "PAID_AWAITING_ACTIVATION":
        lines.append(
            "- Career Assist activation: PAID_AWAITING_ACTIVATION. MK60,000 is verified, "
            "but the monthly term has not started. Do not say Career Assist is active until an IBROWS admin activates it."
        )
    elif ca_state == "EXPIRED":
        lines.append(
            "- Career Assist activation: EXPIRED. The previous monthly entitlement is consumed; "
            "a new MK60,000 service-specific payment and a new admin activation are required for renewal."
        )
    elif ca_state == "PART_PAID":
        lines.append(
            f"- Career Assist activation: PART_PAID; verified MWK {career_assist['paid']:,.0f} of MWK {career_assist['required']:,.0f}. Not active."
        )
    elif ca_state == "NOT_PAID":
        lines.append("- Career Assist activation: NOT_PAID. Not active.")

    try:
        standing = get_career_assist_standing_consent(customer_number)
        if standing.get("event_type") == "GRANT" and standing.get("effective"):
            lines.append(
                "- Career Assist standing application authorization: ACTIVE. Exact customer scope: "
                + standing.get("scope_text", "")[:2200]
            )
            lines.append(
                "  Use standing authority only within that exact scope. Never invent or answer new/sensitive declarations. "
                "Never claim an employer submission unless the system has real submission confirmation."
            )
        elif standing.get("event_type") == "REVOKE":
            lines.append(
                "- Career Assist standing application authorization: REVOKED. Do not submit future applications under standing authority. "
                "Vacancy recommendations and individual application assistance may continue."
            )
        elif standing.get("event_type") == "GRANT" and not standing.get("effective"):
            lines.append(
                "- Career Assist standing application authorization: INACTIVE because the Career Assist term is not currently active. "
                "Do not use it to submit applications."
            )
    except Exception as consent_context_error:
        print(f"CAREER ASSIST CONSENT CONTEXT ERROR: {type(consent_context_error).__name__}", flush=True)

    return [{"role": "user", "content": "\n".join(lines)}]


def ensure_single_job_application_lead(customer_number, customer_name):
    """Create/update the service-specific MK3,000 Single Job Application lead."""
    required = CAREER_SERVICE_DEFAULT_PRICES_MWK["Single Job Application"]
    lead_id, is_new = create_or_update_lead(
        customer_number=customer_number,
        customer_name=customer_name,
        service="Single Job Application",
        summary=(
            "Customer requested one paid job application. Vacancy details and "
            "verified service-specific payment are required before execution."
        ),
        handover_reason=(
            "Single Job Application workflow: verify the MK3,000 payment and "
            "continue once the vacancy/application details are available."
        ),
    )
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE leads
                SET estimated_value = COALESCE(estimated_value, %s),
                    value_currency = CASE WHEN estimated_value IS NULL THEN 'MWK' ELSE value_currency END,
                    quote_status = CASE
                        WHEN quote_status IN ('NOT_STARTED', 'DRAFT') THEN 'ACCEPTED'
                        ELSE quote_status
                    END,
                    updated_at = NOW()
                WHERE id = %s
                """,
                (required, lead_id),
            )
        conn.commit()
    if is_new:
        try:
            send_new_lead_email(
                lead_id=lead_id,
                customer_name=customer_name,
                customer_number=customer_number,
                service="Single Job Application",
                summary="Customer requested one paid job application; payment verification is required.",
                handover_reason="Verify the MK3,000 Single Job Application payment and vacancy details.",
            )
        except Exception as notify_error:
            print(
                f"SINGLE JOB APPLICATION LEAD NOTIFICATION ERROR: {type(notify_error).__name__}",
                flush=True,
            )
    return lead_id


def single_job_application_payment_gate(customer_number, customer_name):
    """Return None only when the MK3,000 Single Job Application payment is verified."""
    required = CAREER_SERVICE_DEFAULT_PRICES_MWK["Single Job Application"]

    # Always normalize/create the dedicated service lead first. Older records may
    # already have a verified payment but still be missing the fixed MK5,000 value
    # and accepted-service metadata needed by the admin dashboard.
    try:
        ensure_single_job_application_lead(customer_number, customer_name)
    except Exception as gate_error:
        print(
            f"SINGLE JOB APPLICATION PAYMENT GATE LEAD ERROR: {type(gate_error).__name__}",
            flush=True,
        )

    state = get_verified_service_payment_state(
        customer_number, "Single Job Application", required
    )
    if state["status"] == "PAID":
        return None

    # Ensure the ledger has a dedicated service lead before asking staff/customer
    # to verify payment. This prevents a MK5,000 payment from being attached to
    # an unrelated CV, Career Assist, or general enquiry entitlement.
    # Re-read after normalization so the reply reflects the current service ledger.
    state = get_verified_service_payment_state(
        customer_number, "Single Job Application", required
    )

    channels = approved_payment_channels_text()
    if state["status"] == "PART_PAID":
        balance = state["balance"] if state["balance"] is not None else required - state["paid"]
        return (
            f"The Single Job Application fee is MK{required:,.0f}. "
            f"The IBROWS ledger currently shows MK{state['paid']:,.0f} verified for this service, "
            f"with MK{balance:,.0f} remaining. Application work starts after the full "
            "service payment is verified, unless an authorized IBROWS admin records an approved exception.\n\n"
            "Please also send the job advert, application link, or exact job title and employer if you have not already done so.\n\n"
            "Approved payment channels:\n" + channels +
            "\n\nDo not send your PIN, OTP, password, or security codes."
        )

    return (
        f"The Single Job Application fee is MK{required:,.0f}. "
        "Application work starts only after the payment is verified in the IBROWS ledger. "
        "A screenshot, transaction reference, or customer message by itself does not mark payment as confirmed.\n\n"
        "Please send the job advert, application link, or exact job title and employer if you have not already done so.\n\n"
        "Approved payment channels:\n" + channels +
        "\n\nAfter payment, send the transaction reference or payment confirmation for IBROWS verification. "
        "Do not send your PIN, OTP, password, or security codes."
    )


def detect_career_assist_standing_consent_revoke(customer_message):
    """Detect an explicit withdrawal of standing Career Assist application authority."""
    text = " ".join(str(customer_message or "").lower().split())
    if not text:
        return False
    exact_markers = (
        "stop applying for jobs on my behalf",
        "stop applying on my behalf",
        "revoke my standing application authorization",
        "revoke my standing application authorisation",
        "revoke my application authorization",
        "revoke my application authorisation",
        "withdraw my standing application authorization",
        "withdraw my standing application authorisation",
        "cancel my standing application authorization",
        "cancel my standing application authorisation",
    )
    if any(marker in text for marker in exact_markers):
        return True
    standing_marker = any(marker in text for marker in (
        "standing consent", "standing authorization", "standing authorisation",
        "automatic submission consent", "automatic application consent",
    ))
    revoke_marker = any(marker in text for marker in (
        "revoke", "withdraw", "cancel", "stop", "disable", "turn off",
    ))
    return standing_marker and revoke_marker


def detect_career_assist_standing_consent_grant(customer_message):
    """Detect explicit standing authorization for future Career Assist applications."""
    text = " ".join(str(customer_message or "").lower().split())
    if not text or detect_career_assist_standing_consent_revoke(customer_message):
        return False
    authorization_marker = any(marker in text for marker in (
        "i authorize ibrows", "i authorise ibrows", "authorize ibrows", "authorise ibrows",
        "standing application authorization", "standing application authorisation",
        "standing consent", "automatic application consent",
    ))
    application_marker = any(marker in text for marker in (
        "apply", "application", "applications", "submit", "submission",
    ))
    future_scope_marker = any(marker in text for marker in (
        "during my active career assist", "during career assist", "future jobs",
        "future vacancies", "jobs in", "roles in", "vacancies in", "on my behalf",
    ))
    return authorization_marker and application_marker and future_scope_marker


def get_career_assist_standing_consent(customer_number):
    """Return the latest append-only standing-consent event and effective status."""
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, career_assist_lead_id, event_type, scope_text, created_at
                FROM career_assist_application_consent_events
                WHERE customer_number = %s
                ORDER BY created_at DESC, id DESC
                LIMIT 1
                """,
                (customer_number,),
            )
            row = cur.fetchone()
    if not row:
        return {
            "event_id": None, "lead_id": None, "event_type": None,
            "scope_text": "", "created_at": None, "effective": False,
        }
    event_id, lead_id, event_type, scope_text, created_at = row
    effective = False
    if str(event_type or "").upper() == "GRANT":
        try:
            effective = get_career_assist_lifecycle_state(customer_number).get("state") == "ACTIVE"
        except Exception:
            effective = False
    return {
        "event_id": event_id,
        "lead_id": lead_id,
        "event_type": str(event_type or "").upper(),
        "scope_text": str(scope_text or ""),
        "created_at": created_at,
        "effective": effective,
    }


def _record_career_assist_consent_event(customer_number, lead_id, event_type, scope_text=""):
    event_type = str(event_type or "").upper().strip()
    if event_type not in {"GRANT", "REVOKE"}:
        raise ValueError("Invalid Career Assist consent event type.")
    scope_text = str(scope_text or "").strip()[:3500]
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO career_assist_application_consent_events
                    (customer_number, career_assist_lead_id, event_type, scope_text)
                VALUES (%s, %s, %s, %s)
                RETURNING id, created_at
                """,
                (customer_number, lead_id, event_type, scope_text or None),
            )
            event_id, created_at = cur.fetchone()
            if lead_id:
                if event_type == "GRANT":
                    note = (
                        "Standing Career Assist application authorization GRANTED. "
                        "Exact customer scope is preserved in the consent audit event. "
                        "Unverified/sensitive declarations still require customer input; "
                        "submission must never be claimed without real submission confirmation."
                    )
                    activity_type = "APPLICATION_CONSENT_GRANTED"
                else:
                    note = (
                        "Standing Career Assist application authorization REVOKED. "
                        "Future submissions under standing authority must stop immediately; "
                        "vacancy recommendations may continue."
                    )
                    activity_type = "APPLICATION_CONSENT_REVOKED"
                cur.execute(
                    "INSERT INTO lead_notes (lead_id, note_text) VALUES (%s, %s)",
                    (lead_id, note),
                )
                _activity_insert(cur, lead_id, activity_type, note)
        conn.commit()
    return {"event_id": event_id, "created_at": created_at}


def handle_career_assist_standing_consent(customer_number, customer_message):
    """Handle standing-consent grant/revocation deterministically before search routing."""
    if detect_career_assist_standing_consent_revoke(customer_message):
        current = get_career_assist_standing_consent(customer_number)
        if current.get("event_type") != "GRANT":
            print("CAREER ASSIST STANDING CONSENT REVOKE: no_active_grant", flush=True)
            return (
                "There is no active standing application authorization recorded for your Career Assist. "
                "I will not submit future applications on standing authority. Vacancy recommendations can continue."
            )
        lead_id = current.get("lead_id")
        if not lead_id:
            try:
                lead_id = get_career_assist_lifecycle_state(customer_number).get("lead_id")
            except Exception:
                lead_id = None
        event = _record_career_assist_consent_event(customer_number, lead_id, "REVOKE")
        print(
            f"CAREER ASSIST STANDING CONSENT REVOKED: event={event['event_id']} lead={lead_id}",
            flush=True,
        )
        return (
            "Your standing Career Assist application authorization has been revoked. "
            "IBROWS must not submit future job applications on your behalf under that standing authority. "
            "You can still receive vacancy recommendations and ask for help with individual applications. "
            "This does not withdraw any application that may already have been submitted."
        )

    if detect_career_assist_standing_consent_grant(customer_message):
        state = get_career_assist_lifecycle_state(customer_number)
        if state.get("state") != "ACTIVE":
            print(
                f"CAREER ASSIST STANDING CONSENT NOT ACTIVATED: lifecycle={state.get('state')}",
                flush=True,
            )
            return (
                "I can record standing application authorization only while Career Assist is active. "
                "Your instruction has not been activated as standing consent."
            )
        event = _record_career_assist_consent_event(
            customer_number,
            state.get("lead_id"),
            "GRANT",
            customer_message,
        )
        print(
            f"CAREER ASSIST STANDING CONSENT GRANTED: event={event['event_id']} lead={state.get('lead_id')}",
            flush=True,
        )
        return (
            "Your standing Career Assist application authorization has been recorded for the exact scope you provided. "
            "IBROWS may use only your verified information within that scope. New or sensitive declarations that are not already verified still require your confirmation. "
            "This authorization does not mean any application has been submitted, and the assistant must not claim submission unless a real submission is confirmed. "
            "You can revoke this standing authorization at any time without stopping vacancy recommendations."
        )
    return None


def detect_career_assist_vacancy_search_request(customer_message):
    """Detect job/vacancy discovery requests that belong to an ACTIVE Career Assist term.

    Discovery language such as "find me jobs I can apply for" is not itself a request
    to submit one specific application. Keeping this distinction prevents the MK5,000
    Single Job Application gate from charging an active Career Assist customer merely
    for asking IBROWS to search for opportunities included in the monthly service.
    """
    text = " ".join(str(customer_message or "").lower().split())
    if not text:
        return False

    # Standing-consent instructions can contain phrases such as "jobs in Malawi".
    # They are authorization changes, not vacancy-discovery requests.
    if (
        detect_career_assist_standing_consent_grant(customer_message)
        or detect_career_assist_standing_consent_revoke(customer_message)
    ):
        return False

    # A mixed "find/search a vacancy and then apply/proceed" request is discovery-first
    # because no exact vacancy exists yet. Check this before the single-application phrases
    # below so wording such as "find a verified Strong Fit job ... and proceed with the
    # application" cannot be misrouted as an already-identified application.
    if detect_career_assist_future_vacancy_apply_request(customer_message):
        return True

    # Explicit execution of one already-identified vacancy is not discovery.
    explicit_single_execution = any(phrase in text for phrase in (
        "apply for this job", "apply to this job", "submit this application",
        "submit my application", "proceed with this application",
        "continue this application", "start this application",
        "apply for the first one", "apply for the second one", "apply for the third one",
    ))
    if explicit_single_execution:
        return False

    discovery_markers = (
        "find me", "find jobs", "find vacancies", "find opportunities",
        "find a job", "find a vacancy", "find a role", "find an opportunity",
        "find a verified", "find a strong fit", "find verified", "find strong fit",
        "find for me", "you find for me", "find and apply", "search and apply",
        "search for", "search jobs", "search vacancies", "look for",
        "show me jobs", "show me vacancies", "current jobs", "current vacancies",
        "open jobs", "open vacancies", "job openings", "available jobs",
        "available vacancies", "jobs in", "vacancies in", "opportunities in",
        "remote jobs", "remote roles", "roles in",
        "next verified", "next suitable", "next strong fit", "next matching",
    )
    job_markers = ("job", "jobs", "vacancy", "vacancies", "role", "roles", "opportunit")
    return any(marker in text for marker in discovery_markers) and any(marker in text for marker in job_markers)


def detect_career_assist_future_vacancy_apply_request(customer_message):
    """Detect a find-then-apply request for a vacancy that is not identified yet.

    Discovery happens first. After standing consent is revoked, this wording must not
    silently restore standing authority or fall into the standalone MK5,000 payment gate.
    """
    text = " ".join(str(customer_message or "").lower().split())
    if not text:
        return False
    if (
        detect_career_assist_standing_consent_grant(customer_message)
        or detect_career_assist_standing_consent_revoke(customer_message)
    ):
        return False
    job_target = any(marker in text for marker in (
        "job", "jobs", "vacancy", "vacancies", "role", "roles", "position",
        "opportunity", "opportunities", "data analyst", "business intelligence",
        "it/business systems", "digital solutions",
    ))
    apply_intent = any(marker in text for marker in (
        "apply for", "apply to", "submit an application", "submit applications",
        "apply on my behalf", "application for", "proceed with the application",
        "proceed with application", "proceed to apply", "continue with the application",
        "go ahead with the application", "go ahead and apply",
    )) or (
        "proceed" in text and "application" in text
    )
    explicit_future_target = any(marker in text for marker in (
        "next verified", "next suitable", "next strong fit", "next matching",
        "next vacancy", "next job", "next role", "you find for me",
        "find for me", "find and apply", "search and apply",
        "find a verified", "find a strong fit", "find verified", "find strong fit",
        "find a job", "find a vacancy", "find a role", "find an opportunity",
    ))
    discovery_verb = any(marker in text for marker in (
        "find ", "search ", "search for ", "look for ", "show me ",
    ))
    future_target = explicit_future_target or (discovery_verb and job_target)
    return apply_intent and future_target and job_target


def detect_single_job_application_request(customer_message):
    """Detect execution of one identified application without confusing it with discovery/CV work."""
    text = " ".join(str(customer_message or "").lower().split())
    if not text:
        return False
    if (
        detect_career_assist_standing_consent_grant(customer_message)
        or detect_career_assist_standing_consent_revoke(customer_message)
    ):
        return False
    if any(term in text for term in ("cv and cover letter", "cv & cover letter", "application pack")):
        return False
    exact_or_named = any(phrase in text for phrase in (
        "single job application", "one job application", "job application assistance",
        "apply for one job", "apply for this job", "apply to this job",
        "apply for vacancy", "apply to vacancy", "apply for role", "apply to role",
        "apply for the first one", "apply for the second one", "apply for the third one",
        "apply for vacancy 1", "apply for vacancy 2", "apply for vacancy 3",
        "proceed with my job application", "continue my job application",
        "start my job application", "submit my job application", "submit this application",
    ))
    action_word = any(word in text for word in (
        "apply", "application", "proceed", "continue", "start", "submit"
    ))
    target_word = any(word in text for word in (
        "job", "vacancy", "role", "position"
    ))
    action_job = action_word and target_word and any(word in text for word in ("apply", "application", "submit"))
    return exact_or_named or action_job


def detect_explicit_single_job_service_purchase_request(customer_message):
    """Detect a deliberate purchase/selection of the standalone MK5,000 service.

    This is intentionally narrower than ``detect_single_job_application_request``.
    An ACTIVE Career Assist customer saying "apply for this job" remains inside
    Career Assist, while a customer explicitly asking for the named standalone
    service/package is routed to its own ledger/payment gate.
    """
    text = " ".join(str(customer_message or "").lower().split())
    if not text:
        return False
    # Do not reinterpret discovery/execution wording as a new purchase merely because
    # it contains the words "job application". The customer must name/select the service.
    named_service = any(phrase in text for phrase in (
        "single job application service",
        "single job application package",
        "single job application",
        "one job application service",
        "one-off job application service",
    ))
    selection_intent = any(phrase in text for phrase in (
        "i want", "i need", "i would like", "i'd like", "buy", "purchase",
        "choose", "select", "take", "get the", "get a", "sign me up",
        "interested in", "pay for", "use the", "use your",
    ))
    # Exact naming of the official service is itself a sufficiently explicit selection
    # when presented as a standalone request, e.g. "Single Job Application service".
    service_word = "service" in text or "package" in text
    return named_service and (selection_intent or service_word)


def _application_pack_message_is_trivial(customer_message):
    raw = str(customer_message or "").strip()
    text = " ".join(raw.lower().split())
    compact = re.sub(r"[^a-z0-9]+", " ", text).strip()
    return compact in {
        "hi", "hello", "hey", "hie", "morning", "good morning",
        "afternoon", "good afternoon", "evening", "good evening",
        "thanks", "thank you", "thankyou", "okay", "ok", "alright",
        "cool", "noted", "great", "fine", "bye", "goodbye",
        "menu", "main menu", "services", "help",
    }


def is_simple_social_greeting(customer_message):
    """Return True only for a standalone greeting with no business instruction.

    This deliberately runs before the language model so old conversation context cannot
    turn "Hello" into a stale Career Assist action or a false Talk-to-Jones referral.
    Mixed messages such as "hello, I need cleaning" are not swallowed here.
    """
    raw = str(customer_message or "").strip()
    compact = re.sub(r"[^a-z0-9]+", " ", raw.lower()).strip()
    return compact in {
        "hi", "hello", "hey", "hie", "hello there", "hi there", "hey there",
        "morning", "good morning", "good morning ibrows",
        "afternoon", "good afternoon", "good afternoon ibrows",
        "evening", "good evening", "good evening ibrows",
        "hello ibrows", "hi ibrows", "hey ibrows",
    }


def simple_social_greeting_reply():
    return (
        "Hello! Welcome to IBROWS Enterprise 👋 How may we help you today? "
        "Type MENU anytime to see our services."
    )


def _reply_has_unbacked_handover_claim(reply):
    """Detect strong claims that a human/Jones handover has already happened.

    A model may discuss the option of human help.  What is blocked here are completion
    claims such as "has been referred" or "Jones has been notified" when the backend
    did not create that handover in the same turn.
    """
    text = " ".join(str(reply or "").lower().split())
    markers = (
        "request to speak with jones has been referred",
        "request to talk to jones has been referred",
        "request to speak to jones has been referred",
        "jones has been notified",
        "jones has been informed",
        "ibrows team has been notified",
        "ibrows team has been informed",
        "has been referred to the ibrows team",
        "i have referred you to jones",
        "i've referred you to jones",
        "i have notified jones",
        "i've notified jones",
    )
    return any(marker in text for marker in markers)


def _one_off_pack_continuation_allowed(customer_number, customer_message):
    """Protect an active one-off CV pack from unrelated-message regeneration."""
    raw = str(customer_message or "").strip()
    if not raw or _application_pack_message_is_trivial(raw):
        if raw:
            print("ONE-OFF PACK CONTINUATION BLOCKED — NON-ACTION MESSAGE", flush=True)
        return False
    if detect_application_pack_request(raw):
        return True
    try:
        recent = get_recent_conversation(customer_number, limit=6)
    except Exception as error:
        print(f"ONE-OFF PACK CONTINUATION CONVERSATION CHECK FAILED: {type(error).__name__}", flush=True)
        return False
    previous_assistant = ""
    for item in reversed(recent or []):
        if str(item.get("role") or "").lower() == "assistant":
            previous_assistant = str(item.get("content") or "").strip()
            break
    prior = previous_assistant.lower()
    asks_for_input = (
        "?" in previous_assistant
        or any(marker in prior for marker in (
            "please confirm", "please provide", "please send", "please tell me",
            "i need", "need your", "missing information", "before i can prepare",
            "before preparation", "what is your", "which",
        ))
    )
    pack_specific = any(marker in prior for marker in (
        "cv", "cover letter", "application pack", "application", "vacancy",
        "job", "role", "employer", "qualification", "experience",
    ))
    allowed = bool(asks_for_input and pack_specific)
    if not allowed:
        print("ONE-OFF PACK CONTINUATION BLOCKED — NO PENDING PACK QUESTION", flush=True)
    return allowed


def _career_assist_pack_continuation_allowed(customer_number, customer_message):
    """Return True only when an existing Career Assist pack should resume.

    A stale workflow flag must never turn a greeting, thanks, menu request or unrelated
    message into an expensive application-pack regeneration.  Explicit preparation or
    application instructions may resume directly.  Short answers are accepted only while
    the latest application is genuinely waiting for information and the immediately
    preceding assistant message contains an application-specific question/request.
    Draft-ready applications require an explicit revision/preparation instruction.
    """
    raw = str(customer_message or "").strip()
    text = " ".join(raw.lower().split())
    if not text:
        return False

    if _application_pack_message_is_trivial(raw):
        print("CAREER ASSIST STALE PACK CONTINUATION BLOCKED — NON-ACTION MESSAGE", flush=True)
        return False

    # These are genuine user instructions to work on the selected application.
    explicit_revision = (
        any(word in text for word in ("revise", "revision", "edit", "correct", "fix", "change", "update", "redo", "regenerate"))
        and any(term in text for term in ("cv", "cover letter", "application", "draft"))
    )
    if explicit_revision or detect_career_assist_preparation_request(raw) or detect_career_assist_application_request(raw):
        return True

    # Read only the most recent application state. Completed/ready work must never
    # restart merely because application_pack_state.active was left behind by an older build.
    try:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT status
                    FROM career_assist_applications
                    WHERE customer_number=%s
                    ORDER BY updated_at DESC, id DESC
                    LIMIT 1
                    """,
                    (customer_number,),
                )
                row = cur.fetchone()
        latest_status = str(row[0] or "").upper() if row else ""
    except Exception as error:
        print(f"CAREER ASSIST CONTINUATION STATE CHECK FAILED: {type(error).__name__}", flush=True)
        return False

    if latest_status in {"DRAFT_READY", "SUBMITTED", "CANCELLED"}:
        print(f"CAREER ASSIST STALE PACK CONTINUATION BLOCKED — STATUS={latest_status or 'UNKNOWN'}", flush=True)
        return False
    if latest_status not in {"PREPARING", "NEEDS_INFO"}:
        return False

    # Allow a concise answer (for example "Yes", a date, phone number or short fact)
    # only when IBROWS actually asked an application-specific question immediately before it.
    try:
        recent = get_recent_conversation(customer_number, limit=6)
    except Exception as error:
        print(f"CAREER ASSIST CONTINUATION CONVERSATION CHECK FAILED: {type(error).__name__}", flush=True)
        return False
    previous_assistant = ""
    for item in reversed(recent or []):
        if str(item.get("role") or "").lower() == "assistant":
            previous_assistant = str(item.get("content") or "").strip()
            break
    prior = previous_assistant.lower()
    asks_for_input = (
        "?" in previous_assistant
        or any(marker in prior for marker in (
            "please confirm", "please provide", "please send", "please tell me",
            "i need", "need your", "missing information", "before i can prepare",
            "before preparation", "which of", "what is your", "when can you",
        ))
    )
    application_specific = any(marker in prior for marker in (
        "application", "vacancy", "job", "role", "cv", "cover letter",
        "employer", "qualification", "experience", "availability", "salary",
        "work authorisation", "work authorization", "declaration",
    ))
    allowed = bool(asks_for_input and application_specific)
    if not allowed:
        print("CAREER ASSIST STALE PACK CONTINUATION BLOCKED — NO PENDING APPLICATION QUESTION", flush=True)
    return allowed


def detect_career_assist_application_request(customer_message):
    """Detect a specific-vacancy application request covered by active Career Assist.

    This detector intentionally accepts ordinary wording such as "proceed with the verified
    QED vacancy" as well as explicit "apply for this job" wording. A customer with an ACTIVE
    Career Assist term must not be pushed into the standalone MK5,000 gate merely because the
    sentence does not match one narrow phrase. Find-then-apply requests for a vacancy that is
    not identified yet remain discovery-first and are handled separately.
    """
    text = " ".join(str(customer_message or "").lower().split())
    if not text:
        return False
    if (
        detect_career_assist_standing_consent_grant(customer_message)
        or detect_career_assist_standing_consent_revoke(customer_message)
    ):
        return False

    # A request for a future/not-yet-identified vacancy must search first.
    if detect_career_assist_future_vacancy_apply_request(customer_message):
        return False
    if detect_career_assist_vacancy_search_request(customer_message):
        return False

    application_intent = any(phrase in text for phrase in (
        "i want to apply", "want to apply", "apply for vacancy", "apply to vacancy",
        "apply for this job", "apply to this job", "apply for this role", "apply to this role",
        "apply for the first one", "apply for the second one", "apply for the third one",
        "proceed with this application", "proceed with my application",
        "proceed with the verified", "proceed with verified", "proceed with the vacancy",
        "continue this application", "continue with the application", "start this application",
        "submit this application", "submit the application", "using my standing application authorization",
        "using my standing application authorisation", "use my standing application authorization",
        "use my standing application authorisation", "before anything is submitted", "before submission",
    ))
    target_hint = any(term in text for term in (
        "vacancy", "job", "role", "position", "first one", "second one", "third one",
        "vacancy 1", "vacancy 2", "vacancy 3", "role 1", "role 2", "role 3",
    ))

    # Generic action + a specific vacancy/job target is also enough. This catches natural
    # variants such as "Under my active Career Assist, proceed with the verified QED.ai
    # Data Analyst – Lilongwe vacancy" without weakening discovery-first handling above.
    action_word = any(word in text for word in ("apply", "proceed", "continue", "start", "submit"))
    specific_target = target_hint and not any(marker in text for marker in (
        "next vacancy", "next job", "next role", "next verified", "next suitable",
        "next strong fit", "next matching", "you find for me", "find for me",
    ))
    return (application_intent and target_hint) or (action_word and specific_target)


def _v51_specific_career_apply_request(customer_message):
    """Detect an instruction to act on one already-identified vacancy.

    This is intentionally broader than the older Career Assist detector so natural
    wording such as "Apply for the Data Analyst – Lilongwe job" cannot fall
    through to the general AI path. Discovery/find-next wording is excluded.
    """
    text = " ".join(str(customer_message or "").lower().replace("–", "-").replace("—", "-").split())
    if not text:
        return False
    if detect_explicit_single_job_service_purchase_request(customer_message):
        return False
    if detect_career_assist_submission_approval_request(customer_message):
        return False
    if detect_career_assist_future_vacancy_apply_request(customer_message):
        return False
    discovery = any(marker in text for marker in (
        "find me", "find a job", "find a vacancy", "search jobs", "search vacancies",
        "look for", "show me jobs", "next vacancy", "next job", "next role",
        "next verified", "next suitable", "next strong fit", "next matching",
    ))
    if discovery:
        return False
    action = any(marker in text for marker in (
        "apply for", "apply to", "proceed with", "continue with",
        "continue this", "start this", "work on this", "prepare this application",
    ))
    target = any(marker in text for marker in (
        " job", " vacancy", " role", " position", " application",
        "data analyst", "business intelligence", "digital solutions",
    ))
    return bool(action and target)


def _v51_generic_affirmation(customer_message):
    text = " ".join(str(customer_message or "").lower().split()).strip(" .!?")
    return text in {
        "yes", "yes please", "okay", "ok", "sure", "go ahead", "proceed",
        "do it", "approved", "i agree", "i approve",
    }


def _v51_previous_assistant_requires_specific_submission_approval(customer_number):
    try:
        recent = get_recent_conversation(customer_number, limit=6)
    except Exception as error:
        print(f"V51 APPROVAL CONTEXT CHECK FAILED: {type(error).__name__}", flush=True)
        return False
    previous_assistant = ""
    for item in reversed(recent or []):
        if str(item.get("role") or "").lower() == "assistant":
            previous_assistant = str(item.get("content") or "").strip().lower()
            break
    return (
        "explicit instruction" in previous_assistant
        and "submission" in previous_assistant
        and "nothing has been submitted" in previous_assistant
    ) or (
        "i approve submission for" in previous_assistant
        and "proceed to submission" in previous_assistant
    )


def ensure_cv_package_lead(customer_number, customer_name):
    """Create/update the paid CV package lead and attach its approved MK7,500 value."""
    lead_id, is_new = create_or_update_lead(
        customer_number=customer_number,
        customer_name=customer_name,
        service="CV & Cover Letter",
        summary="Customer requested the One-Off CV + Cover Letter package; payment verification is required before paid document preparation.",
        handover_reason="Payment verification required before paid CV + Cover Letter work begins.",
    )
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE leads
                SET estimated_value = COALESCE(estimated_value, %s),
                    value_currency = CASE WHEN estimated_value IS NULL THEN 'MWK' ELSE value_currency END,
                    quote_status = CASE
                        WHEN quote_status IN ('NOT_STARTED', 'DRAFT') THEN 'ACCEPTED'
                        ELSE quote_status
                    END,
                    updated_at = NOW()
                WHERE id = %s
                """,
                (CAREER_SERVICE_DEFAULT_PRICES_MWK["CV & Cover Letter"], lead_id),
            )
        conn.commit()
    if is_new:
        try:
            send_new_lead_email(
                lead_id=lead_id,
                customer_name=customer_name,
                customer_number=customer_number,
                service="CV & Cover Letter",
                summary="Customer requested the One-Off CV + Cover Letter package; payment verification is required.",
                handover_reason="Payment verification required before paid CV + Cover Letter work begins.",
            )
        except Exception as notify_error:
            print(f"CV PAYMENT LEAD NOTIFICATION ERROR: {type(notify_error).__name__}", flush=True)
    return lead_id


def application_pack_payment_gate(customer_number, customer_name):
    """Return None when paid; otherwise return a truthful payment-gate reply."""
    required = CAREER_SERVICE_DEFAULT_PRICES_MWK["CV & Cover Letter"]
    state = get_verified_service_payment_state(
        customer_number, "CV & Cover Letter", required
    )
    if state["status"] == "PAID":
        return None

    # A direct request to prepare the paid pack is enough to create a real admin
    # follow-up record; no customer-facing claim of referral is made without it.
    try:
        ensure_cv_package_lead(customer_number, customer_name)
        state = get_verified_service_payment_state(
            customer_number, "CV & Cover Letter", required
        )
    except Exception as gate_error:
        print(f"CV PAYMENT GATE LEAD ERROR: {type(gate_error).__name__}", flush=True)

    channels = approved_payment_channels_text()
    if state["status"] == "PART_PAID":
        balance = state["balance"] if state["balance"] is not None else required - state["paid"]
        return (
            f"Your One-Off CV + Cover Letter package is MK{required:,.0f}. "
            f"The IBROWS ledger currently shows MK{state['paid']:,.0f} verified, "
            f"with MK{balance:,.0f} remaining. Paid document preparation starts only "
            "after the full package payment is verified, unless an authorized IBROWS "
            "admin records an approved exception.\n\n"
            "Approved payment channels:\n" + channels +
            "\n\nAfter payment, send the transaction reference or payment confirmation. "
            "Do not send your PIN, OTP, password, or security codes."
        )

    return (
        f"The One-Off CV + Cover Letter package costs MK{required:,.0f}. "
        "I can prepare the paid documents after payment has been verified in the "
        "IBROWS ledger. A screenshot or customer message by itself does not mark a "
        "payment as confirmed.\n\nApproved payment channels:\n" + channels +
        "\n\nAfter payment, send the transaction reference or payment confirmation for "
        "IBROWS verification. Do not send your PIN, OTP, password, or security codes."
    )


def consume_cv_package_entitlement(customer_number):
    """Consume exactly one fully-paid One-Off CV + Cover Letter entitlement.

    This runs only after the generated documents have been delivered successfully.
    The payment rows stay untouched for finance/audit history, while the service lead
    is closed and permanently marked consumed so reopening the lead cannot reuse the
    same MK15,000 payment for another application pack.
    """
    required = CAREER_SERVICE_DEFAULT_PRICES_MWK["CV & Cover Letter"]

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT l.id, l.service, l.estimated_value,
                       COALESCE(l.value_currency, 'MWK'),
                       COALESCE((
                           SELECT SUM(p.amount)
                           FROM lead_payments p
                           WHERE p.lead_id = l.id
                             AND p.currency = COALESCE(l.value_currency, 'MWK')
                       ), 0) AS paid_total
                FROM leads l
                WHERE l.customer_number = %s
                  AND l.status IN ('NEW', 'CONTACTED')
                  AND l.merged_into_lead_id IS NULL
                  AND l.privacy_deleted_at IS NULL
                  AND l.entitlement_consumed_at IS NULL
                ORDER BY l.updated_at DESC, l.id DESC
                FOR UPDATE OF l
                """,
                (customer_number,),
            )
            rows = cur.fetchall()

            selected = None
            for row in rows:
                if canonicalize_service(row[1]) == "CV & Cover Letter":
                    selected = row
                    break

            if not selected:
                raise ValueError("No active CV + Cover Letter entitlement found to consume.")

            lead_id, _service, estimated_value, currency, paid_total = selected
            paid_total = Decimal(paid_total or 0)
            service_value = Decimal(estimated_value) if estimated_value is not None else required

            if currency != "MWK":
                raise ValueError("CV + Cover Letter entitlement currency is not MWK.")
            if service_value < required:
                service_value = required
            if paid_total < service_value:
                raise ValueError("CV + Cover Letter entitlement is not fully paid.")

            reason = (
                "One-Off CV + Cover Letter entitlement consumed after successful "
                "WhatsApp delivery of the purchased application pack."
            )
            cur.execute(
                """
                UPDATE leads
                SET entitlement_consumed_at = NOW(),
                    entitlement_consumed_reason = %s,
                    status = 'CLOSED',
                    follow_up_at = NULL,
                    follow_up_notified_at = NULL,
                    follow_up_notification_claimed_at = NULL,
                    follow_up_notification_error = NULL,
                    updated_at = NOW()
                WHERE id = %s
                  AND entitlement_consumed_at IS NULL
                """,
                (reason, lead_id),
            )
            if cur.rowcount != 1:
                raise ValueError("CV + Cover Letter entitlement was already consumed.")

            _activity_insert(
                cur,
                lead_id,
                "SERVICE_CONSUMED",
                "One-Off CV + Cover Letter package completed and entitlement consumed after successful document delivery.",
            )

        conn.commit()

    print(f"CV PACKAGE ENTITLEMENT CONSUMED: lead={lead_id}", flush=True)
    return lead_id



def complete_single_job_application_entitlement(lead_id):
    """Mark one paid Single Job Application as submitted/completed.

    This is an explicit admin action used only after IBROWS has actually submitted
    the application to the employer. Payment rows remain untouched for finance and
    audit history. The service lead is permanently marked consumed and closed so
    the same MK5,000 payment cannot unlock another job application.
    """
    required = CAREER_SERVICE_DEFAULT_PRICES_MWK["Single Job Application"]

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT l.customer_number, l.service, l.status,
                       l.entitlement_consumed_at, l.estimated_value,
                       COALESCE(l.value_currency, 'MWK'),
                       COALESCE((
                           SELECT SUM(p.amount)
                           FROM lead_payments p
                           WHERE p.lead_id = l.id
                             AND p.currency = COALESCE(l.value_currency, 'MWK')
                       ), 0) AS paid_total
                FROM leads l
                WHERE l.id = %s
                  AND l.merged_into_lead_id IS NULL
                  AND l.privacy_deleted_at IS NULL
                FOR UPDATE OF l
                """,
                (lead_id,),
            )
            row = cur.fetchone()
            if not row:
                raise ValueError("Single Job Application lead not found.")

            (customer_number, service, status, consumed_at, estimated_value,
             currency, paid_total) = row

            if canonicalize_service(service) != "Single Job Application":
                raise ValueError("Lead is not a Single Job Application service.")

            # Make repeated/double taps harmless after a successful completion.
            if consumed_at is not None:
                return {"lead_id": lead_id, "already_completed": True}

            paid_total = Decimal(paid_total or 0)
            # Honor a fully paid pre-V108 quote while all new purchases use the
            # current fixed price. This prevents a price change from invalidating
            # an entitlement the customer already paid for.
            service_value = _effective_fixed_service_price(
                "Single Job Application", estimated_value, paid_total
            )

            if currency != "MWK":
                raise ValueError("Single Job Application entitlement currency is not MWK.")
            if paid_total < service_value:
                raise ValueError("Single Job Application entitlement is not fully paid.")

            reason = (
                "Single Job Application entitlement consumed after an IBROWS admin "
                "confirmed that the purchased application was submitted to the employer."
            )
            cur.execute(
                """
                UPDATE leads
                SET entitlement_consumed_at = NOW(),
                    entitlement_consumed_reason = %s,
                    status = 'CLOSED',
                    handover_reason = %s,
                    follow_up_at = NULL,
                    follow_up_notified_at = NULL,
                    follow_up_notification_claimed_at = NULL,
                    follow_up_notification_error = NULL,
                    updated_at = NOW()
                WHERE id = %s
                  AND entitlement_consumed_at IS NULL
                """,
                (
                    reason,
                    "Application submitted to the employer; Single Job Application service completed.",
                    lead_id,
                ),
            )
            if cur.rowcount != 1:
                return {"lead_id": lead_id, "already_completed": True}

            cur.execute(
                """
                INSERT INTO lead_notes (lead_id, note_text)
                VALUES (%s, %s)
                """,
                (
                    lead_id,
                    "Admin confirmed employer submission. Single Job Application completed and entitlement consumed.",
                ),
            )
            _activity_insert(
                cur,
                lead_id,
                "SERVICE_CONSUMED",
                "Single Job Application completed after confirmed employer submission; MK3,000 entitlement consumed.",
            )

        conn.commit()

    print(
        f"SINGLE JOB APPLICATION ENTITLEMENT CONSUMED: lead={lead_id} customer={customer_number}",
        flush=True,
    )
    return {"lead_id": lead_id, "already_completed": False}


def create_or_update_lead(
    customer_number,
    customer_name,
    service,
    summary,
    handover_reason
):
    service = canonicalize_service(service)

    with get_db() as conn:
        with conn.cursor() as cur:

            cur.execute(
                """
                SELECT id, service
                FROM leads
                WHERE customer_number = %s
                  AND status IN ('NEW', 'CONTACTED')
                  AND merged_into_lead_id IS NULL
                  AND privacy_deleted_at IS NULL
                  AND entitlement_consumed_at IS NULL
                ORDER BY updated_at DESC, created_at DESC
                """,
                (customer_number,)
            )

            existing = None
            for candidate_id, candidate_service in cur.fetchall():
                if canonicalize_service(candidate_service).casefold() == service.casefold():
                    existing = (candidate_id,)
                    break

            if existing:
                lead_id = existing[0]

                cur.execute(
                    """
                    UPDATE leads
                    SET customer_name = COALESCE(
                            NULLIF(%s, ''),
                            customer_name
                        ),
                        service = %s,
                        summary = %s,
                        handover_reason = %s,
                        updated_at = NOW()
                    WHERE id = %s
                    """,
                    (
                        customer_name,
                        service,
                        summary,
                        handover_reason,
                        lead_id
                    )
                )

                _activity_insert(
                    cur,
                    lead_id,
                    "AI_UPDATE",
                    "Lead details refreshed from the WhatsApp conversation.",
                )

                print(
                    f"LEAD UPDATED: {lead_id}",
                    flush=True
                )

            else:
                cur.execute(
                    """
                    INSERT INTO leads (
                        customer_number,
                        customer_name,
                        service,
                        summary,
                        handover_reason
                    )
                    VALUES (%s, %s, %s, %s, %s)
                    RETURNING id
                    """,
                    (
                        customer_number,
                        customer_name,
                        service,
                        summary,
                        handover_reason
                    )
                )

                lead_id = cur.fetchone()[0]

                _activity_insert(
                    cur,
                    lead_id,
                    "LEAD_CREATED",
                    f"{service} lead created from WhatsApp.",
                )

                print(
                    f"NEW LEAD CREATED: {lead_id}",
                    flush=True
                )

        conn.commit()

    return lead_id, existing is None


def record_lead_notification(lead_id, status, error=None):
    """Persist notification delivery state without storing API secrets."""
    try:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO lead_notification_status
                        (lead_id, status, attempts, last_error, updated_at)
                    VALUES (%s, %s, 1, %s, NOW())
                    ON CONFLICT (lead_id) DO UPDATE SET
                        status=EXCLUDED.status,
                        attempts=lead_notification_status.attempts + 1,
                        last_error=EXCLUDED.last_error,
                        updated_at=NOW()
                    """,
                    (lead_id, status, error)
                )
            conn.commit()
    except Exception as tracking_error:
        print(
            f"Lead notification tracking error: {type(tracking_error).__name__}",
            flush=True
        )


def send_human_handover_alert_email(
    lead_id,
    customer_name,
    customer_number,
    service,
    handover_reason,
):
    """Send Jones an immediate email when a customer requests human takeover."""
    if not BREVO_API_KEY or not NOTIFICATION_EMAIL or not BREVO_SENDER_EMAIL:
        print(
            "Human handover alert skipped: Brevo API settings are not fully configured.",
            flush=True,
        )
        if lead_id:
            record_lead_notification(lead_id, "FAILED", "Brevo configuration incomplete")
        return False

    display_name = customer_name or "Not provided"
    subject = f"Jones requested — IBROWS customer +{customer_number}"
    body = f"""A customer has requested Jones and the AI assistant has been paused for this conversation.

Customer: {display_name}
WhatsApp: +{customer_number}
Service: {service}
Lead ID: {lead_id}

Reason:
{handover_reason}

Open the IBROWS Inbox to continue the conversation:
{LEAD_DASHBOARD_URL.rsplit('/admin/leads', 1)[0]}/admin/inbox/{customer_number}

IBROWS Enterprise
Kupanga zofanana, mosiyana
"""

    payload = {
        "sender": _brevo_sender_payload("INFO"),
        "replyTo": _brevo_reply_to_payload("INFO"),
        "to": [{"email": NOTIFICATION_EMAIL}],
        "subject": subject,
        "textContent": body,
    }

    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={
                "accept": "application/json",
                "api-key": BREVO_API_KEY,
                "content-type": "application/json",
            },
            json=payload,
            timeout=8,
        )
        if 200 <= response.status_code < 300:
            if lead_id:
                record_lead_notification(lead_id, "SENT")
            print(
                f"HUMAN HANDOVER ALERT EMAIL SENT: lead={lead_id} customer={customer_number}",
                flush=True,
            )
            return True

        error_label = f"Brevo HTTP {response.status_code}"
        if lead_id:
            record_lead_notification(lead_id, "FAILED", error_label)
        print(
            f"HUMAN HANDOVER ALERT EMAIL FAILED: lead={lead_id} — {error_label}",
            flush=True,
        )
        return False
    except requests.RequestException as error:
        error_label = type(error).__name__
        if lead_id:
            record_lead_notification(lead_id, "FAILED", error_label)
        print(
            f"HUMAN HANDOVER ALERT EMAIL FAILED: lead={lead_id} — {error_label}",
            flush=True,
        )
        return False


