def claim_due_follow_up_reminders(limit=20):
    """
    Atomically claim due follow-ups. Stale claims older than 15 minutes are
    recoverable so a crashed worker cannot permanently suppress a reminder.
    """
    limit = max(1, min(int(limit), 50))
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    id,
                    customer_number,
                    customer_name,
                    service,
                    summary,
                    priority,
                    follow_up_at
                FROM leads
                WHERE status <> 'CLOSED'
                  AND privacy_deleted_at IS NULL
                  AND follow_up_at IS NOT NULL
                  AND follow_up_at <= NOW()
                  AND follow_up_notified_at IS NULL
                  AND (
                        follow_up_notification_claimed_at IS NULL
                        OR follow_up_notification_claimed_at
                           < NOW() - INTERVAL '15 minutes'
                  )
                ORDER BY follow_up_at ASC
                LIMIT %s
                FOR UPDATE SKIP LOCKED
                """,
                (limit,)
            )
            rows = cur.fetchall()

            for row in rows:
                cur.execute(
                    """
                    UPDATE leads
                    SET follow_up_notification_claimed_at = NOW(),
                        follow_up_notification_error = NULL
                    WHERE id = %s
                      AND follow_up_notified_at IS NULL
                      AND merged_into_lead_id IS NULL
                    """,
                    (row[0],)
                )
        conn.commit()

    return [
        {
            "id": row[0],
            "customer_number": row[1],
            "customer_name": row[2],
            "service": canonicalize_service(row[3]),
            "summary": row[4],
            "priority": row[5] or "NORMAL",
            "follow_up_at": row[6],
        }
        for row in rows
    ]


def finish_follow_up_reminder(lead_id, success, error=None):
    with get_db() as conn:
        with conn.cursor() as cur:
            if success:
                cur.execute(
                    """
                    UPDATE leads
                    SET follow_up_notified_at = NOW(),
                        follow_up_notification_claimed_at = NULL,
                        follow_up_notification_error = NULL
                    WHERE id = %s
                    """,
                    (lead_id,)
                )
                _activity_insert(
                    cur,
                    lead_id,
                    "REMINDER",
                    "Follow-up email reminder sent to IBROWS.",
                )
            else:
                cur.execute(
                    """
                    UPDATE leads
                    SET follow_up_notification_claimed_at = NULL,
                        follow_up_notification_error = %s
                    WHERE id = %s
                    """,
                    (str(error or "Unknown reminder error")[:500], lead_id)
                )
        conn.commit()


def send_follow_up_reminder_email(lead):
    if not BREVO_API_KEY or not NOTIFICATION_EMAIL or not BREVO_SENDER_EMAIL:
        return False, "Brevo configuration incomplete"

    follow_up_local = lead["follow_up_at"].astimezone(ADMIN_TIMEZONE)
    display_name = lead.get("customer_name") or "WhatsApp Customer"
    customer_number = lead.get("customer_number") or ""
    service = lead.get("service") or "General Enquiry"
    priority = lead.get("priority") or "NORMAL"
    summary = lead.get("summary") or "No summary available."

    subject = f"IBROWS Follow-up Due: {display_name} — {service}"
    body = f"""IBROWS customer follow-up is now due.

Lead ID: {lead['id']}
Customer: {display_name}
WhatsApp: +{customer_number}
Service: {service}
Priority: {priority}
Scheduled follow-up: {follow_up_local.strftime('%d %B %Y at %H:%M')} Malawi time

Lead summary:
{summary}

Open WhatsApp:
https://wa.me/{customer_number}

Lead dashboard:
{LEAD_DASHBOARD_URL}

IBROWS Enterprise
Kupanga zofanana, mosiyana
"""

    payload = {
        "sender": _brevo_sender_payload("INFO"),
        "replyTo": _brevo_reply_to_payload("INFO"),
        "to": [{"email": NOTIFICATION_EMAIL}],
        "subject": subject,
        "textContent": body,
    }

    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={
                "accept": "application/json",
                "api-key": BREVO_API_KEY,
                "content-type": "application/json",
            },
            json=payload,
            timeout=10,
        )
        if 200 <= response.status_code < 300:
            print(f"FOLLOW-UP REMINDER EMAIL SENT: {lead['id']}", flush=True)
            return True, None

        error = f"Brevo HTTP {response.status_code}"
        print(
            f"FOLLOW-UP REMINDER EMAIL FAILED: {lead['id']} — {error}",
            flush=True,
        )
        return False, error
    except Exception as error:
        label = f"{type(error).__name__}: {str(error)[:180]}"
        print(
            f"FOLLOW-UP REMINDER EMAIL FAILED: {lead['id']} — {label}",
            flush=True,
        )
        return False, label



def claim_due_invoice_reminders(limit=20):
    """Claim admin-only reminders for immutable business invoices.

    V124 deliberately derives invoice value/currency/customer/service from the
    document snapshot created when the invoice was issued. Live lead fields are
    only a compatibility fallback for older pre-snapshot documents. VOID invoices
    are excluded, and the SQL candidate window avoids scanning brand-new invoices
    that cannot yet be due-soon under the current payment terms.
    """
    limit = max(1, min(int(limit), 50))
    today_local = datetime.now(ADMIN_TIMEZONE).date()
    earliest_relevant_issued_at = datetime.now(UTC_TIMEZONE) - timedelta(
        days=max(0, BUSINESS_INVOICE_DUE_DAYS - RECEIVABLE_DUE_SOON_DAYS)
    )
    claimed = []

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    d.id, d.lead_id, d.document_number, d.issued_at,
                    d.due_soon_notified_at, d.overdue_notified_at,
                    d.snapshot,
                    l.customer_number, l.customer_name, l.service,
                    l.estimated_value, COALESCE(l.value_currency, 'MWK'),
                    COALESCE(SUM(
                        CASE
                            WHEN p.currency = COALESCE(
                                NULLIF(d.snapshot->>'value_currency',''),
                                l.value_currency,
                                'MWK'
                            )
                            THEN p.amount ELSE 0
                        END
                    ), 0) AS paid_total
                FROM business_documents d
                JOIN leads l ON l.id = d.lead_id
                LEFT JOIN lead_payments p ON p.lead_id = l.id
                WHERE d.doc_type = 'invoice'
                  AND COALESCE(d.document_status, 'ACTIVE') <> 'VOID'
                  AND l.merged_into_lead_id IS NULL
                  AND d.issued_at <= %s
                  AND (d.due_soon_notified_at IS NULL OR d.overdue_notified_at IS NULL)
                  AND (
                    d.invoice_notification_claimed_at IS NULL
                    OR d.invoice_notification_claimed_at < NOW() - INTERVAL '30 minutes'
                  )
                GROUP BY
                    d.id, d.lead_id, d.document_number, d.issued_at,
                    d.due_soon_notified_at, d.overdue_notified_at,
                    d.invoice_notification_claimed_at, d.snapshot,
                    l.customer_number, l.customer_name, l.service,
                    l.estimated_value, l.value_currency
                ORDER BY d.issued_at ASC, d.id ASC
                LIMIT %s
                """,
                (earliest_relevant_issued_at, limit * 8),
            )
            rows = cur.fetchall()

            for row in rows:
                (
                    document_id, lead_id, document_number, issued_at,
                    due_soon_notified_at, overdue_notified_at, snapshot,
                    live_customer_number, live_customer_name, live_service,
                    live_estimated_value, live_currency, paid_total,
                ) = row

                snap = dict(snapshot or {})
                currency = str(snap.get("value_currency") or live_currency or "MWK").strip().upper()
                raw_estimated = snap.get("estimated_value")
                if raw_estimated in (None, ""):
                    raw_estimated = live_estimated_value
                if raw_estimated is None:
                    # An invoice without a usable face value cannot produce a
                    # meaningful receivable reminder; leave it visible in admin
                    # instead of guessing an amount.
                    continue

                try:
                    estimated_value = Decimal(str(raw_estimated))
                except Exception:
                    continue
                paid_total = Decimal(paid_total or 0)
                balance = estimated_value - paid_total
                if balance <= 0:
                    continue

                due_local = issued_at.astimezone(ADMIN_TIMEZONE) + timedelta(
                    days=BUSINESS_INVOICE_DUE_DAYS
                )
                days_to_due = (due_local.date() - today_local).days

                reminder_kind = None
                if days_to_due < 0 and overdue_notified_at is None:
                    reminder_kind = "OVERDUE"
                elif (
                    0 <= days_to_due <= RECEIVABLE_DUE_SOON_DAYS
                    and due_soon_notified_at is None
                ):
                    reminder_kind = "DUE_SOON"

                if reminder_kind is None:
                    continue

                cur.execute(
                    """
                    UPDATE business_documents
                    SET invoice_notification_claimed_at = NOW(),
                        invoice_notification_error = NULL
                    WHERE id = %s
                      AND COALESCE(document_status, 'ACTIVE') <> 'VOID'
                      AND (
                        invoice_notification_claimed_at IS NULL
                        OR invoice_notification_claimed_at < NOW() - INTERVAL '30 minutes'
                      )
                    """,
                    (document_id,),
                )
                if cur.rowcount != 1:
                    continue

                claimed.append({
                    "document_id": document_id,
                    "lead_id": lead_id,
                    "document_number": document_number,
                    "issued_at": issued_at,
                    "due_at": due_local.astimezone(UTC_TIMEZONE),
                    "days_to_due": days_to_due,
                    "kind": reminder_kind,
                    "customer_number": str(snap.get("customer_number") or live_customer_number or "").strip(),
                    "customer_name": str(snap.get("customer_name") or live_customer_name or "WhatsApp Customer").strip(),
                    "service": canonicalize_service(snap.get("service") or live_service),
                    "estimated_value": estimated_value,
                    "paid_total": paid_total,
                    "balance": balance,
                    "currency": currency,
                })
                if len(claimed) >= limit:
                    break

        conn.commit()

    return claimed

def finish_invoice_reminder(item, success, error=None):
    with get_db() as conn:
        with conn.cursor() as cur:
            if success:
                notified_column = (
                    "overdue_notified_at"
                    if item["kind"] == "OVERDUE"
                    else "due_soon_notified_at"
                )
                cur.execute(
                    f"""
                    UPDATE business_documents
                    SET {notified_column} = NOW(),
                        invoice_notification_claimed_at = NULL,
                        invoice_notification_error = NULL
                    WHERE id = %s
                    """,
                    (item["document_id"],),
                )
                label = (
                    "Overdue invoice admin reminder sent."
                    if item["kind"] == "OVERDUE"
                    else "Due-soon invoice admin reminder sent."
                )
                _activity_insert(
                    cur,
                    item["lead_id"],
                    "INVOICE_REMINDER",
                    f"{label} {item['document_number']}",
                )
            else:
                cur.execute(
                    """
                    UPDATE business_documents
                    SET invoice_notification_claimed_at = NULL,
                        invoice_notification_error = %s
                    WHERE id = %s
                    """,
                    (
                        str(error or "Unknown invoice reminder error")[:500],
                        item["document_id"],
                    ),
                )
        conn.commit()


