def claim_due_project_invoice_reminders(limit=20):
    """Claim due-soon / overdue project invoices for internal IBROWS reminders.

    Deposit and stage invoices share the same ageing rule displayed by Accounts
    Receivable. Claims are persisted before email delivery so concurrent cron
    invocations cannot send the same reminder twice.
    """
    limit = max(1, min(int(limit), 50))
    today_local = datetime.now(ADMIN_TIMEZONE).date()
    claimed = []

    with get_db() as conn:
        with conn.cursor() as cur:
            # Build one chronological candidate queue across Deposit, Functional
            # Demonstration and Final invoices. Individual rows are locked again
            # before claiming because UNION queries themselves are not row-lockable.
            cur.execute(
                """
                SELECT invoice_kind, invoice_id, issued_at
                FROM (
                    SELECT 'DEPOSIT'::text AS invoice_kind, id AS invoice_id, issued_at
                    FROM project_invoices
                    WHERE status <> 'VOID'
                      AND (
                        invoice_notification_claimed_at IS NULL
                        OR invoice_notification_claimed_at < NOW() - INTERVAL '30 minutes'
                      )
                    UNION ALL
                    SELECT 'STAGE'::text AS invoice_kind, id AS invoice_id, issued_at
                    FROM project_stage_invoices
                    WHERE status <> 'VOID'
                      AND (
                        invoice_notification_claimed_at IS NULL
                        OR invoice_notification_claimed_at < NOW() - INTERVAL '30 minutes'
                      )
                ) candidates
                ORDER BY issued_at ASC, invoice_kind, invoice_id
                LIMIT %s
                """,
                (limit * 4,),
            )
            candidates = cur.fetchall()

            for invoice_kind, invoice_id, _candidate_issued_at in candidates:
                if len(claimed) >= limit:
                    break

                if invoice_kind == "DEPOSIT":
                    table_name = "project_invoices"
                    stage = "DEPOSIT"
                    cur.execute(
                        """
                        SELECT id,project_id,quotation_id,invoice_number,amount,currency,
                               status,issued_at,due_soon_notified_at,overdue_notified_at
                        FROM project_invoices
                        WHERE id=%s
                        FOR UPDATE SKIP LOCKED
                        """,
                        (invoice_id,),
                    )
                else:
                    table_name = "project_stage_invoices"
                    cur.execute(
                        """
                        SELECT id,project_id,quotation_id,invoice_number,amount,currency,
                               status,issued_at,due_soon_notified_at,overdue_notified_at,stage
                        FROM project_stage_invoices
                        WHERE id=%s
                        FOR UPDATE SKIP LOCKED
                        """,
                        (invoice_id,),
                    )

                row = cur.fetchone()
                if not row:
                    continue

                if invoice_kind == "DEPOSIT":
                    (iid, project_id, quotation_id, invoice_number, amount, currency,
                     status, issued_at, due_notice, overdue_notice) = row
                else:
                    (iid, project_id, quotation_id, invoice_number, amount, currency,
                     status, issued_at, due_notice, overdue_notice, stage) = row

                if status == "VOID":
                    continue

                cur.execute(
                    "SELECT COALESCE(SUM(amount),0) FROM project_payments "
                    "WHERE quotation_id=%s AND stage=%s",
                    (quotation_id, stage),
                )
                paid_total = Decimal((cur.fetchone() or [0])[0] or 0)
                amount = Decimal(amount or 0)
                balance = amount - paid_total
                if balance <= 0:
                    continue

                due_local = issued_at.astimezone(ADMIN_TIMEZONE) + timedelta(
                    days=BUSINESS_INVOICE_DUE_DAYS
                )
                days_to_due = (due_local.date() - today_local).days
                reminder_kind = None
                if days_to_due < 0 and overdue_notice is None:
                    reminder_kind = "OVERDUE"
                elif (
                    0 <= days_to_due <= RECEIVABLE_DUE_SOON_DAYS
                    and due_notice is None
                ):
                    reminder_kind = "DUE_SOON"
                if reminder_kind is None:
                    continue

                cur.execute(
                    f"""
                    UPDATE {table_name}
                    SET invoice_notification_claimed_at=NOW(),
                        invoice_notification_error=NULL
                    WHERE id=%s
                      AND status<>'VOID'
                      AND (
                        invoice_notification_claimed_at IS NULL
                        OR invoice_notification_claimed_at < NOW() - INTERVAL '30 minutes'
                      )
                    """,
                    (iid,),
                )
                if cur.rowcount != 1:
                    continue

                cur.execute(
                    """
                    SELECT pa.reference,pa.contact_name,pa.organisation,pa.project_type,
                           pq.quote_reference
                    FROM project_assessments pa
                    JOIN project_quotations pq ON pq.id=%s
                    WHERE pa.id=%s
                    """,
                    (quotation_id, project_id),
                )
                meta = cur.fetchone()
                if not meta:
                    continue
                project_reference, contact_name, organisation, project_type, quote_reference = meta
                claimed.append({
                    "invoice_kind": invoice_kind,
                    "table_name": table_name,
                    "document_id": iid,
                    "project_id": project_id,
                    "quotation_id": quotation_id,
                    "document_number": invoice_number,
                    "stage": stage,
                    "stage_label": PROJECT_PAYMENT_STAGE_LABELS.get(stage, stage),
                    "issued_at": issued_at,
                    "due_at": due_local.astimezone(UTC_TIMEZONE),
                    "days_to_due": days_to_due,
                    "kind": reminder_kind,
                    "project_reference": project_reference or "",
                    "quote_reference": quote_reference or "",
                    "customer_name": organisation or contact_name or "Project client",
                    "service": _v43_project_service_name(project_type),
                    "estimated_value": amount,
                    "paid_total": paid_total,
                    "balance": balance,
                    "currency": currency or "MWK",
                })
        conn.commit()
    return claimed


def finish_project_invoice_reminder(item, success, error=None):
    table_name = item.get("table_name")
    if table_name not in {"project_invoices", "project_stage_invoices"}:
        raise ValueError("Invalid project invoice table.")
    notified_column = (
        "overdue_notified_at" if item["kind"] == "OVERDUE"
        else "due_soon_notified_at"
    )
    with get_db() as conn:
        with conn.cursor() as cur:
            if success:
                cur.execute(
                    f"""
                    UPDATE {table_name}
                    SET {notified_column}=NOW(),
                        invoice_notification_claimed_at=NULL,
                        invoice_notification_error=NULL
                    WHERE id=%s
                    """,
                    (item["document_id"],),
                )
                label = (
                    "Overdue project-invoice admin reminder sent."
                    if item["kind"] == "OVERDUE"
                    else "Due-soon project-invoice admin reminder sent."
                )
                _project_activity_insert(
                    cur,
                    item["project_id"],
                    "INVOICE_REMINDER",
                    f"{label} {item['document_number']} · {item['stage_label']}",
                )
            else:
                cur.execute(
                    f"""
                    UPDATE {table_name}
                    SET invoice_notification_claimed_at=NULL,
                        invoice_notification_error=%s
                    WHERE id=%s
                    """,
                    (str(error or "Unknown project invoice reminder error")[:500],
                     item["document_id"]),
                )
        conn.commit()


