_EMBEDDED_ASSET_CACHE = {}
_EMBEDDED_ASSET_CACHE_LOCK = threading.Lock()


def _embedded_asset_response(cache_key, encoded, mimetype, max_age=86400):
    """Serve an embedded immutable-at-runtime asset with strong validation.

    The decoded bytes and SHA-256 validator are cached once per worker. Browsers
    can then receive 304 Not Modified without repeated base64 decoding or payload
    transfer. Asset URLs keep a one-day freshness window so a future deployment
    can replace branding without visitors being stuck with a long immutable cache.
    """
    cache_key = str(cache_key or "")
    with _EMBEDDED_ASSET_CACHE_LOCK:
        cached = _EMBEDDED_ASSET_CACHE.get(cache_key)
        if cached is None:
            try:
                asset_bytes = base64.b64decode(encoded)
            except Exception:
                abort(404)
            digest = hashlib.sha256(asset_bytes).hexdigest()
            cached = (asset_bytes, digest)
            _EMBEDDED_ASSET_CACHE[cache_key] = cached
    asset_bytes, digest = cached
    response = Response(asset_bytes, mimetype=mimetype)
    response.set_etag(digest)
    response.headers["Cache-Control"] = f"public, max-age={int(max_age)}, must-revalidate"
    response.make_conditional(request)
    return response


@app.route("/assets/ibrows-logo.jpg", methods=["GET"])
def public_ibrows_logo():
    return _embedded_asset_response("logo-jpeg", IBROWS_LOGO_JPEG_B64, "image/jpeg")


@app.route("/favicon.ico", methods=["GET"])
def favicon():
    return _embedded_asset_response("favicon-ico", IBROWS_FAVICON_ICO_B64, "image/x-icon", max_age=604800)


@app.route("/apple-touch-icon.png", methods=["GET"])
@app.route("/apple-touch-icon-precomposed.png", methods=["GET"])
def apple_touch_icon():
    return _embedded_asset_response("apple-touch-png", IBROWS_APPLE_TOUCH_PNG_B64, "image/png", max_age=604800)


@app.route("/assets/jones-nalikungwi-founder.jpg", methods=["GET"])
def public_jones_nalikungwi_founder():
    return _embedded_asset_response("founder-jpeg", IBROWS_FOUNDER_JPEG_B64, "image/jpeg")


@app.route("/assets/team/<slug>.jpg", methods=["GET"])
def public_team_photo(slug):
    slug = str(slug or "").strip().lower()
    encoded = PUBLIC_TEAM_IMAGE_B64.get(slug)
    if not encoded:
        abort(404)
    return _embedded_asset_response(f"team:{slug}", encoded, "image/jpeg")


