@app.route("/company-profile.pdf", methods=["GET"])
def public_company_profile_pdf():
    try:
        pdf_bytes = base64.b64decode(IBROWS_COMPANY_PROFILE_PDF_B64)
    except Exception:
        abort(404)
    response = Response(pdf_bytes, mimetype="application/pdf")
    disposition = "attachment" if request.args.get("download") == "1" else "inline"
    response.headers["Content-Disposition"] = f'{disposition}; filename="IBROWS_Enterprise_Company_Profile_2026.pdf"'
    response.headers["Cache-Control"] = "public, max-age=3600"
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


