@app.route("/sitemap.xml", methods=["GET"])
def sitemap_xml():
    paths = [
        "/", "/career-jobs", "/scholarships-opportunities", "/business-registration", "/business-email",
        "/photo-restoration", "/cleaning", "/car-wash", "/fumigation", "/agriculture",
        "/design-branding", "/landscaping", "/landscaping/preview", "/construction",
        "/construction/design-quote", "/construction/tender-boq-support",
        "/project-discovery", "/pricing", "/team", "/company-profile",
        "/privacy", "/terms", "/data-deletion",
    ]
    urls = "".join(f"<url><loc>{IBROWS_PUBLIC_BASE_URL}{path}</loc></url>" for path in paths)
    body = ('<?xml version="1.0" encoding="UTF-8"?>'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + urls + '</urlset>')
    response = Response(body, mimetype="application/xml")
    response.headers["Cache-Control"] = "public, max-age=3600"
    return response


