@app.route("/health", methods=["GET"])
def health():
    try:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT 1")
                cur.fetchone()

        return {
            "status": "ok",
            "database": "connected"
        }, 200

    except Exception as error:
        print(f"Health check error: {type(error).__name__}", flush=True)

        return {
            "status": "error",
            "database": "not connected"
        }, 500


# =========================================================
# ADMIN AUTHENTICATION
# =========================================================

def _login_client_key():
    # request.remote_addr is intentionally used instead of trusting a user-supplied
    # forwarding header. On this small single-worker service it provides a safe,
    # conservative throttle key.
    return request.remote_addr or "unknown"


def _login_is_locked(client_key):
    now = time.monotonic()
    with _login_attempts_lock:
        record = _login_attempts.get(client_key)
        if not record:
            return False
        attempts = [t for t in record.get("attempts", []) if now - t <= LOGIN_WINDOW_SECONDS]
        locked_until = record.get("locked_until", 0)
        if locked_until and now < locked_until:
            record["attempts"] = attempts
            return True
        if locked_until and now >= locked_until:
            _login_attempts.pop(client_key, None)
            return False
        record["attempts"] = attempts
        if not attempts:
            _login_attempts.pop(client_key, None)
        return False


def _record_failed_login(client_key):
    now = time.monotonic()
    with _login_attempts_lock:
        record = _login_attempts.setdefault(client_key, {"attempts": [], "locked_until": 0})
        record["attempts"] = [t for t in record["attempts"] if now - t <= LOGIN_WINDOW_SECONDS]
        record["attempts"].append(now)
        if len(record["attempts"]) >= LOGIN_MAX_ATTEMPTS:
            record["locked_until"] = now + LOGIN_LOCKOUT_SECONDS


def _clear_failed_logins(client_key):
    with _login_attempts_lock:
        _login_attempts.pop(client_key, None)


def _safe_admin_next(value):
    """Allow post-login return only to local IBROWS admin paths."""
    target = str(value or "").strip()
    if not target:
        return ""
    if "\r" in target or "\n" in target or target.startswith("//") or "://" in target:
        return ""
    if target == "/admin" or target.startswith("/admin/"):
        return target
    return ""


def admin_required(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        if not session.get("admin_authenticated"):
            target = request.full_path if request.query_string else request.path
            if target.endswith("?"):
                target = target[:-1]
            return redirect(url_for("admin_login", next=_safe_admin_next(target)))

        session.permanent = True
        return function(*args, **kwargs)

    return wrapper


@app.route("/admin/confirm-actions.js", methods=["GET"])
def admin_confirm_actions_js():
    # CSP-safe confirmation handler for destructive/admin-critical forms.
    # Inline onsubmit/onclick JavaScript is intentionally blocked by our CSP.
    script = r"""
(function () {
  function installConfirmations() {
    document.querySelectorAll('form[data-confirm]').forEach(function (form) {
      if (form.dataset.confirmBound === '1') return;
      form.dataset.confirmBound = '1';
      form.addEventListener('submit', function (event) {
        var message = form.getAttribute('data-confirm') || 'Are you sure?';
        if (!window.confirm(message)) {
          event.preventDefault();
          event.stopImmediatePropagation();
          return;
        }
        var marker = form.querySelector('input[name="_ibrows_confirmed_action"]');
        if (!marker) {
          marker = document.createElement('input');
          marker.type = 'hidden';
          marker.name = '_ibrows_confirmed_action';
          form.appendChild(marker);
        }
        marker.value = '1';
      });
    });
  }
  function installFeedbackDismissal() {
    var feedback = document.getElementById('ibrows-global-feedback');
    if (!feedback) return;
    window.setTimeout(function () {
      if (feedback && feedback.parentNode) feedback.parentNode.removeChild(feedback);
    }, 6500);
  }
  function installCopyButtons() {
    document.querySelectorAll('[data-copy-text]').forEach(function (button) {
      if (button.dataset.copyBound === '1') return;
      button.dataset.copyBound = '1';
      button.addEventListener('click', function () {
        var value = button.getAttribute('data-copy-text') || '';
        if (!value) return;
        function done() { button.textContent = 'Reference Copied'; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(value).then(done).catch(function () {
            var ta = document.createElement('textarea');
            ta.value = value; document.body.appendChild(ta); ta.select();
            try { document.execCommand('copy'); done(); } catch (e) {}
            ta.remove();
          });
        } else {
          var ta = document.createElement('textarea');
          ta.value = value; document.body.appendChild(ta); ta.select();
          try { document.execCommand('copy'); done(); } catch (e) {}
          ta.remove();
        }
      });
    });
  }
  function installDeferredPortfolioPreviews() {
    document.querySelectorAll('[data-load-portfolio-preview]').forEach(function (button) {
      if (button.dataset.previewBound === '1') return;
      button.dataset.previewBound = '1';
      button.addEventListener('click', function () {
        var holder = button.closest('[data-portfolio-preview]');
        if (!holder || holder.dataset.loaded === '1') return;
        var src = holder.getAttribute('data-src') || '';
        if (!src) return;
        holder.dataset.loaded = '1';
        button.disabled = true;
        button.textContent = 'Loading Preview…';
        var link = document.createElement('a');
        link.href = holder.getAttribute('data-full-src') || src;
        link.target = '_blank';
        link.rel = 'noopener';
        var img = document.createElement('img');
        img.loading = 'lazy';
        img.decoding = 'async';
        img.alt = holder.getAttribute('data-alt') || 'Portfolio preview';
        img.addEventListener('error', function () {
          holder.dataset.loaded = '0';
          holder.replaceChildren(button);
          button.disabled = false;
          button.textContent = 'Retry Preview';
        }, {once:true});
        img.src = src;
        link.appendChild(img);
        holder.replaceChildren(link);
      });
    });
  }
  function installProjectFocus() {
    try {
      var params = new URLSearchParams(window.location.search || '');
      if (params.get('focus') !== 'payment') return;
      var target = document.getElementById('deposit-project-start');
      if (!target) return;
      window.requestAnimationFrame(function () {
        target.scrollIntoView({block: 'start'});
        if (window.history && window.history.replaceState) {
          var u = new URL(window.location.href);
          u.searchParams.delete('focus');
          u.hash = 'deposit-project-start';
          window.history.replaceState(null, '', u.pathname + (u.search ? u.search : '') + u.hash);
        }
      });
    } catch (e) {
      // Navigation focus is a convenience only; never block admin controls.
    }
  }
  // V132: Mobile-friendly acknowledgement that gallery edits need saving.
  // Does not intercept or change form submission, payment controls or deletes.
  function installPortfolioSaveHints() {
    document.querySelectorAll('form[id^="portfolio-save-"]').forEach(function (form) {
      if (form.dataset.saveHintBound === '1') return;
      form.dataset.saveHintBound = '1';
      var actions = form.querySelector('.actions');
      if (!actions) return;
      var hint = document.createElement('span');
      hint.setAttribute('role', 'status');
      hint.setAttribute('aria-live', 'polite');
      hint.style.cssText = 'display:none;color:#b54708;font-size:14px;font-weight:700;align-self:center;line-height:1.4;';
      hint.textContent = 'Unsaved edits — tap Save All or Save This Item.';
      actions.appendChild(hint);
      function markUnsaved(event) {
        if (event && event.target && !event.target.matches('input,select,textarea')) return;
        hint.style.display = 'inline';
      }
      form.addEventListener('input', markUnsaved);
      form.addEventListener('change', markUnsaved);
    });
  }
  function installAll() {
    installConfirmations();
    installFeedbackDismissal();
    installCopyButtons();
    installDeferredPortfolioPreviews();
    installPortfolioSaveHints();
    installProjectFocus();
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', installAll);
  } else {
    installAll();
  }
})();
"""
    response = Response(script, mimetype="application/javascript")
    response.headers["Cache-Control"] = "no-store"
    return response


def _admin_success_feedback_message(response):
    """Return a user-facing confirmation for successful admin write actions.

    This is centralized so new admin forms do not silently save/update/delete records.
    Existing feature-specific confirmations remain authoritative; the global banner is
    suppressed automatically when the destination page already renders the same message.
    """
    endpoint = str(request.endpoint or "")
    if not endpoint.startswith("admin_") or endpoint in {"admin_login", "admin_logout"}:
        return ""

    # Do not report success when an admin route deliberately redirected to an error state.
    location = str(response.headers.get("Location") or "").lower()
    if any(marker in location for marker in (
        "message_type=err", "error=", "invalid", "failed=1", "failure=1",
    )):
        return ""

    sandbox = str(request.form.get("mode") or "").strip().lower() == "sandbox"
    action = str(request.form.get("action") or "").strip().lower()

    messages = {
        "admin_inbox_send": "Message sent successfully.",
        "admin_void_payment": "Payment void recorded successfully.",
        "admin_expenses_add": "Expense saved.",
        "admin_expenses_delete": "Expense deleted.",
        "admin_merge_customer_duplicates": "Customer duplicates merged successfully.",
        "admin_business_document_send": "Business document sent successfully.",
        "admin_ai_takeover": "AI / human handover setting updated successfully.",
        "admin_single_job_application_complete": "Single-job application marked complete successfully.",
        "admin_career_assist_activate": "Career Assist activation saved successfully.",
        "admin_career_assist_application_submitted": "Application submission recorded successfully.",
        "admin_customer_privacy": "Customer privacy action completed successfully.",
        "admin_lead_status": "Lead status updated successfully.",
        "admin_project_status": "Project workflow status updated successfully.",
        "admin_project_analyze": "Scope analysis refresh completed.",
        "admin_project_note": "Internal project note added successfully.",
        "admin_project_costing_import_apply": "Price sheet applied successfully.",
        "admin_project_costing": "Internal costing saved successfully.",
        "admin_project_costing_approve": "Costing approved for quotation draft successfully.",
        "admin_project_quotation_issue": "Quotation issued successfully.",
        "admin_project_quotation_email": "Quotation email sent successfully with the PDF attached.",
        "admin_project_sandbox_enable": "Sandbox / Test Mode enabled successfully.",
        "admin_project_sandbox_payment_record": "Test payment recorded successfully.",
        "admin_project_sandbox_payment_void": "Test payment voided successfully.",
        "admin_project_sandbox_start": "Test project start simulated successfully.",
        "admin_project_sandbox_reset": "Sandbox reset successfully.",
        "admin_project_sandbox_exit": "Sandbox cleared and exited successfully.",
        "admin_project_payment_record": "Verified project payment recorded successfully.",
        "admin_project_payment_void": "Verified project payment voided successfully.",
        "admin_project_start": "Project started successfully.",
        "admin_budget_save": "Budget saved successfully.",
        "admin_budget_delete": "Budget deleted successfully.",
        "admin_project_execution_milestone_update": "Milestone saved successfully.",
        "admin_project_execution_task_add": "Task added successfully.",
        "admin_project_execution_task_update": "Task saved successfully.",
        "admin_project_execution_task_delete": "Task deleted successfully.",
        "admin_project_stage_invoice_create": "Project stage invoice is ready.",
        "admin_project_execution_complete": "Project completion recorded successfully.",
    }

    if endpoint == "admin_lead_operations":
        if action == "note":
            return "Lead note added successfully."
        if action == "followup":
            return "Lead follow-up updated successfully."
        if action == "priority":
            return "Lead priority updated successfully."
        return "Lead changes saved successfully."

    if endpoint == "admin_project_execution_update_add":
        return "Test client update added successfully." if sandbox else "Client update published successfully."

    if endpoint == "admin_project_costing_import":
        # Successful upload/review is returned directly as HTML rather than a redirect.
        return "Price sheet uploaded successfully for review."

    if endpoint == "admin_project_costing_import_apply" and "imported=1" not in location:
        return ""

    return messages.get(endpoint, "Action completed successfully.")


def _admin_feedback_banner_html(message):
    # Messages are application-owned constants, never customer-provided HTML.
    return (
        '<div id="ibrows-global-feedback" role="status" aria-live="polite" '
        'style="position:fixed;left:12px;right:12px;bottom:16px;z-index:10000;max-width:760px;'
        'margin:0 auto;padding:14px 18px;border:1px solid #abefc6;border-radius:14px;'
        'background:#ecfdf3;color:#067647;font-family:system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;font-size:16px;line-height:1.45;'
        'font-weight:700;box-shadow:0 8px 24px rgba(16,24,40,.18)">'
        '✓ ' + str(message) + '</div>'
    )


def _admin_html_already_has_feedback(html, message):
    normalized = str(message or "").strip().lower().lstrip("✓").strip()
    if not normalized:
        return False
    body = str(html or "").lower()
    # Exact feature-specific banners win over the centralized fallback to avoid duplicates.
    return normalized in body


@app.after_request
def add_security_headers(response):
    immediate_feedback = ""
    # Per-response CSP nonce keeps inline scripts functional without weakening
    # script-src with unsafe-inline. It is injected into rendered <script> tags
    # just before the response leaves Flask.
    csp_nonce = secrets.token_urlsafe(18)

    # Centralized post-action feedback for every successful admin mutation.
    if (
        request.path.startswith("/admin")
        and request.method == "POST"
        and session.get("admin_authenticated")
        and 200 <= response.status_code < 400
    ):
        feedback = _admin_success_feedback_message(response)
        if feedback:
            if 300 <= response.status_code < 400:
                session["_ibrows_admin_feedback"] = feedback
            elif response.mimetype == "text/html" and not response.is_streamed:
                immediate_feedback = feedback

    response.headers["X-Content-Type-Options"] = "nosniff"
    # The public company-profile PDF is intentionally embeddable only by the
    # same IBROWS origin so /company-profile can display it inline. All other
    # responses keep the stricter DENY policy.
    if request.path == "/company-profile.pdf":
        response.headers["X-Frame-Options"] = "SAMEORIGIN"
    else:
        response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    # V85: Render redirects public HTTP traffic to HTTPS. Tell browsers to keep
    # using HTTPS for this host after the first secure response as an additional
    # transport downgrade safeguard. Avoid includeSubDomains/preload because
    # IBROWS may later attach a custom domain with unrelated subdomains.
    response.headers["Strict-Transport-Security"] = "max-age=31536000"
    response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    if request.path == "/company-profile.pdf":
        response.headers["Content-Security-Policy"] = (
            "default-src 'self'; object-src 'none'; frame-ancestors 'self'; base-uri 'self'"
        )
    else:
        response.headers["Content-Security-Policy"] = (
            f"default-src 'self'; script-src 'self' 'nonce-{csp_nonce}'; style-src 'self' 'unsafe-inline'; "
            "img-src 'self' data:; worker-src 'self'; manifest-src 'self'; object-src 'none'; "
            "frame-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'self'"
        )
    # V132: Public capability URLs (client questionnaires, quotations, invoices,
    # and project status) carry unguessable tokens but are not public landing pages.
    # Prevent search indexing and intermediary/browser storage even for PDFs and
    # successful 200 responses. Do not emit token-bearing canonical URLs.
    private_client_path = bool(
        re.match(r"^/(?:quotation|project-status)/[^/]+(?:/|$)", request.path)
        or re.match(r"^/project-discovery/[^/]+/(?:step/[0-9]+|complete)/?$", request.path)
    )
    if private_client_path:
        response.headers["Cache-Control"] = "private, no-store, no-cache, max-age=0, must-revalidate"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        response.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive"
        response.headers.pop("Link", None)
    elif request.path.startswith("/admin"):
        response.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive"

    # Keep the Render hostname available as an operational fallback without
    # allowing search engines to index it as a duplicate of the professional domain.
    request_host = (request.host or "").split(":", 1)[0].lower()
    if request_host.endswith(".onrender.com"):
        response.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive"
    elif response.status_code >= 400:
        # Error/probe URLs must never become indexable pseudo-pages or receive
        # self-referencing canonical links. This also keeps automated secret-file
        # scans such as /.env and /backup.sql out of search indexes.
        response.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive"

    if (
        request.method in {"GET", "HEAD"}
        and 200 <= response.status_code < 300
        and not request.path.startswith(("/admin", "/tasks", "/webhook"))
        and not private_client_path
    ):
        canonical_url = f"{IBROWS_PUBLIC_BASE_URL}{request.path}"
        response.headers["Link"] = f'<{canonical_url}>; rel="canonical"'

    if request.path.startswith("/admin"):
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, private, max-age=0"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        if response.mimetype == "text/html" and not response.is_streamed:
            try:
                html = response.get_data(as_text=True)

                feedback = immediate_feedback
                if (
                    not feedback
                    and request.method == "GET"
                    and 200 <= response.status_code < 300
                ):
                    feedback = str(session.pop("_ibrows_admin_feedback", "") or "")

                if feedback and not _admin_html_already_has_feedback(html, feedback):
                    banner = _admin_feedback_banner_html(feedback)
                    if "<body" in html:
                        body_end = html.find(">", html.find("<body"))
                        if body_end != -1:
                            html = html[:body_end + 1] + banner + html[body_end + 1:]

                script_tag = '<script src="/admin/confirm-actions.js" defer></script>'
                if "</body>" in html and script_tag not in html:
                    html = html.replace("</body>", script_tag + "</body>", 1)

                response.set_data(html)
            except Exception:
                # Security headers must still be applied even if a nonstandard response
                # cannot be inspected for script/banner injection.
                pass

    # Some legacy/public templates still contain small inline script blocks.
    # Give every rendered script tag the per-response nonce so those controls
    # work under the strict CSP. Inline event-handler attributes remain blocked.
    if response.mimetype == "text/html" and not response.is_streamed:
        try:
            html = response.get_data(as_text=True)
            html = re.sub(
                r'<script(?![^>]*\bnonce=)([^>]*)>',
                lambda match: f'<script nonce="{csp_nonce}"{match.group(1)}>',
                html,
                flags=re.IGNORECASE,
            )
            response.set_data(html)
        except Exception:
            pass
    return response


def get_csrf_token():
    token = session.get("csrf_token")

    if not token:
        token = secrets.token_urlsafe(32)
        session["csrf_token"] = token

    return token


def validate_csrf():
    supplied = request.form.get("csrf_token", "")
    stored = session.get("csrf_token", "")

    if (
        not supplied
        or not stored
        or not secrets.compare_digest(supplied, stored)
    ):
        abort(403)


def get_project_discovery_csrf(scope="START"):
    """Return a stable, form-scoped CSRF token for the public discovery flow.

    Project Discovery can take a client a while to complete and may span deploys or
    browser/session refreshes. Tying these public forms only to the Flask session can
    therefore strand a legitimate client on the final Submit step. The project URL
    itself already contains a high-entropy capability token; this HMAC binds the form
    to that capability without weakening admin-session CSRF protection.
    """
    secret = str(FLASK_SECRET_KEY or "").encode("utf-8")
    normalized_scope = str(scope or "START").strip()
    message = f"ibrows-project-discovery-csrf-v55:{normalized_scope}".encode("utf-8")
    return hmac.new(secret, message, hashlib.sha256).hexdigest()


def validate_project_discovery_csrf(scope="START"):
    supplied = str(request.form.get("csrf_token", "") or "").strip()
    expected = get_project_discovery_csrf(scope)

    # Transitional compatibility: accept an already-rendered pre-V55 form if its
    # original Flask-session CSRF token is still valid. New forms use the stable HMAC.
    stored = str(session.get("csrf_token", "") or "").strip()
    stable_ok = bool(supplied and secrets.compare_digest(supplied, expected))
    legacy_ok = bool(supplied and stored and secrets.compare_digest(supplied, stored))
    if not (stable_ok or legacy_ok):
        print(
            f"PROJECT DISCOVERY CSRF REJECTED: scope={str(scope)[:20]}",
            flush=True,
        )
        abort(403)


