@app.route("/tasks/followup-reminders", methods=["POST"])
def follow_up_reminder_task():
    if not FOLLOWUP_CRON_SECRET:
        print("FOLLOW-UP REMINDER TASK BLOCKED: FOLLOWUP_CRON_SECRET missing", flush=True)
        return Response(
            json.dumps({"ok": False, "error": "task not configured"}),
            status=503,
            mimetype="application/json",
        )

    supplied = request.headers.get("X-IBROWS-CRON-SECRET", "")
    if not supplied or not hmac.compare_digest(supplied, FOLLOWUP_CRON_SECRET):
        return Response(
            json.dumps({"ok": False, "error": "unauthorized"}),
            status=401,
            mimetype="application/json",
        )

    try:
        expired_career_assist = expire_career_assist_entitlements()
        follow_up_result = process_due_follow_up_reminders(limit=20)
        website_service_follow_up_result = process_due_website_service_follow_up_reminders(limit=20)
        invoice_result = process_due_invoice_reminders(limit=20)
        result = {
            "ok": True,
            "career_assist_expired": expired_career_assist,
            "follow_up": follow_up_result,
            "website_service_follow_up": website_service_follow_up_result,
            "invoice": invoice_result,
        }
        _record_task_health(REMINDER_TASK_KEY, "CRON", True, result)
        return Response(
            json.dumps(result, separators=(",", ":")),
            mimetype="application/json",
        )
    except Exception as exc:
        _record_task_health(REMINDER_TASK_KEY, "CRON", False, {}, f"{type(exc).__name__}: {str(exc)[:500]}")
        print(f"FOLLOW-UP REMINDER TASK FAILED: {type(exc).__name__}: {str(exc)[:300]}", flush=True)
        raise



@app.route("/admin/login", methods=["GET", "POST"])
def admin_login():

    next_url = _safe_admin_next(request.form.get("next") or request.args.get("next"))

    if session.get("admin_authenticated"):
        return redirect(next_url or url_for("admin_leads"))

    error = None
    csrf_token = get_csrf_token()

    if request.method == "POST":

        supplied_csrf = str(request.form.get("csrf_token") or "")
        stored_csrf = str(session.get("csrf_token") or "")
        if (
            not supplied_csrf
            or not stored_csrf
            or not secrets.compare_digest(supplied_csrf, stored_csrf)
        ):
            # A deployment, long-open tab or restored browser form can leave an old
            # login CSRF token behind. Keep the check fail-closed, but recover with a
            # fresh form instead of exposing a generic Flask 403 page.
            session.pop("csrf_token", None)
            error = "Your sign-in form expired or changed. Please sign in again."
            print("ADMIN LOGIN CSRF REFRESHED", flush=True)
            return render_template_string(
                LOGIN_TEMPLATE,
                error=error,
                csrf_token=get_csrf_token(),
                next_url=next_url,
            ), 400

        client_key = _login_client_key()
        if _login_is_locked(client_key):
            error = "Too many sign-in attempts. Please wait 15 minutes and try again."
            return render_template_string(
                LOGIN_TEMPLATE,
                error=error,
                csrf_token=get_csrf_token(),
                next_url=next_url
            ), 429

        username = request.form.get("username", "")
        password = request.form.get("password", "")

        username_ok = (
            ADMIN_USERNAME
            and secrets.compare_digest(
                username,
                ADMIN_USERNAME
            )
        )

        password_ok = (
            ADMIN_PASSWORD
            and secrets.compare_digest(
                password,
                ADMIN_PASSWORD
            )
        )

        if username_ok and password_ok:
            _clear_failed_logins(client_key)
            session.clear()
            session.permanent = True
            session["admin_authenticated"] = True
            session["csrf_token"] = secrets.token_urlsafe(32)

            return redirect(next_url or url_for("admin_leads"))

        _record_failed_login(client_key)
        error = "Incorrect username or password."

    return render_template_string(
        LOGIN_TEMPLATE,
        error=error,
        csrf_token=csrf_token,
        next_url=next_url
    )


@app.route("/admin/logout", methods=["POST"])
@admin_required
def admin_logout():
    validate_csrf()
    session.clear()

    return redirect(url_for("admin_login"))


