@app.route("/admin/applications", methods=["GET"])
@admin_required
def admin_career_applications():
    expire_career_assist_entitlements()
    status_filter = request.args.get("status", "ALL").strip().upper()
    if status_filter not in {"ALL", "PENDING", "NEEDS_INFO", "PREPARING", "DRAFT_READY", "SUBMITTED"}:
        status_filter = "ALL"
    search_query = request.args.get("q", "").strip()[:120]
    applications, counts = get_career_assist_application_operations(status_filter, search_query)
    current_return = request.full_path
    if current_return.endswith("?"):
        current_return = current_return[:-1]
    current_return = _safe_admin_return_path(current_return)
    return render_template_string(
        CAREER_APPLICATIONS_TEMPLATE,
        applications=applications,
        counts=counts,
        csrf_token=get_csrf_token(),
        status_filter=status_filter,
        search_query=search_query,
        current_return=current_return,
    )



