@app.route("/admin/customers/<customer_number>", methods=["GET"])
@admin_required
def admin_customer_history(customer_number):
    if not customer_number.isdigit() or len(customer_number) > 20:
        abort(400)

    profile = get_customer_crm_profile(customer_number)
    if not profile:
        abort(404)

    leads = profile["leads"]
    timeline = profile["timeline"]
    payments = profile.get("payments", [])
    documents = get_customer_business_documents(customer_number)
    payment_totals = get_payment_totals_by_lead([lead["id"] for lead in leads])
    customer_name = next(
        (lead["customer_name"] for lead in leads if lead.get("customer_name")),
        "WhatsApp Customer",
    )

    for lead in leads:
        lead["estimated_value_label"] = _format_crm_amount(
            lead.get("estimated_value"),
            lead.get("value_currency") or "MWK",
        )
        lead["quote_status_label"] = QUOTE_STATUSES.get(
            lead.get("quote_status") or "NOT_STARTED",
            "Not started",
        )
        lead.update(_lead_payment_snapshot(lead, payment_totals))
        lead["created_label"] = lead["created_at"].astimezone(
            ADMIN_TIMEZONE
        ).strftime("%d %b %Y %H:%M")
        lead["updated_label"] = lead["updated_at"].astimezone(
            ADMIN_TIMEZONE
        ).strftime("%d %b %Y %H:%M")

    kind_labels = {
        "LEAD_CREATED": "Lead created",
        "AI_UPDATE": "AI update",
        "LEAD_UPDATED": "Lead update",
        "STATUS": "Status change",
        "NOTE": "Internal note",
        "REMINDER": "Reminder",
        "MERGE": "Duplicate consolidation",
        "PAYMENT": "Payment",
        "DOCUMENT_SENT": "Document sent",
        "DOCUMENT_CREATED": "Document generated",
    }
    for item in timeline:
        item["kind_label"] = kind_labels.get(item["kind"], item["kind"].replace("_", " ").title())
        item["time_label"] = item["created_at"].astimezone(
            ADMIN_TIMEZONE
        ).strftime("%d %b %Y %H:%M")

    for payment in payments:
        payment["amount_label"] = _format_crm_amount(
            payment["amount"],
            payment["currency"],
        )
        payment["method_label"] = PAYMENT_METHODS.get(
            payment["payment_method"],
            payment["payment_method"].replace("_", " ").title(),
        )
        payment["received_label"] = payment["received_at"].astimezone(
            ADMIN_TIMEZONE
        ).strftime("%d %b %Y %H:%M")

    for doc in documents:
        doc["issued_label"] = doc["issued_at"].astimezone(
            ADMIN_TIMEZONE
        ).strftime("%d %b %Y %H:%M")
        doc["last_sent_label"] = (
            doc["last_sent_at"].astimezone(ADMIN_TIMEZONE).strftime(
                "%d %b %Y %H:%M"
            )
            if doc["last_sent_at"]
            else ""
        )

    return_to = _safe_admin_return_path(request.args.get("return_to"))
    crm_return = url_for(
        "admin_customer_history",
        customer_number=customer_number,
        return_to=return_to,
    )
    return render_template_string(
        CUSTOMER_CRM_TEMPLATE,
        customer_number=customer_number,
        customer_name=customer_name,
        leads=leads,
        timeline=timeline,
        open_count=sum(1 for lead in leads if lead["status"] != "CLOSED"),
        services_count=len({lead["service"] for lead in leads}),
        archived_merged_count=profile.get("archived_merged_count", 0),
        duplicate_groups=profile.get("duplicate_groups", []),
        customer_values=summarize_customer_values(leads, payment_totals),
        payments=payments,
        documents=documents,
        csrf_token=get_csrf_token(),
        crm_return=crm_return,
        return_to=return_to,
    )


