def _project_primary_type(components):
    components = [str(x or "").strip().upper() for x in (components or []) if str(x or "").strip()]
    unique = []
    for item in components:
        if item not in unique:
            unique.append(item)
    if "OTHER" in unique and len(unique) > 1:
        unique = [x for x in unique if x != "OTHER"]
    selected = set(unique)
    if {"WEBSITE", "MOBILE_APP"}.issubset(selected):
        return "WEB_APP"
    for preferred in ("CUSTOMER_PORTAL", "BUSINESS_SYSTEM", "WHATSAPP_AI", "AI_SOLUTION", "EXISTING_SYSTEM", "WEBSITE", "MOBILE_APP", "OTHER"):
        if preferred in selected:
            return preferred
    return "OTHER"


def _project_component_codes(project):
    answers = (project or {}).get("answers") or {}
    components = _project_list(answers.get("project_components", []), limit_items=12, item_limit=60)
    if components:
        return set(x.upper() for x in components)
    primary = str((project or {}).get("project_type") or "").upper()
    if primary == "WEB_APP":
        return {"WEBSITE", "MOBILE_APP"}
    return {primary} if primary else set()

