@app.route("/admin/projects/<int:project_id>/quotations/<int:quotation_id>/email", methods=["POST"])
@admin_required
def admin_project_quotation_email(project_id, quotation_id):
    validate_csrf()
    quote_item = _get_project_quotation_by_id(quotation_id)
    if not quote_item or quote_item.get("project_id") != project_id:
        abort(404)
    quote_item = _sync_project_quotation_expiry(quote_item)
    if quote_item.get("status") not in {"ISSUED", "VIEWED"}:
        error = "Only an active issued quotation can be delivered to the client."
        return redirect(url_for("admin_project_quotation_detail", project_id=project_id, quotation_id=quotation_id, email="failed", error=error))
    public_url = url_for("public_project_quotation", public_token=quote_item["public_token"], _external=True)
    ok, error = _send_project_quotation_email(quote_item, public_url)
    with get_db() as conn:
        with conn.cursor() as cur:
            if ok:
                _quote_event_insert(cur, quotation_id, "EMAIL_SENT", f"Quotation emailed to {quote_item['client'].get('email')} with PDF attachment.")
                _project_activity_insert(cur, project_id, "QUOTE_EMAIL", f"Quotation {quote_item['quote_reference']} emailed to client.")
            else:
                _quote_event_insert(cur, quotation_id, "EMAIL_FAILED", error)
        conn.commit()
    if ok:
        return redirect(url_for("admin_project_quotation_detail", project_id=project_id, quotation_id=quotation_id, email="sent"))
    return redirect(url_for("admin_project_quotation_detail", project_id=project_id, quotation_id=quotation_id, email="failed", error=error))



