@app.route("/admin/projects/<int:project_id>/sandbox/enable", methods=["POST"])
@admin_required
def admin_project_sandbox_enable(project_id):
    validate_csrf()
    if request.form.get("confirm_sandbox") != "1":
        abort(400)
    quote_item = _latest_accepted_project_quotation(project_id)
    if not quote_item:
        abort(400)
    real_state = _project_commercial_state(project_id, quote_item)
    if not real_state or real_state.get("payments") or real_state.get("execution"):
        abort(409)
    with get_db() as conn:
        with conn.cursor() as cur:
            # Enabling Sandbox must not silently delete test history from an
            # earlier quotation revision. Payment reads are scoped to the current
            # quotation_id, so prior test rows can remain preserved until the
            # admin explicitly chooses Reset Sandbox or Exit & Clear Sandbox.
            cur.execute(
                """
                INSERT INTO project_sandbox_state (
                    project_id, quotation_id, enabled, sandbox_started_at,
                    start_note, created_at, updated_at
                ) VALUES (%s,%s,TRUE,NULL,NULL,NOW(),NOW())
                ON CONFLICT (project_id) DO UPDATE
                SET quotation_id=EXCLUDED.quotation_id,
                    enabled=TRUE,
                    sandbox_started_at=NULL,
                    start_note=NULL,
                    updated_at=NOW()
                """,
                (project_id, quote_item["id"]),
            )
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="enabled", _anchor="deposit-project-start"))


@app.route("/admin/projects/<int:project_id>/sandbox/payments/record", methods=["POST"])
@admin_required
def admin_project_sandbox_payment_record(project_id):
    validate_csrf()
    token = _project_clean(request.form.get("sandbox_payment_request_token"), 160)
    if not token:
        abort(400)
    quote_item = _latest_accepted_project_quotation(project_id)
    if not quote_item:
        abort(400)
    try:
        amount = _crm_payment_amount(request.form.get("amount"))
    except ValueError:
        abort(400)
    if amount is None or amount <= 0:
        abort(400)
    method = _crm_payment_method(request.form.get("payment_method"))
    stage = _project_clean(request.form.get("stage"), 40).upper()
    if stage not in {"DEPOSIT", "MILESTONE_2", "FINAL"}:
        abort(400)
    reference = _project_clean(request.form.get("reference"), 180)
    payment_note = _project_clean(request.form.get("payment_note"), 1000)

    # Serialize Sandbox payment writes exactly like the live ledger. The row
    # lock makes stage/total remaining checks authoritative even if the admin
    # double-taps or two requests arrive at nearly the same time. The request
    # token makes a replay of the same rendered form idempotent.
    required_by_stage = _execution_required_amounts(quote_item)
    stage_required = required_by_stage.get(stage, Decimal("0"))
    final_price = _money_decimal((quote_item.get("pricing") or {}).get("final_price"))
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT quotation_id, enabled FROM project_sandbox_state WHERE project_id=%s FOR UPDATE",
                (project_id,),
            )
            state_row = cur.fetchone()
            if not state_row or not state_row[1] or state_row[0] != quote_item["id"]:
                abort(409)
            cur.execute(
                "SELECT id FROM project_sandbox_payments WHERE request_token=%s",
                (token,),
            )
            if cur.fetchone():
                conn.commit()
                return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="payment", _anchor="deposit-project-start"))
            cur.execute(
                "SELECT COALESCE(SUM(amount),0) FROM project_sandbox_payments WHERE project_id=%s AND quotation_id=%s AND voided_at IS NULL",
                (project_id, quote_item["id"]),
            )
            total_paid = Decimal((cur.fetchone() or [0])[0] or 0)
            total_remaining = max(Decimal("0"), final_price - total_paid)
            cur.execute(
                "SELECT COALESCE(SUM(amount),0) FROM project_sandbox_payments WHERE project_id=%s AND quotation_id=%s AND stage=%s AND voided_at IS NULL",
                (project_id, quote_item["id"], stage),
            )
            stage_paid = Decimal((cur.fetchone() or [0])[0] or 0)
            stage_remaining = max(Decimal("0"), stage_required - stage_paid)
            if (
                final_price <= 0
                or stage_required <= 0
                or total_remaining <= 0
                or stage_remaining <= 0
                or amount > total_remaining
                or amount > stage_remaining
            ):
                abort(400)
            cur.execute(
                """
                INSERT INTO project_sandbox_payments (
                    project_id, quotation_id, stage, amount, currency,
                    payment_method, reference, payment_note, request_token, received_at
                ) VALUES (%s,%s,%s,%s,%s,%s,NULLIF(%s,''),NULLIF(%s,''),%s,NOW())
                """,
                (project_id, quote_item["id"], stage, amount, quote_item.get("currency") or "MWK", method, reference, payment_note, token),
            )
            cur.execute("UPDATE project_sandbox_state SET updated_at=NOW() WHERE project_id=%s", (project_id,))
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="payment", _anchor="deposit-project-start"))


@app.route("/admin/projects/<int:project_id>/sandbox/payments/<int:payment_id>/void", methods=["POST"])
@admin_required
def admin_project_sandbox_payment_void(project_id, payment_id):
    validate_csrf()
    if request.form.get('_ibrows_confirmed_action') != '1':
        abort(400)
    reason = _project_clean(request.form.get("void_reason"), 300)
    if not reason:
        abort(400)
    quote_item = _latest_accepted_project_quotation(project_id)
    sandbox = _project_sandbox_state(project_id, quote_item)
    if not sandbox or not sandbox.get("enabled"):
        abort(409)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE project_sandbox_payments
                SET voided_at=NOW(), void_reason=%s
                WHERE id=%s AND project_id=%s AND quotation_id=%s AND voided_at IS NULL
                RETURNING id
                """,
                (reason, payment_id, project_id, quote_item["id"]),
            )
            if not cur.fetchone():
                abort(404)
            cur.execute("UPDATE project_sandbox_state SET updated_at=NOW() WHERE project_id=%s", (project_id,))
        conn.commit()
    # A void must also unwind any sandbox state that depended on the removed
    # payment. If the deposit itself falls below threshold, the simulated start
    # is no longer valid. If only a later stage becomes underpaid, preserve the
    # simulated work but reopen a previously completed sandbox execution.
    new_state = _project_sandbox_state(project_id, quote_item)
    if new_state and new_state.get("started") and not new_state.get("deposit_verified"):
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE project_sandbox_state SET sandbox_started_at=NULL, start_note=NULL, execution_plan='{}'::jsonb, execution_updates='[]'::jsonb, updated_at=NOW() WHERE project_id=%s",
                    (project_id,),
                )
            conn.commit()
    elif new_state and new_state.get("started"):
        execution_state = _sandbox_execution_state(project_id, quote_item)
        if execution_state and execution_state.get("status") == "COMPLETED":
            payment_summary = _execution_payment_summary(project_id, quote_item, sandbox_state=new_state)
            if not payment_summary or not _execution_can_complete(execution_state, payment_summary):
                execution_state["status"] = "IN_PROGRESS"
                _sandbox_save_execution(project_id, execution_state, execution_state.get("updates") or [])
    return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="voided", _anchor="deposit-project-start"))


