    for obj_id in range(1,max_id+1): offsets[obj_id]=len(out); out.extend(f"{obj_id} 0 obj\n".encode("ascii")); out.extend(objects[obj_id]); out.extend(b"\nendobj\n")
    xref=len(out); out.extend(f"xref\n0 {max_id+1}\n".encode("ascii")); out.extend(b"0000000000 65535 f \n")
    for obj_id in range(1,max_id+1): out.extend(f"{offsets[obj_id]:010d} 00000 n \n".encode("ascii"))
    out.extend(f"trailer\n<< /Size {max_id+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF".encode("ascii")); return bytes(out)


