@app.route("/admin/projects/<int:project_id>/execution/invoices/<stage>/create", methods=["POST"])
@admin_required
def admin_project_stage_invoice_create(project_id,stage):
    validate_csrf(); stage=str(stage or "").upper()
    if stage not in PROJECT_STAGE_INVOICE_LABELS: abort(404)
    # V85: derive the invoice's initial status from the verified ledger while
    # holding the same project -> accepted quotation locks used by payment
    # recording. This closes the race where a payment could commit after an
    # out-of-transaction summary read but before the invoice insert, leaving a
    # newly created invoice stale until some later page happened to resync it.
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(project_id,))
            if not cur.fetchone(): abort(404)
            quote=_v43_locked_quote(cur,project_id)
            if not quote: abort(400)
            cur.execute("SELECT quotation_id,status FROM project_execution WHERE project_id=%s FOR UPDATE",(project_id,))
            execution=cur.fetchone()
            if not execution or execution[0]!=quote["id"] or execution[1] not in {"IN_PROGRESS","COMPLETED"}: abort(400)
            cur.execute("SELECT enabled FROM project_sandbox_state WHERE project_id=%s AND quotation_id=%s FOR UPDATE",(project_id,quote["id"]))
            sandbox=cur.fetchone()
            if sandbox and sandbox[0]: abort(409)
            required_by_stage=_execution_required_amounts(quote)
            stage_required=_money_decimal(required_by_stage.get(stage,Decimal("0")))
            if stage_required<=0: abort(400)
            cur.execute("SELECT COALESCE(SUM(amount),0) FROM project_payments WHERE quotation_id=%s AND stage=%s",(quote["id"],stage))
            stage_paid=_money_decimal((cur.fetchone() or [0])[0])
            invoice_status="PAID" if stage_paid>=stage_required else ("PART_PAID" if stage_paid>0 else "UNPAID")
            year=datetime.now(ADMIN_TIMEZONE).year; suffix="M2" if stage=="MILESTONE_2" else "F"; number=f"IBR-INV-{year}-{project_id:04d}-{suffix}R{int(quote.get('revision_no') or 1)}"
            currency=quote.get("currency") or "MWK"
            cur.execute(
                """
                INSERT INTO project_stage_invoices(
                    project_id,quotation_id,stage,invoice_number,amount,currency,status,paid_at,updated_at
                ) VALUES(%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s='PAID' THEN NOW() ELSE NULL END,NOW())
                ON CONFLICT(quotation_id,stage) DO UPDATE SET
                    status=CASE WHEN project_stage_invoices.status='VOID' THEN project_stage_invoices.status ELSE EXCLUDED.status END,
                    paid_at=CASE
                        WHEN project_stage_invoices.status='VOID' THEN project_stage_invoices.paid_at
                        WHEN EXCLUDED.status='PAID' THEN COALESCE(project_stage_invoices.paid_at,NOW())
                        ELSE NULL
                    END,
                    updated_at=CASE WHEN project_stage_invoices.status='VOID' THEN project_stage_invoices.updated_at ELSE NOW() END
                RETURNING id
                """,
                (project_id,quote["id"],stage,number,stage_required,currency,invoice_status,invoice_status),
            ); created=cur.fetchone()
            if created: _project_activity_insert(cur,project_id,"STAGE_INVOICE_CREATED",f"{PROJECT_STAGE_INVOICE_LABELS[stage]} invoice {number} created/reconciled for {currency} {stage_required:,.0f} with ledger status {invoice_status}.")
        conn.commit()
    return redirect(url_for("admin_project_execution",project_id=project_id,_anchor="payment-schedule"))


