# -------------------------
# Cost-sheet hardening
# -------------------------

def _xlsx_rows(raw):
    rows=[]
    max_uncompressed=8*1024*1024
    max_rows=5000
    max_cols=100
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        infos=zf.infolist()
        if sum(int(info.file_size or 0) for info in infos) > max_uncompressed:
            raise ValueError("The XLSX expands beyond the safe 8 MB processing limit.")
        shared=[]
        if "xl/sharedStrings.xml" in zf.namelist():
            info=zf.getinfo("xl/sharedStrings.xml")
            if info.file_size > 4*1024*1024:
                raise ValueError("The XLSX shared-string table is too large.")
            root=ET.fromstring(zf.read("xl/sharedStrings.xml"))
            ns={"a":"http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
            for si in root.findall("a:si",ns):
                shared.append("".join((t.text or "") for t in si.findall(".//a:t",ns)))
                if len(shared)>20000:
                    raise ValueError("The XLSX contains too many shared strings.")
        sheet_name="xl/worksheets/sheet1.xml"
        if sheet_name not in zf.namelist():
            candidates=sorted(x for x in zf.namelist() if x.startswith("xl/worksheets/sheet") and x.endswith(".xml"))
            if not candidates: return rows
            sheet_name=candidates[0]
        if zf.getinfo(sheet_name).file_size > max_uncompressed:
            raise ValueError("The XLSX worksheet expands beyond the safe processing limit.")
        root=ET.fromstring(zf.read(sheet_name))
        ns={"a":"http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
        def col_index(ref):
            letters=re.match(r"[A-Z]+",ref or "A"); n=0
            for ch in (letters.group(0) if letters else "A"):
                n=n*26+(ord(ch)-64)
            return n-1
        for row_index,row in enumerate(root.findall(".//a:sheetData/a:row",ns),start=1):
            if row_index>max_rows: raise ValueError("The XLSX contains too many rows.")
            vals={}; max_idx=-1
            for cell in row.findall("a:c",ns):
                idx=col_index(cell.get("r","A1"))
                if idx>=max_cols: raise ValueError("The XLSX contains too many columns.")
                max_idx=max(max_idx,idx); t=cell.get("t")
                if t=="inlineStr":
                    value="".join((x.text or "") for x in cell.findall(".//a:t",ns))
                else:
                    vnode=cell.find("a:v",ns); value=vnode.text if vnode is not None and vnode.text is not None else ""
                    if t=="s" and value!="":
                        try: value=shared[int(value)]
                        except Exception: pass
                vals[idx]=value
            if max_idx>=0: rows.append([vals.get(i,"") for i in range(max_idx+1)])
    return rows


def _admin_project_costing_import_v43(project_id):
    validate_csrf(); project=_get_project_by_id(project_id)
    if not project or project.get("status") not in {"READY_FOR_COSTING","QUOTED","ACCEPTED","DECLINED"}: abort(404)
    uploaded=request.files.get("price_sheet")
    if not uploaded or not uploaded.filename:
        imported={"components":[],"commercial":{},"unmatched":[],"internal_total":"0"}
        return render_template_string(PROJECT_COST_IMPORT_PREVIEW_TEMPLATE,project=project,imported=imported,csrf_token=get_csrf_token(),error="Choose a price sheet first."),400
    try:
        rows=_uploaded_cost_sheet_rows(uploaded); imported=_parse_cost_sheet_rows(rows)
    except Exception as exc:
        imported={"components":[],"commercial":{},"unmatched":[],"internal_total":"0"}
        return render_template_string(PROJECT_COST_IMPORT_PREVIEW_TEMPLATE,project=project,imported=imported,csrf_token=get_csrf_token(),error=str(exc)),400
    token=secrets.token_urlsafe(24)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM project_cost_import_staging WHERE project_id=%s",(project_id,))
            cur.execute("INSERT INTO project_cost_import_staging(token,project_id,payload,expires_at) VALUES(%s,%s,%s::jsonb,NOW()+(%s*INTERVAL '1 minute'))",(token,project_id,json.dumps(imported),V43_COST_IMPORT_TTL_MINUTES))
        conn.commit()
    session[f"cost_sheet_import_token_{project_id}"]=token
    return render_template_string(PROJECT_COST_IMPORT_PREVIEW_TEMPLATE,project=project,imported=imported,csrf_token=get_csrf_token(),error=""),200


def _admin_project_costing_import_apply_v43(project_id):
    validate_csrf(); project=_get_project_by_id(project_id)
    if not project or project.get("status") not in {"READY_FOR_COSTING","QUOTED","ACCEPTED","DECLINED"}: abort(404)
    token=session.pop(f"cost_sheet_import_token_{project_id}",None)
    if not token: return redirect(url_for("admin_project_costing",project_id=project_id))
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT payload FROM project_cost_import_staging WHERE token=%s AND project_id=%s AND expires_at>NOW() FOR UPDATE",(token,project_id)); row=cur.fetchone()
            if not row:
                conn.commit(); return redirect(url_for("admin_project_costing",project_id=project_id))
            imported=row[0] if isinstance(row[0],dict) else json.loads(row[0] or "{}")
            cur.execute("DELETE FROM project_cost_import_staging WHERE token=%s",(token,))
        conn.commit()
    if not imported.get("components"): return redirect(url_for("admin_project_costing",project_id=project_id))
    form_data=_cost_sheet_to_form(project,imported); _save_project_costing(project,form_data)
