_V42_GET_STANDING_CONSENT=get_career_assist_standing_consent

def get_career_assist_standing_consent(customer_number):
    state=_V42_GET_STANDING_CONSENT(customer_number)
    state=dict(state or {})
    # V43 deliberately disables standing/automatic submission authority.
    # Stored events remain as audit history, but each vacancy needs fresh approval.
    state["effective"]=False
    return state


def handle_career_assist_standing_consent(customer_number,customer_message):
    if detect_career_assist_standing_consent_revoke(customer_message):
        current=_V42_GET_STANDING_CONSENT(customer_number)
        lead_id=current.get("lead_id")
        if current.get("event_type")=="GRANT":
            _record_career_assist_consent_event(customer_number,lead_id,"REVOKE","V43 policy: vacancy-specific submission approval is required.")
        return ("Standing/automatic application submission is disabled. IBROWS will continue vacancy discovery and preparation, but each specific vacancy requires your fresh approval before any employer submission step.")
    if detect_career_assist_standing_consent_grant(customer_message):
        return ("For your protection, IBROWS no longer enables standing or automatic job-application submission authority. I can keep searching within your preferences and prepare applications, but I will ask for approval for each specific vacancy before submission.")
    return None


def _v43_disable_legacy_standing_consent():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                WITH latest AS (
                    SELECT DISTINCT ON (customer_number) id,customer_number,career_assist_lead_id,event_type
                    FROM career_assist_application_consent_events
                    ORDER BY customer_number,created_at DESC,id DESC
                )
                SELECT customer_number,career_assist_lead_id FROM latest WHERE event_type='GRANT'
            """)
            rows=cur.fetchall()
            for number,lead_id in rows:
                cur.execute("INSERT INTO career_assist_application_consent_events(customer_number,career_assist_lead_id,event_type,scope_text) VALUES(%s,%s,'REVOKE',%s)",(number,lead_id,"V43 migration: standing application submission authority disabled; vacancy-specific approval required."))
                if lead_id: _activity_insert(cur,lead_id,"APPLICATION_CONSENT_REVOKED","V43 disabled standing submission authority; future vacancies require specific customer approval.")
        conn.commit()


