def _public_project_quotation_v43(public_token):
    quote=_get_project_quotation_by_token(public_token)
    if not quote: abort(404)
    # V60: use the same authoritative expiry + client-view audit path as the
    # original public route. V43 previously replaced the registered view function
    # and accidentally skipped VIEWED persistence entirely.
    quote=_sync_project_quotation_expiry(quote)
    quote=_record_project_quotation_client_view(quote)
    response_nonce=""
    nonce_key=f"quote_response_nonce_{quote['id']}"
    if quote.get("status") in {"ISSUED","VIEWED"}:
        response_nonce=secrets.token_urlsafe(20)
        session[nonce_key]=response_nonce
    else:
        # Non-actionable quotations render no response form. Do not accumulate
        # unused response nonces in the client's cookie-backed session.
        session.pop(nonce_key,None)
    html=render_template_string(PROJECT_QUOTATION_PUBLIC_TEMPLATE,quote=quote,preview_only=False,response_nonce=response_nonce,pdf_url=url_for("public_project_quotation_pdf",public_token=public_token),commercial_state=_project_commercial_state(quote["project_id"],quote,sync=False) if quote.get("status")=="ACCEPTED" else None,deposit_invoice_url=(url_for("public_project_deposit_invoice_pdf",public_token=public_token) if quote.get("status")=="ACCEPTED" else ""))
    return html,200,{"Cache-Control":"no-store, private","Pragma":"no-cache"}


def _public_project_quotation_respond_v43(public_token):
    quote=_get_project_quotation_by_token(public_token)
    if not quote: abort(404)
    nonce=str(request.form.get("response_nonce") or ""); expected=str(session.pop(f"quote_response_nonce_{quote['id']}","") or "")
    if not nonce or not expected or not hmac.compare_digest(nonce,expected): abort(400)
    if request.form.get("authorized")!="1": abort(400)
    decision=_project_clean(request.form.get("decision"),20).upper(); responded_by=_project_clean(request.form.get("responded_by"),160); response_note=_project_clean(request.form.get("response_note"),1200)
    if decision not in {"ACCEPTED","DECLINED"} or not responded_by: abort(400)
    conflict=False
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(quote["project_id"],))
            cur.execute(_quotation_select_sql()+" WHERE id=%s FOR UPDATE",(quote["id"],)); row=cur.fetchone()
            if not row: abort(404)
            current=_quotation_row_to_dict(row)
            if current.get("status") not in {"ISSUED","VIEWED"}: conn.commit(); return redirect(url_for("public_project_quotation",public_token=public_token))
            if current.get("valid_until") and current["valid_until"] <= datetime.now(UTC_TIMEZONE):
                cur.execute("UPDATE project_quotations SET status='EXPIRED',updated_at=NOW() WHERE id=%s",(current["id"],))
                _quote_event_insert(cur,current["id"],"EXPIRED","Quotation validity period expired before the client response was submitted.")
                _project_activity_insert(cur,current["project_id"],"QUOTE_EXPIRED",f"Quotation {current['quote_reference']} expired before the client response was submitted.")
                conn.commit()
                return redirect(url_for("public_project_quotation",public_token=public_token))
            if decision=="ACCEPTED":
                cur.execute("SELECT id,quote_reference FROM project_quotations WHERE project_id=%s AND status='ACCEPTED' AND id<>%s FOR UPDATE",(current["project_id"],current["id"])); other=cur.fetchone()
                if other:
                    old_quote_id, old_quote_reference = other
                    cur.execute(
                        """
                        SELECT
                            EXISTS(SELECT 1 FROM project_payments WHERE quotation_id=%s)
                            OR EXISTS(SELECT 1 FROM project_execution WHERE quotation_id=%s)
                            OR EXISTS(
                                SELECT 1 FROM project_sandbox_state
                                WHERE project_id=%s AND quotation_id=%s AND enabled=TRUE
                            )
                        """,
                        (old_quote_id,old_quote_id,current["project_id"],old_quote_id),
                    ); busy=bool(cur.fetchone()[0])
                    if busy:
                        conflict=True
                    else:
                        cur.execute("UPDATE project_quotations SET status='SUPERSEDED',updated_at=NOW() WHERE id=%s",(old_quote_id,))
                        # An accepted quote automatically owns a deposit invoice. If the
                        # quote is safely replaced before any payment or execution, that
                        # invoice must stop appearing in receivables while remaining in
                        # the immutable finance/export history.
                        cur.execute("UPDATE project_invoices SET status='VOID',paid_at=NULL,updated_at=NOW() WHERE quotation_id=%s AND status<>'VOID' RETURNING invoice_number",(old_quote_id,))
                        old_invoice=cur.fetchone()
                        if old_invoice:
                            _quote_event_insert(cur,old_quote_id,"DEPOSIT_INVOICE_VOIDED_SUPERSEDED",f"Deposit invoice {old_invoice[0]} voided because quotation {old_quote_reference} was superseded before verified payment or project execution.")
                            _project_activity_insert(cur,current["project_id"],"SUPERSEDED_INVOICE_VOIDED",f"Deposit invoice {old_invoice[0]} from superseded quotation {old_quote_reference} was voided before the replacement quotation was accepted.")
                if not conflict:
                    cur.execute("UPDATE project_quotations SET status='SUPERSEDED',updated_at=NOW() WHERE project_id=%s AND id<>%s AND status IN ('ISSUED','VIEWED')",(current["project_id"],current["id"]))
                    cur.execute("UPDATE project_quotations SET status='ACCEPTED',responded_at=NOW(),responded_by=%s,response_note=NULLIF(%s,''),accepted_at=NOW(),updated_at=NOW() WHERE id=%s",(responded_by,response_note,current["id"]))
                    cur.execute("UPDATE project_assessments SET status='ACCEPTED',portal_token=COALESCE(portal_token,%s),updated_at=NOW() WHERE id=%s",(secrets.token_urlsafe(32),current["project_id"]))
                    current["status"]="ACCEPTED"
                    _v43_ensure_deposit_invoice_locked(cur,current)
                    _quote_event_insert(cur,current["id"],"ACCEPTED",f"Quotation accepted by {responded_by}. Acceptance does not record payment."); _project_activity_insert(cur,current["project_id"],"QUOTE_ACCEPTED",f"Quotation {current['quote_reference']} accepted by {responded_by}; awaiting payment/deposit confirmation.")
            else:
                cur.execute("UPDATE project_quotations SET status='DECLINED',responded_at=NOW(),responded_by=%s,response_note=NULLIF(%s,''),declined_at=NOW(),updated_at=NOW() WHERE id=%s",(responded_by,response_note,current["id"]))
                cur.execute("SELECT 1 FROM project_quotations WHERE project_id=%s AND status='ACCEPTED' LIMIT 1",(current["project_id"],)); has_accepted=cur.fetchone() is not None
                cur.execute("UPDATE project_assessments SET status=%s,updated_at=NOW() WHERE id=%s",("ACCEPTED" if has_accepted else "DECLINED",current["project_id"]))
                _quote_event_insert(cur,current["id"],"DECLINED",f"Quotation declined by {responded_by}."); _project_activity_insert(cur,current["project_id"],"QUOTE_DECLINED",f"Quotation {current['quote_reference']} declined by {responded_by}.")
        if conflict:
            conn.rollback()
        else:
            conn.commit()
    if conflict:
        return Response("This project already has an accepted quotation with verified commercial activity or an active Sandbox simulation. IBROWS must reconcile the live revision or exit Sandbox before a replacement quotation can be accepted.",status=409,mimetype="text/plain")
    return redirect(url_for("public_project_quotation",public_token=public_token))

