def _v68_sync_stage_invoice_statuses_locked(cur, quote_item):
    """Keep milestone/final invoice state consistent with the verified ledger.

    This runs inside the same serialized payment transaction so Finance and
    receivables never depend on an admin later opening the execution page to
    refresh invoice status.
    """
    if not quote_item:
        return
    required_by_stage = _execution_required_amounts(quote_item)
    cur.execute(
        "SELECT stage,COALESCE(SUM(amount),0) FROM project_payments WHERE quotation_id=%s GROUP BY stage",
        (quote_item["id"],),
    )
    paid_by_stage = {row[0]: Decimal(row[1] or 0) for row in cur.fetchall()}
    cur.execute(
        "SELECT id,stage FROM project_stage_invoices WHERE quotation_id=%s AND status<>'VOID' FOR UPDATE",
        (quote_item["id"],),
    )
    for invoice_id, stage in cur.fetchall():
        required = required_by_stage.get(stage, Decimal("0"))
        paid = paid_by_stage.get(stage, Decimal("0"))
        status = "PAID" if required > 0 and paid >= required else ("PART_PAID" if paid > 0 else "UNPAID")
        cur.execute(
            "UPDATE project_stage_invoices SET status=%s,paid_at=CASE WHEN %s='PAID' THEN COALESCE(paid_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND status<>'VOID'",
            (status, status, invoice_id),
        )


def _admin_project_payment_record_v43(project_id):
    validate_csrf(); token=_project_clean(request.form.get("payment_request_token"),160)
    if not token: abort(400)
    try: amount=_crm_payment_amount(request.form.get("amount"))
    except ValueError: abort(400)
    if amount is None: abort(400)
    method=_crm_payment_method(request.form.get("payment_method")); stage=_project_clean(request.form.get("stage"),40).upper()
    if stage not in {"DEPOSIT","MILESTONE_2","FINAL"}: abort(400)
    reference=_project_clean(request.form.get("reference"),180); note=_project_clean(request.form.get("payment_note"),1000)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(project_id,))
            if not cur.fetchone(): abort(404)
            quote=_v43_locked_quote(cur,project_id)
            if not quote: abort(400)
            cur.execute("SELECT 1 FROM project_payment_void_audit WHERE request_token=%s",(token,))
            if cur.fetchone(): abort(409)
            cur.execute("SELECT id FROM project_payments WHERE request_token=%s",(token,)); existing=cur.fetchone()
            if existing:
                conn.commit(); return redirect(url_for("admin_project_detail", project_id=project_id, _anchor="deposit-project-start"))
            invoice=_v43_ensure_deposit_invoice_locked(cur,quote); paid,final,deposit=_v43_quote_totals_locked(cur,quote); deposit_paid=_v43_deposit_paid_locked(cur,quote)
            if amount<=0 or amount>max(Decimal("0"),final-paid): abort(400)
            # Completion is stage-gated as well as total-value-gated. Keep the
            # allocation valid inside the same serialized transaction.
            stage_required=_execution_required_amounts(quote).get(stage,Decimal("0"))
            cur.execute("SELECT COALESCE(SUM(amount),0) FROM project_payments WHERE quotation_id=%s AND stage=%s",(quote["id"],stage)); stage_paid=Decimal((cur.fetchone() or [0])[0] or 0)
            stage_remaining=max(Decimal("0"),stage_required-stage_paid)
            if stage_required<=0 or stage_remaining<=0 or amount>stage_remaining: abort(400)
            invoice_id=invoice["id"] if invoice and stage=="DEPOSIT" else None
            cur.execute("INSERT INTO project_payments(project_id,quotation_id,invoice_id,stage,amount,currency,payment_method,reference,payment_note,request_token,received_at) VALUES(%s,%s,%s,%s,%s,%s,%s,NULLIF(%s,''),NULLIF(%s,''),%s,NOW()) RETURNING id",(project_id,quote["id"],invoice_id,stage,amount,quote.get("currency") or "MWK",method,reference,note,token)); payment_id=cur.fetchone()[0]
            new_paid=paid+amount; new_deposit_paid=deposit_paid+(amount if stage=="DEPOSIT" else Decimal("0")); deposit_verified=deposit>0 and new_deposit_paid>=deposit; invoice_status="PAID" if deposit_verified else ("PART_PAID" if new_deposit_paid>0 else "UNPAID")
            if invoice: cur.execute("UPDATE project_invoices SET status=%s,paid_at=CASE WHEN %s='PAID' THEN COALESCE(paid_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND status<>'VOID'",(invoice_status,invoice_status,invoice["id"]))
            _v68_sync_stage_invoice_statuses_locked(cur, quote)
            cur.execute("SELECT status FROM project_execution WHERE project_id=%s",(project_id,)); erow=cur.fetchone(); project_status="IN_PROGRESS" if erow and erow[0]=="IN_PROGRESS" else ("COMPLETED" if erow and erow[0]=="COMPLETED" else ("DEPOSIT_PAID" if deposit_verified else "ACCEPTED"))
            cur.execute("UPDATE project_assessments SET status=%s,updated_at=NOW() WHERE id=%s",(project_status,project_id))
            _project_activity_insert(cur,project_id,"PAYMENT_VERIFIED",f"Verified project payment recorded: {quote.get('currency') or 'MWK'} {amount:,.0f} ({PROJECT_PAYMENT_STAGE_LABELS[stage]}). Ledger payment ID {payment_id}."); _quote_event_insert(cur,quote["id"],"PAYMENT_VERIFIED",f"IBROWS recorded a verified payment of {quote.get('currency') or 'MWK'} {amount:,.0f}.")
            if deposit_verified and deposit_paid<deposit: _project_activity_insert(cur,project_id,"DEPOSIT_VERIFIED",f"Required deposit threshold reached from verified DEPOSIT-stage payments: {quote.get('currency') or 'MWK'} {deposit:,.0f}. Project is ready for explicit IBROWS start approval.")
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id, _anchor="deposit-project-start"))


def _admin_project_payment_void_v43(project_id,payment_id):
    validate_csrf()
    if request.form.get('_ibrows_confirmed_action') != '1':
        abort(400)
    reason=_project_clean(request.form.get("void_reason"),300)
    if not reason: abort(400)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(project_id,));
            if not cur.fetchone(): abort(404)
            cur.execute("SELECT id,project_id,quotation_id,invoice_id,stage,amount,currency,payment_method,reference,payment_note,request_token,received_at FROM project_payments WHERE id=%s AND project_id=%s FOR UPDATE",(payment_id,project_id)); row=cur.fetchone()
            if not row: abort(404)
