def _public_project_status_v43(public_token):
    project=_get_project_by_portal_token(public_token)
    if not project: abort(404)
    execution=_execution_live_rows(project["id"])
    if not execution: abort(404)
    quote=_get_project_quotation_by_id(execution.get("quotation_id"))
    if not quote or quote.get("status")!="ACCEPTED": abort(404)
    milestones=[m for m in execution.get("milestones",[]) if m.get("client_visible")]; updates=[u for u in execution.get("updates",[]) if u.get("published")]
    commercial=_project_commercial_state(project["id"],quote,sync=False); stage_invoices=_execution_stage_invoices(project["id"],quote,sync=False)
    return render_template_string(PROJECT_STATUS_PUBLIC_TEMPLATE,project=project,quote=quote,execution=execution,milestones=milestones,updates=updates,commercial=commercial,stage_invoices=stage_invoices,preview_mode=False,display_status_label="",portal_token=public_token),200


def _public_project_stage_invoice_pdf_v43(public_token,stage):
    project=_get_project_by_portal_token(public_token); stage=str(stage or "").upper()
    if not project or stage not in PROJECT_STAGE_INVOICE_LABELS: abort(404)
    execution=_get_project_execution(project["id"])
    if not execution: abort(404)
    quote=_get_project_quotation_by_id(execution.get("quotation_id"))
    if not quote or quote.get("status")!="ACCEPTED": abort(404)
    invoices=_execution_stage_invoices(project["id"],quote,sync=False); inv=next((i for i in invoices if i["stage"]==stage),None)
    if not inv: abort(404)
    pdf=_execution_stage_invoice_pdf_bytes(inv,quote,_execution_payment_summary(project["id"],quote)); return Response(pdf,mimetype="application/pdf",headers={"Content-Disposition":f'attachment; filename="{inv["invoice_number"]}.pdf"'})

app.view_functions["public_project_status"]=_public_project_status_v43
app.view_functions["public_project_stage_invoice_pdf"]=_public_project_stage_invoice_pdf_v43


