def _project_commercial_state(project_id,quote_item=None,sync=True):
    quote_item=quote_item or _latest_accepted_project_quotation(project_id)
    if not quote_item or quote_item.get("status")!="ACCEPTED": return None
    if sync:
        invoice=_ensure_project_deposit_invoice(quote_item)
    else:
        invoice=_get_project_invoice_by_quotation(quote_item["id"])
    payments=_project_payment_rows(project_id,quote_item["id"])
    total_paid=sum((_money_decimal(x.get("amount")) for x in payments),Decimal("0"))
    deposit_paid=sum((_money_decimal(x.get("amount")) for x in payments if x.get("stage")=="DEPOSIT"),Decimal("0"))
    final_price=_money_decimal(quote_item["pricing"].get("final_price")); deposit_required=_money_decimal(quote_item["pricing"].get("deposit_amount"))
    deposit_applied=min(deposit_paid,deposit_required); deposit_remaining=max(Decimal("0"),deposit_required-deposit_paid); total_remaining=max(Decimal("0"),final_price-total_paid); deposit_verified=deposit_required>0 and deposit_paid>=deposit_required; fully_paid=final_price>0 and total_paid>=final_price; execution=_get_project_execution(project_id); desired=("COMPLETED" if execution and execution.get("status")=="COMPLETED" else "IN_PROGRESS" if execution and execution.get("status")=="IN_PROGRESS" else "DEPOSIT_PAID" if deposit_verified else "ACCEPTED")
    invoice_status="PAID" if deposit_verified else "PART_PAID" if deposit_paid>0 else "UNPAID"
    if sync and invoice:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute("UPDATE project_invoices SET status=%s,paid_at=CASE WHEN %s='PAID' THEN COALESCE(paid_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND status<>'VOID'",(invoice_status,invoice_status,invoice["id"]))
                cur.execute("UPDATE project_assessments SET status=%s,updated_at=NOW() WHERE id=%s AND status IN ('ACCEPTED','DEPOSIT_PAID','IN_PROGRESS','COMPLETED')",(desired,project_id))
            conn.commit()
        invoice=_get_project_invoice_by_quotation(quote_item["id"])
    return {"quote":quote_item,"invoice":invoice,"payments":payments,"total_paid":total_paid,"deposit_paid":deposit_paid,"final_price":final_price,"deposit_required":deposit_required,"deposit_applied":deposit_applied,"deposit_remaining":deposit_remaining,"total_remaining":total_remaining,"deposit_verified":deposit_verified,"fully_paid":fully_paid,"execution":execution,"project_status":desired,"currency":quote_item.get("currency") or "MWK"}

def _execution_stage_invoices(project_id,quote_item=None,sync=True):
    quote_item=quote_item or _latest_accepted_project_quotation(project_id)
    if not quote_item: return []
    summary=_execution_payment_summary(project_id,quote_item); paid_map={x["stage"]:x["paid"] for x in summary["rows"]}; req_map={x["stage"]:x["required"] for x in summary["rows"]}
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id,project_id,quotation_id,stage,invoice_number,amount,currency,status,issued_at,paid_at,created_at,updated_at FROM project_stage_invoices WHERE project_id=%s AND quotation_id=%s ORDER BY issued_at,id",(project_id,quote_item["id"])); rows=cur.fetchall()
            if sync:
                for r in rows:
                    stage=r[3]; paid=paid_map.get(stage,Decimal("0")); req=req_map.get(stage,_money_decimal(r[5])); status="PAID" if req>0 and paid>=req else "PART_PAID" if paid>0 else "UNPAID"; cur.execute("UPDATE project_stage_invoices SET status=%s,paid_at=CASE WHEN %s='PAID' THEN COALESCE(paid_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND status<>'VOID'",(status,status,r[0]))
                conn.commit(); cur.execute("SELECT id,project_id,quotation_id,stage,invoice_number,amount,currency,status,issued_at,paid_at,created_at,updated_at FROM project_stage_invoices WHERE project_id=%s AND quotation_id=%s ORDER BY issued_at,id",(project_id,quote_item["id"])); rows=cur.fetchall()
    return [_stage_invoice_row_to_dict(r) for r in rows]


