# =========================================================
# V43 FINAL CONSISTENCY REMEDIATION
# Immutable receivables/export + privacy-safe snapshots
# =========================================================

def _v43_snapshot_decimal(value, default="0"):
    try:
        return Decimal(str(value if value not in (None, "") else default))
    except Exception:
        return Decimal(str(default))


def _v43_legacy_business_document_context(lead_id, payment_id=None):
    """Best-effort one-time snapshot source for pre-V43 documents.

    Historical V42 documents did not preserve their rendered fields, so their exact
    past bytes cannot be reconstructed. This freezes the best information still
    available at migration time and prevents any further drift.
    """
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id,customer_number,customer_name,service,summary,status,priority,
                       estimated_value,COALESCE(value_currency,'MWK'),quote_status,
                       COALESCE(quote_reference,'')
                FROM leads WHERE id=%s
                """,
                (lead_id,),
            )
            row=cur.fetchone()
            if not row:
                return None
            lead={
                "id":row[0],"customer_number":row[1],"customer_name":row[2] or "WhatsApp Customer",
                "service":canonicalize_service(row[3]),"summary":row[4] or "","status":row[5],
                "priority":row[6] or "NORMAL","estimated_value":Decimal(row[7]) if row[7] is not None else None,
                "value_currency":row[8] or "MWK","quote_status":row[9] or "NOT_STARTED","quote_reference":row[10] or "",
            }
            cur.execute(
                """SELECT id,amount,currency,payment_method,reference,payment_note,received_at
                   FROM lead_payments WHERE lead_id=%s ORDER BY received_at,id""",
                (lead_id,),
            )
            rows=cur.fetchall()
            if payment_id is not None and not any(r[0]==payment_id for r in rows):
                cur.execute(
                    """SELECT id,amount,currency,payment_method,reference,payment_note,received_at
                       FROM lead_payments WHERE id=%s""",
                    (payment_id,),
                )
                extra=cur.fetchone()
                if extra: rows.append(extra)
    payments=[{"id":r[0],"amount":Decimal(r[1]),"currency":r[2],"payment_method":r[3],"reference":r[4] or "","payment_note":r[5] or "","received_at":r[6]} for r in rows]
    selected=next((x for x in payments if payment_id is not None and x["id"]==payment_id),None)
    if selected is None and payments: selected=payments[-1]
    currency=lead["value_currency"]
    paid=sum((x["amount"] for x in payments if x["currency"]==currency),Decimal("0"))
    lead["payments"]=payments; lead["selected_payment"]=selected; lead["paid_total"]=paid
    lead["balance"]=max(lead["estimated_value"]-paid,Decimal("0")) if lead["estimated_value"] is not None else None
    return lead


def _v43_backfill_business_document_snapshots():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id,lead_id,payment_id FROM business_documents WHERE snapshot IS NULL AND COALESCE(document_status,'ACTIVE')<>'VOID' ORDER BY id")
            rows=cur.fetchall()
    frozen=0
    for doc_id,lead_id,payment_id in rows:
        try:
            context=get_business_document_context(lead_id,payment_id=payment_id)
            if context is None:
                context=_v43_legacy_business_document_context(lead_id,payment_id)
            if not context:
                continue
            snapshot=_v43_business_snapshot_from_context(context,payment_id)
            snapshot["legacy_v42_snapshot_frozen_at_migration"] = True
            with get_db() as conn:
                with conn.cursor() as cur:
                    cur.execute("UPDATE business_documents SET snapshot=COALESCE(snapshot,%s::jsonb) WHERE id=%s",(json.dumps(snapshot),doc_id))
                conn.commit()
            frozen+=1
        except Exception as exc:
            print(f"V43 LEGACY DOCUMENT SNAPSHOT BACKFILL SKIPPED: document={doc_id} error={type(exc).__name__}",flush=True)
    if frozen:
        print(f"V43 LEGACY DOCUMENT SNAPSHOTS FROZEN: {frozen}",flush=True)


def _v43_anonymize_business_document_snapshots(cur, lead_ids):
    if not lead_ids:
        return
    cur.execute(
        """
        UPDATE business_documents
        SET snapshot = jsonb_set(
            jsonb_set(
                jsonb_set(COALESCE(snapshot,'{}'::jsonb),'{customer_name}',to_jsonb('Deleted customer'::text),true),
                '{customer_number}',to_jsonb(''::text),true
            ),
            '{summary}',to_jsonb('Commercial service record retained for accounting/audit.'::text),true
        )
        WHERE lead_id=ANY(%s) AND snapshot IS NOT NULL
        """,
        (lead_ids,),
    )


def _v43_anonymize_project_quote_snapshots(cur, project_id):
    client=json.dumps({"organisation":"","contact_name":"Deleted customer","email":"","phone":""})
    cur.execute("SELECT id FROM project_quotations WHERE project_id=%s FOR UPDATE",(project_id,))
    quote_ids=[r[0] for r in cur.fetchall()]
    for quote_id in quote_ids:
        cur.execute(
            """
            UPDATE project_quotations
            SET snapshot=jsonb_set(COALESCE(snapshot,'{}'::jsonb),'{client}',%s::jsonb,true),
                public_token=%s,updated_at=NOW()
            WHERE id=%s
            """,
            (client,"revoked-"+secrets.token_urlsafe(24),quote_id),
        )


def delete_customer_data(customer_number):
    """V43 complete erasure with finance-safe, privacy-safe immutable snapshots."""
    customer_number=str(customer_number or "").strip()
    if not customer_number:
        raise ValueError("Customer number is required.")
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM leads WHERE customer_number=%s FOR UPDATE",(customer_number,))
            original_lead_ids=[r[0] for r in cur.fetchall()]
        conn.commit()
    _V42_DELETE_CUSTOMER_DATA(customer_number)
    normalized=re.sub(r"\D","",customer_number)
    with get_db() as conn:
        with conn.cursor() as cur:
            _v43_anonymize_business_document_snapshots(cur,original_lead_ids)
            cur.execute("DELETE FROM customer_menu_state WHERE customer_number=%s",(customer_number,))
            cur.execute("DELETE FROM career_assist_application_consent_events WHERE customer_number=%s",(customer_number,))
            cur.execute("DELETE FROM application_confirmation_evidence WHERE customer_number=%s",(customer_number,))
            cur.execute("DELETE FROM career_verified_vacancies WHERE customer_number=%s",(customer_number,))
            cur.execute("DELETE FROM career_assist_applications WHERE customer_number=%s",(customer_number,))
            cur.execute("DELETE FROM whatsapp_delivery_outbox WHERE customer_number=%s",(customer_number,))
            if normalized:
                cur.execute("SELECT id FROM project_assessments WHERE regexp_replace(COALESCE(phone,''),'[^0-9]','','g')=%s FOR UPDATE",(normalized,))
                project_ids=[r[0] for r in cur.fetchall()]
                for project_id in project_ids:
                    cur.execute("SELECT EXISTS(SELECT 1 FROM project_quotations WHERE project_id=%s) OR EXISTS(SELECT 1 FROM project_payments WHERE project_id=%s) OR EXISTS(SELECT 1 FROM project_execution WHERE project_id=%s)",(project_id,project_id,project_id))
                    commercial=bool(cur.fetchone()[0])
                    if not commercial:
                        cur.execute("DELETE FROM project_assessments WHERE id=%s",(project_id,))
                        continue
                    cur.execute("DELETE FROM project_notes WHERE project_id=%s",(project_id,))
                    cur.execute("""
                        UPDATE project_assessments SET contact_name='Deleted customer',organisation=NULL,phone=NULL,email=NULL,
                            answers='{}'::jsonb,ai_summary='Personal discovery data deleted; commercial record retained.',
                            ai_required_features='[]'::jsonb,ai_recommended_features='[]'::jsonb,ai_future_enhancements='[]'::jsonb,
                            ai_missing_information='[]'::jsonb,ai_risk_flags='[]'::jsonb,ai_cost_drivers='[]'::jsonb,ai_scope_reducers='[]'::jsonb,
                            portal_token=NULL,alert_last_error=NULL,updated_at=NOW() WHERE id=%s
                    """,(project_id,))
                    _v43_anonymize_project_quote_snapshots(cur,project_id)
        conn.commit()
    print("V43 CUSTOMER PRIVACY ERASURE COMPLETED WITH SNAPSHOT ANONYMIZATION",flush=True)


def delete_project_assessment_data(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(project_id,)); row=cur.fetchone()
            if not row: raise ValueError("Project not found")
            cur.execute("SELECT EXISTS(SELECT 1 FROM project_quotations WHERE project_id=%s) OR EXISTS(SELECT 1 FROM project_payments WHERE project_id=%s) OR EXISTS(SELECT 1 FROM project_execution WHERE project_id=%s)",(project_id,project_id,project_id)); commercial=bool(cur.fetchone()[0])
            if not commercial:
                cur.execute("DELETE FROM project_assessments WHERE id=%s",(project_id,)); action="deleted"
            else:
                cur.execute("DELETE FROM project_notes WHERE project_id=%s",(project_id,))
                cur.execute("""
                    UPDATE project_assessments SET contact_name='Deleted customer',organisation=NULL,phone=NULL,email=NULL,
                        answers='{}'::jsonb,ai_summary='Personal discovery data deleted; commercial record retained.',
                        ai_required_features='[]'::jsonb,ai_recommended_features='[]'::jsonb,ai_future_enhancements='[]'::jsonb,
                        ai_missing_information='[]'::jsonb,ai_risk_flags='[]'::jsonb,ai_cost_drivers='[]'::jsonb,ai_scope_reducers='[]'::jsonb,
                        portal_token=NULL,alert_last_error=NULL,updated_at=NOW() WHERE id=%s
                """,(project_id,))
                _v43_anonymize_project_quote_snapshots(cur,project_id); action="anonymized"
        conn.commit()
    return action


def _v43_receivable_fields(amount,paid,issued_at):
    amount=_v43_snapshot_decimal(amount); paid=min(_v43_snapshot_decimal(paid),amount) if amount>0 else _v43_snapshot_decimal(paid)
    balance=max(amount-paid,Decimal("0")); issued_local=issued_at.astimezone(ADMIN_TIMEZONE); due_local=issued_local+timedelta(days=BUSINESS_INVOICE_DUE_DAYS); days=(due_local.date()-datetime.now(ADMIN_TIMEZONE).date()).days
    if balance<=0 and amount>0:
        return amount,paid,balance,issued_local,due_local,"paid","Paid","Paid in full","Paid"
    payment_status="Part paid" if paid>0 else "Not paid"
    if days<0:
        n=abs(days); return amount,paid,balance,issued_local,due_local,"overdue","Overdue",f"Overdue by {n} day{'' if n==1 else 's'}",payment_status
    if days<=RECEIVABLE_DUE_SOON_DAYS:
        urgency="Due today" if days==0 else "Due tomorrow" if days==1 else f"Due in {days} days"
        return amount,paid,balance,issued_local,due_local,"due_soon","Due soon",urgency,payment_status
    return amount,paid,balance,issued_local,due_local,"open","Open",f"Due in {days} days",payment_status


def get_accounts_receivable_data(status_filter="all"):
    """Unified receivables using immutable CRM snapshots plus project invoices."""
    status_filter=status_filter if status_filter in RECEIVABLE_FILTERS else "all"; invoices=[]
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT d.id,d.lead_id,d.document_number,d.issued_at,d.last_sent_at,COALESCE(d.send_count,0),
                       d.due_soon_notified_at,d.overdue_notified_at,d.snapshot,
                       l.customer_number,l.customer_name,l.service,l.estimated_value,COALESCE(l.value_currency,'MWK'),
                       COALESCE(SUM(CASE WHEN p.currency=COALESCE(d.snapshot->>'value_currency',l.value_currency,'MWK') THEN p.amount ELSE 0 END),0)
                FROM business_documents d JOIN leads l ON l.id=d.lead_id
                LEFT JOIN lead_payments p ON p.lead_id=l.id
                WHERE d.doc_type='invoice' AND COALESCE(d.document_status,'ACTIVE')<>'VOID' AND l.merged_into_lead_id IS NULL
                GROUP BY d.id,l.id ORDER BY d.issued_at DESC,d.id DESC
            """); ordinary=cur.fetchall()
            cur.execute("""
                SELECT 'DEPOSIT',pi.id,pi.project_id,pi.quotation_id,NULL,pi.invoice_number,pi.amount,pi.currency,pi.issued_at,
                       pa.contact_name,pa.organisation,pa.project_type,COALESCE(SUM(pp.amount),0),
                       pi.due_soon_notified_at,pi.overdue_notified_at
                FROM project_invoices pi JOIN project_assessments pa ON pa.id=pi.project_id
                LEFT JOIN project_payments pp ON pp.quotation_id=pi.quotation_id AND pp.stage='DEPOSIT'
                WHERE pi.status<>'VOID' GROUP BY pi.id,pa.contact_name,pa.organisation,pa.project_type
                UNION ALL
                SELECT 'STAGE',si.id,si.project_id,si.quotation_id,si.stage,si.invoice_number,si.amount,si.currency,si.issued_at,
                       pa.contact_name,pa.organisation,pa.project_type,COALESCE(SUM(pp.amount),0),
                       si.due_soon_notified_at,si.overdue_notified_at
                FROM project_stage_invoices si JOIN project_assessments pa ON pa.id=si.project_id
                LEFT JOIN project_payments pp ON pp.quotation_id=si.quotation_id AND pp.stage=si.stage
                WHERE si.status<>'VOID' GROUP BY si.id,pa.contact_name,pa.organisation,pa.project_type
                ORDER BY 9 DESC
            """); project_rows=cur.fetchall()
    for doc_id,lead_id,number,issued,last_sent,send_count,due_notice,overdue_notice,snapshot,live_number,live_name,live_service,live_value,live_currency,paid in ordinary:
        snap=dict(snapshot or {}); currency=snap.get("value_currency") or live_currency or "MWK"; amount=snap.get("estimated_value") if snap.get("estimated_value") is not None else live_value
        amount,paid,balance,issued_local,due_local,sk,sl,urg,pstat=_v43_receivable_fields(amount,paid,issued)
        sent_count=int(send_count or 0); sent_label=(f"Sent {sent_count} time{'' if sent_count==1 else 's'}" + ((" · Last sent "+last_sent.astimezone(ADMIN_TIMEZONE).strftime('%d %b %Y %H:%M')) if last_sent else "")) if sent_count else "Generated · not sent yet"
        invoices.append({"document_id":doc_id,"lead_id":lead_id,"project_id":None,"stage":None,"invoice_kind":"BUSINESS","document_number":number,
            "customer_number":snap.get("customer_number") if snapshot else live_number,"customer_name":snap.get("customer_name") or live_name or "WhatsApp Customer",
            "service":canonicalize_service(snap.get("service") or live_service),"issued_at":issued,"issued_label":issued_local.strftime('%d %b %Y'),"due_label":due_local.strftime('%d %b %Y'),
            "estimated_value":amount,"value_label":_format_crm_amount(amount,currency),"paid_total":paid,"paid_label":_format_crm_amount(paid,currency),"balance":balance,"balance_label":_format_crm_amount(balance,currency),"currency":currency,
            "status_key":sk,"status_label":sl,"urgency_label":urg,"payment_status":pstat,"send_count":sent_count,"sent_label":sent_label,"due_soon_notified_at":due_notice,"overdue_notified_at":overdue_notice,
            "admin_reminder_label":"Overdue reminder sent to admin" if overdue_notice else "Due-soon reminder sent to admin" if due_notice else ""})
    for kind,doc_id,project_id,qid,stage,number,amount,currency,issued,contact,org,ptype,paid,due_notice,overdue_notice in project_rows:
        amount,paid,balance,issued_local,due_local,sk,sl,urg,pstat=_v43_receivable_fields(amount,paid,issued)
        invoices.append({"document_id":doc_id,"lead_id":None,"project_id":project_id,"stage":stage,"invoice_kind":kind,"document_number":number,"customer_number":"","customer_name":org or contact or "Project client","service":_v43_project_service_name(ptype),"issued_at":issued,"issued_label":issued_local.strftime('%d %b %Y'),"due_label":due_local.strftime('%d %b %Y'),"estimated_value":amount,"value_label":_format_crm_amount(amount,currency),"paid_total":paid,"paid_label":_format_crm_amount(paid,currency),"balance":balance,"balance_label":_format_crm_amount(balance,currency),"currency":currency,"status_key":sk,"status_label":sl,"urgency_label":urg,"payment_status":pstat,"send_count":0,"sent_label":"Project invoice · client portal","due_soon_notified_at":due_notice,"overdue_notified_at":overdue_notice,"admin_reminder_label":"Overdue reminder sent to admin" if overdue_notice else "Due-soon reminder sent to admin" if due_notice else ""})
    priority={"overdue":0,"due_soon":1,"open":2,"paid":3}; invoices.sort(key=lambda x:(priority.get(x["status_key"],9),x["issued_at"])); visible=invoices if status_filter=="all" else [x for x in invoices if x["status_key"]==status_filter]
    outstanding={}; overdue={}; due_soon={}; counts={"open":0,"due_soon":0,"overdue":0,"paid":0}
    for inv in invoices:
        counts[inv["status_key"]]+=1
        if inv["balance"]>0:
            c=inv["currency"]; outstanding[c]=outstanding.get(c,Decimal("0"))+inv["balance"]
            if inv["status_key"]=="overdue": overdue[c]=overdue.get(c,Decimal("0"))+inv["balance"]
            elif inv["status_key"]=="due_soon": due_soon[c]=due_soon.get(c,Decimal("0"))+inv["balance"]
    return {"filter":status_filter,"filter_label":RECEIVABLE_FILTERS[status_filter],"invoices":visible,"invoice_count":len(invoices),"visible_count":len(visible),"outstanding":_crm_amount_lines(outstanding),"overdue":_crm_amount_lines(overdue),"due_soon":_crm_amount_lines(due_soon),"status_counts":counts}


def _admin_finance_export_csv_v43_final():
    """Export all finance CSVs from one repeatable-read ledger snapshot."""
    with get_db() as conn:
        with conn.cursor() as cur:
            # Every CSV below must describe the same point in time. Without one
            # repeatable-read transaction, a payment/void arriving mid-export can
            # make the detail files disagree with their monthly summaries.
            cur.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
            cur.execute(
                "SELECT id,document_number,doc_type,lead_id,payment_id,issued_at,"
                "last_sent_at,COALESCE(send_count,0),COALESCE(document_status,'ACTIVE'),snapshot "
                "FROM business_documents ORDER BY issued_at,id"
            )
            docs = cur.fetchall()
            cur.execute(
                "SELECT p.id,p.lead_id,l.customer_name,l.customer_number,l.service,p.amount,"
                "COALESCE(p.currency,'MWK'),p.payment_method,p.reference,p.payment_note,p.received_at "
                "FROM lead_payments p JOIN leads l ON l.id=p.lead_id "
                "WHERE l.merged_into_lead_id IS NULL ORDER BY p.received_at,p.id"
            )
            payments = cur.fetchall()
            cur.execute(
                "SELECT v.original_payment_id,v.lead_id,COALESCE(l.customer_name,'Customer'),"
                "COALESCE(l.customer_number,''),COALESCE(l.service,'General Enquiry'),v.amount,"
                "COALESCE(v.currency,'MWK'),v.payment_method,v.reference,v.payment_note,"
                "v.original_received_at,v.void_reason,v.voided_at "
                "FROM payment_void_audit v LEFT JOIN leads l ON l.id=v.lead_id "
                "ORDER BY v.voided_at,v.id"
            )
            voided = cur.fetchall()
            cur.execute(
                "SELECT pp.id,pp.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),"
                "pa.project_type,pq.quote_reference,pp.stage,pp.amount,pp.currency,pp.payment_method,"
                "pp.reference,pp.payment_note,pp.received_at "
                "FROM project_payments pp JOIN project_assessments pa ON pa.id=pp.project_id "
                "JOIN project_quotations pq ON pq.id=pp.quotation_id ORDER BY pp.received_at,pp.id"
            )
            project_payments = cur.fetchall()
            cur.execute(
                "SELECT v.original_payment_id,v.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),"
                "pq.quote_reference,v.stage,v.amount,v.currency,v.payment_method,v.reference,v.payment_note,"
                "v.original_received_at,v.void_reason,v.voided_at "
                "FROM project_payment_void_audit v JOIN project_assessments pa ON pa.id=v.project_id "
                "JOIN project_quotations pq ON pq.id=v.quotation_id ORDER BY v.voided_at,v.id"
            )
            project_voids = cur.fetchall()
            cur.execute(
                "SELECT id,amount,COALESCE(currency,'MWK'),category,service,description,payment_method,"
                "reference,expense_date FROM business_expenses ORDER BY expense_date,id"
            )
            expenses = cur.fetchall()
            cur.execute(
                "SELECT original_expense_id,amount,currency,category,service,description,payment_method,"
                "reference,original_expense_date,void_reason,voided_at "
                "FROM business_expense_void_audit ORDER BY voided_at,id"
            )
            expense_voids = cur.fetchall()
            cur.execute(
                "SELECT pi.id,pi.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),"
                "pi.invoice_number,pi.invoice_type,pi.amount,pi.currency,pi.status,pi.issued_at,pi.paid_at "
                "FROM project_invoices pi JOIN project_assessments pa ON pa.id=pi.project_id "
                "UNION ALL "
                "SELECT si.id,si.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),"
                "si.invoice_number,si.stage,si.amount,si.currency,si.status,si.issued_at,si.paid_at "
                "FROM project_stage_invoices si JOIN project_assessments pa ON pa.id=si.project_id "
                "ORDER BY 10,1"
            )
            project_invoices = cur.fetchall()

    doc_rows=[]
    for doc_id,number,doc_type,lead_id,payment_id,issued,last_sent,send_count,status,snapshot in docs:
        snap=dict(snapshot or {}); selected=snap.get("selected_payment") if isinstance(snap.get("selected_payment"),dict) else {}
        doc_rows.append([doc_id,number,doc_type,status,lead_id,payment_id,snap.get("customer_name") or "",snap.get("customer_number") or "",snap.get("service") or "",snap.get("estimated_value") or "",snap.get("value_currency") or "MWK",snap.get("paid_total") or "",snap.get("balance") if snap.get("balance") is not None else "",selected.get("amount") or "",_export_local_datetime(issued),_export_local_datetime(last_sent),send_count])

    files={
        "payments.csv":_csv_text(["payment_id","lead_id","customer_name","customer_number","service","amount","currency","payment_method","reference","note","received_at_malawi"],[list(r[:10])+[_export_local_datetime(r[10])] for r in payments]),
        "voided_payments.csv":_csv_text(["original_payment_id","lead_id","customer_name","customer_number","service","amount","currency","payment_method","reference","note","original_received_at_malawi","void_reason","voided_at_malawi"],[list(r[:10])+[_export_local_datetime(r[10]),r[11],_export_local_datetime(r[12])] for r in voided]),
        "business_documents.csv":_csv_text(["document_id","document_number","document_type","document_status","lead_id","payment_id","customer_name_at_issue","customer_number_at_issue","service_at_issue","service_value_at_issue","currency","paid_total_at_issue","balance_at_issue","receipt_payment_amount","issued_at_malawi","last_sent_at_malawi","send_count"],doc_rows),
        "project_payments.csv":_csv_text(["payment_id","project_id","project_reference","client","project_type","quotation_reference","stage","amount","currency","payment_method","reference","note","received_at_malawi"],[list(r[:12])+[_export_local_datetime(r[12])] for r in project_payments]),
        "project_voided_payments.csv":_csv_text(["original_payment_id","project_id","project_reference","client","quotation_reference","stage","amount","currency","payment_method","reference","note","original_received_at_malawi","void_reason","voided_at_malawi"],[list(r[:11])+[_export_local_datetime(r[11]),r[12],_export_local_datetime(r[13])] for r in project_voids]),
        "project_invoices.csv":_csv_text(["invoice_id","project_id","project_reference","client","invoice_number","invoice_type_or_stage","amount","currency","status","issued_at_malawi","paid_at_malawi"],[list(r[:9])+[_export_local_datetime(r[9]),_export_local_datetime(r[10])] for r in project_invoices]),
        "expenses.csv":_csv_text(["expense_id","amount","currency","category","related_service","description","payment_method","reference","expense_date_malawi"],[list(r[:8])+[_export_local_datetime(r[8])] for r in expenses]),
        "voided_expenses.csv":_csv_text(["original_expense_id","amount","currency","category","related_service","description","payment_method","reference","original_expense_date_malawi","void_reason","voided_at_malawi"],[list(r[:8])+[_export_local_datetime(r[8]),r[9],_export_local_datetime(r[10])] for r in expense_voids]),
    }

    # Derive summaries from the exact detail rows already captured above instead
    # of opening fresh database connections after the detail CSVs were read.
    months = {}
    def month_bucket(dt):
        local = dt.astimezone(ADMIN_TIMEZONE)
        key = local.strftime("%Y-%m")
        return months.setdefault(key,{"label":local.strftime("%B %Y"),"received":{},"expenses":{},"payment_count":0,"expense_count":0,"services":{}})
    def add_revenue(amount,currency,dt,service):
        b=month_bucket(dt); amount=Decimal(amount or 0); currency=currency or "MWK"; service=service or "General business"
        b["received"][currency]=b["received"].get(currency,Decimal("0"))+amount; b["payment_count"]+=1
        sb=b["services"].setdefault(service,{"revenue":{},"expenses":{}}); sb["revenue"][currency]=sb["revenue"].get(currency,Decimal("0"))+amount
    def add_expense(amount,currency,dt,service):
        b=month_bucket(dt); amount=Decimal(amount or 0); currency=currency or "MWK"; service=service or "General business"
        b["expenses"][currency]=b["expenses"].get(currency,Decimal("0"))+amount; b["expense_count"]+=1
        sb=b["services"].setdefault(service,{"revenue":{},"expenses":{}}); sb["expenses"][currency]=sb["expenses"].get(currency,Decimal("0"))+amount

    for r in payments:
        add_revenue(r[5],r[6],r[10],canonicalize_service(r[4]) if r[4] else "General business")
    for r in project_payments:
        add_revenue(r[7],r[8],r[12],_v43_project_service_name(r[4]))
    for r in expenses:
        add_expense(r[1],r[2],r[8],canonicalize_service(r[4]) if r[4] else "General business")

    monthly=[]; service_monthly=[]
    for key in sorted(months,reverse=True)[:36]:
        b=months[key]
        currencies=sorted(set(b["received"])|set(b["expenses"]))
        for c in currencies:
            rev=b["received"].get(c,Decimal("0")); exp=b["expenses"].get(c,Decimal("0"))
            monthly.append([key,b["label"],c,rev,exp,rev-exp,b["payment_count"],b["expense_count"]])
        for service,sb in sorted(b["services"].items()):
            for c in sorted(set(sb["revenue"])|set(sb["expenses"])):
                rev=sb["revenue"].get(c,Decimal("0")); exp=sb["expenses"].get(c,Decimal("0"))
                service_monthly.append([key,b["label"],service,c,rev,exp,rev-exp])

    files["monthly_summary.csv"]=_csv_text(["month","month_label","currency","payments_received","business_expenses","net_cash","payment_count","expense_count"],monthly)
    files["monthly_service_summary.csv"]=_csv_text(["month","month_label","service","currency","payments_received","assigned_expenses","net_cash_contribution"],service_monthly)
    memory=io.BytesIO()
    with zipfile.ZipFile(memory,"w",compression=zipfile.ZIP_DEFLATED) as archive:
        for name,data in files.items(): archive.writestr(name,data)
    stamp=datetime.now(ADMIN_TIMEZONE).strftime("%Y-%m-%d")
    response=Response(memory.getvalue(),mimetype="application/zip")
    response.headers["Content-Disposition"]=f'attachment; filename="IBROWS_Finance_Export_{stamp}.zip"'
    response.headers["Cache-Control"]="no-store"
    print(f"FINANCE CSV EXPORT DOWNLOADED: files={len(files)} snapshot=repeatable-read",flush=True)
    return response

app.view_functions["admin_finance_export_csv"]=admin_required(_admin_finance_export_csv_v43_final)

def _v49_cleanup_invalid_application_confirmation_evidence():
    """Remove clearly non-evidentiary responses accidentally stored by older builds.

    Conversation history itself remains intact; only the special reusable-evidence table
    is cleaned. The loader also applies the same guard, so historical conversation
    fallback cannot resurrect these social/navigation messages later.
    """
    removed_ids = []
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, response_text
                FROM application_confirmation_evidence
                ORDER BY id
                """
            )
            for evidence_id, response_text in cur.fetchall():
                if not _application_confirmation_response_is_reusable(response_text):
                    removed_ids.append(evidence_id)
            if removed_ids:
                cur.execute(
                    "DELETE FROM application_confirmation_evidence WHERE id = ANY(%s)",
                    (removed_ids,),
                )
        conn.commit()
    if removed_ids:
        print(
            f"V49 INVALID APPLICATION EVIDENCE CLEANED: {len(removed_ids)}",
            flush=True,
        )
    return len(removed_ids)



def _v69_reconcile_superseded_project_invoices():
    """Void obsolete deposit invoices left by superseded, commercially-unused quotes.

    Earlier builds allowed an accepted quotation to be replaced before any money or
    execution existed, but left that quote's auto-created deposit invoice open. The
    invoice row is preserved for audit/export; only receivables status is corrected.
    Rows with any verified payment or execution are deliberately untouched.
    """
    fixed = []
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT pi.id,pi.invoice_number,pi.project_id,pi.quotation_id,pq.quote_reference
                FROM project_invoices pi
                JOIN project_quotations pq ON pq.id=pi.quotation_id
                WHERE pq.status='SUPERSEDED'
                  AND pi.status<>'VOID'
                  AND NOT EXISTS (SELECT 1 FROM project_payments pp WHERE pp.quotation_id=pi.quotation_id)
                  AND NOT EXISTS (SELECT 1 FROM project_execution pe WHERE pe.quotation_id=pi.quotation_id)
                FOR UPDATE OF pi
                """
            )
            rows = cur.fetchall()
            for invoice_id, invoice_number, project_id, quotation_id, quote_reference in rows:
                cur.execute(
                    "UPDATE project_invoices SET status='VOID',paid_at=NULL,updated_at=NOW() WHERE id=%s AND status<>'VOID'",
                    (invoice_id,),
                )
                _quote_event_insert(
                    cur,
                    quotation_id,
                    "DEPOSIT_INVOICE_VOIDED_SUPERSEDED",
                    f"Deposit invoice {invoice_number} reconciled to VOID because quotation {quote_reference} was superseded without verified payment or project execution.",
                )
                _project_activity_insert(
                    cur,
                    project_id,
                    "SUPERSEDED_INVOICE_RECONCILED",
                    f"Obsolete deposit invoice {invoice_number} from superseded quotation {quote_reference} was reconciled to VOID.",
                )
                fixed.append(invoice_id)
        conn.commit()
    if fixed:
        print(f"V69 SUPERSEDED PROJECT INVOICES RECONCILED: {len(fixed)}", flush=True)
    return len(fixed)

# =========================================================
# CONSTRUCTION PORTFOLIO V87
# Persistent public gallery + BUA company profile management.
# Files are stored in PostgreSQL, never on Render's ephemeral filesystem.
# =========================================================

CONSTRUCTION_MAX_IMAGE_BYTES = 8 * 1024 * 1024
CONSTRUCTION_MAX_PROFILE_BYTES = 10 * 1024 * 1024
CONSTRUCTION_MAX_IMAGES_PER_UPLOAD = 20
CONSTRUCTION_MAX_IMAGE_BATCH_BYTES = 12 * 1024 * 1024


def _init_construction_portfolio_v87_schema():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS construction_portfolio_assets (
                    id BIGSERIAL PRIMARY KEY,
                    asset_type TEXT NOT NULL
                        CHECK (asset_type IN ('IMAGE','PROFILE_PDF')),
                    filename TEXT NOT NULL,
                    mime_type TEXT NOT NULL,
                    file_bytes BYTEA NOT NULL,
                    byte_size BIGINT NOT NULL,
                    sha256 TEXT NOT NULL,
                    caption TEXT,
                    alt_text TEXT,
                    display_order INTEGER NOT NULL DEFAULT 0,
                    is_active BOOLEAN NOT NULL DEFAULT TRUE,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
                """
            )
            cur.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_construction_portfolio_public
                ON construction_portfolio_assets(asset_type,is_active,display_order,id)
                """
            )
            cur.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS uq_construction_portfolio_image_sha
                ON construction_portfolio_assets(sha256)
                WHERE asset_type='IMAGE'
                """
            )
        conn.commit()


def _construction_safe_filename(value, fallback):
    name = os.path.basename(str(value or "").strip())
    name = re.sub(r"[^A-Za-z0-9._ -]+", "_", name).strip(" ._")
    if not name:
        name = fallback
    return name[:180]


def _construction_read_upload(upload, max_bytes):
    data = upload.stream.read(max_bytes + 1)
    if not data:
        raise ValueError("The selected file is empty.")
    if len(data) > max_bytes:
        raise ValueError("The selected file is too large.")
    return bytes(data)


def _construction_detect_image_type(data):
    if data.startswith(b"\xff\xd8\xff"):
        return "image/jpeg", ".jpg"
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png", ".png"
    if len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp", ".webp"
    raise ValueError("Only JPEG, PNG or WebP construction photos are allowed.")


def _construction_image_rows(include_inactive=False):
    where = "asset_type='IMAGE'"
    if not include_inactive:
        where += " AND is_active=TRUE"
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT id,filename,mime_type,byte_size,caption,alt_text,
                       display_order,is_active,created_at,updated_at
                FROM construction_portfolio_assets
                WHERE {where}
                ORDER BY display_order ASC, id ASC
                """
            )
            rows = cur.fetchall()
    result = []
    for row in rows:
        result.append({
            "id": row[0],
            "filename": row[1],
            "mime_type": row[2],
            "byte_size": int(row[3] or 0),
            "size_label": f"{(int(row[3] or 0) / 1024 / 1024):.1f} MB",
            "caption": row[4] or "",
            "alt_text": row[5] or "",
            "display_order": int(row[6] or 0),
            "is_active": bool(row[7]),
            "created_at": row[8],
            "updated_at": row[9],
            "created_label": row[8].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[8] else "",
        })
    return result


def _construction_profile_meta():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id,filename,mime_type,byte_size,created_at,updated_at
                FROM construction_portfolio_assets
                WHERE asset_type='PROFILE_PDF' AND is_active=TRUE
                ORDER BY id DESC
                LIMIT 1
                """
            )
            row = cur.fetchone()
    if not row:
        return None
    return {
        "id": row[0],
        "filename": row[1],
        "mime_type": row[2],
        "byte_size": int(row[3] or 0),
        "size_label": f"{(int(row[3] or 0) / 1024 / 1024):.1f} MB",
        "created_at": row[4],
        "updated_at": row[5],
        "created_label": row[4].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[4] else "",
    }


# V120 public-gallery media optimization. Public pages use a bounded in-process
# preview cache; originals remain untouched in PostgreSQL and are still opened
# when a visitor taps an image. This keeps first-page bandwidth much smaller
# without changing the admin/source files.
WEB_GALLERY_PREVIEW_MAX_SIDE = 1280
# V131: Smaller admin thumbnails. Original uploads stay intact in PostgreSQL.
WEB_GALLERY_ADMIN_PREVIEW_MAX_SIDE = 640
WEB_GALLERY_PREVIEW_CACHE_ITEMS = 24
WEB_GALLERY_PREVIEW_CACHE_MAX_BYTES = 24 * 1024 * 1024
_WEB_GALLERY_PREVIEW_CACHE = OrderedDict()
_WEB_GALLERY_PREVIEW_LOCK = threading.Lock()


def _public_conditional_304(digest, updated_at, cache_control="public, max-age=3600, must-revalidate"):
    """Return a 304 response before reading a BYTEA payload when the browser cache is fresh."""
    probe = Response(b"", status=200)
    if digest:
        try:
            probe.set_etag(str(digest))
        except Exception:
            probe.headers["ETag"] = f'"{digest}"'
    probe.headers["Cache-Control"] = cache_control
    if updated_at:
        try:
            probe.last_modified = updated_at
        except Exception:
            pass
    try:
        probe.make_conditional(request)
    except Exception:
        return None
    return probe if probe.status_code == 304 else None


def _gallery_preview_cache_get(cache_key, source_digest, max_side=None):
    if not PIL_IMAGE_OPTIMIZER_AVAILABLE:
        return None
    size = int(max_side or WEB_GALLERY_PREVIEW_MAX_SIDE)
    key = (str(cache_key), str(source_digest or ""), size)
    with _WEB_GALLERY_PREVIEW_LOCK:
        cached = _WEB_GALLERY_PREVIEW_CACHE.get(key)
        if cached is not None:
            _WEB_GALLERY_PREVIEW_CACHE.move_to_end(key)
        return cached


def _gallery_preview_variant(cache_key, raw, mime_type, source_digest, max_side=None):
    """Create a browser-friendly preview, returning (bytes, mime, etag).

    Pillow is optional. If unavailable, invalid, or unable to make a meaningful
    saving, the original bytes are returned unchanged. Cache is deliberately
    bounded because Render runs this service with one modest worker.
    """
    data = bytes(raw or b"")
    mime = str(mime_type or "application/octet-stream").lower()
    digest = str(source_digest or hashlib.sha256(data).hexdigest())
    if not data or not mime.startswith("image/") or not PIL_IMAGE_OPTIMIZER_AVAILABLE:
        return data, mime, digest

    size = int(max_side or WEB_GALLERY_PREVIEW_MAX_SIDE)
    size = max(160, min(1920, size))
    key = (str(cache_key), digest, size)
    with _WEB_GALLERY_PREVIEW_LOCK:
        cached = _WEB_GALLERY_PREVIEW_CACHE.get(key)
        if cached is not None:
            _WEB_GALLERY_PREVIEW_CACHE.move_to_end(key)
            return cached

    try:
        with PILImage.open(io.BytesIO(data)) as source:
            image = PILImageOps.exif_transpose(source) if PILImageOps else source.copy()
            image.thumbnail((size, size), PILImage.Resampling.LANCZOS)
            out = io.BytesIO()
            has_alpha = image.mode in {"RGBA", "LA"} or (image.mode == "P" and "transparency" in image.info)
            if has_alpha:
                if image.mode not in {"RGBA", "LA"}:
                    image = image.convert("RGBA")
                image.save(out, format="WEBP", quality=82, method=4)
                preview_mime = "image/webp"
            else:
                if image.mode != "RGB":
                    image = image.convert("RGB")
                image.save(out, format="JPEG", quality=82, optimize=True, progressive=True)
                preview_mime = "image/jpeg"
            preview = out.getvalue()
    except Exception:
        return data, mime, digest

    # Do not replace an already-small/efficient original with a larger derivative.
    if not preview or len(preview) >= int(len(data) * 0.95):
        result = (data, mime, digest)
    else:
        result = (preview, preview_mime, hashlib.sha256(preview).hexdigest())

    with _WEB_GALLERY_PREVIEW_LOCK:
        _WEB_GALLERY_PREVIEW_CACHE[key] = result
        _WEB_GALLERY_PREVIEW_CACHE.move_to_end(key)
        # Keep previews within a byte budget as well as an item-count budget.
        # Memory footprint on small Render workers matters more than gallery count.
        while (_WEB_GALLERY_PREVIEW_CACHE and
               (len(_WEB_GALLERY_PREVIEW_CACHE) > WEB_GALLERY_PREVIEW_CACHE_ITEMS or
                sum(len(value[0]) for value in _WEB_GALLERY_PREVIEW_CACHE.values()) > WEB_GALLERY_PREVIEW_CACHE_MAX_BYTES)):
            _WEB_GALLERY_PREVIEW_CACHE.popitem(last=False)
    return result


def _construction_asset_response(asset_id, allow_inactive=False, download=False):
    # Admin and downloads always receive the original. Public gallery <img> tags
    # request ?preview=1 and may receive a smaller derivative.
    wants_preview = (not allow_inactive and not download and request.args.get("preview") == "1")
    where = "id=%s" if allow_inactive else "id=%s AND is_active=TRUE"

    # Metadata first: a browser with a fresh ETag can be answered with 304 without
    # pulling a multi-megabyte BYTEA value from PostgreSQL.
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"SELECT filename,mime_type,sha256,updated_at FROM construction_portfolio_assets WHERE {where}",
                (asset_id,),
            )
            meta = cur.fetchone()
    if not meta:
        abort(404)
    filename, mime_type, digest, updated_at = meta

    cache_control = "private, no-store" if allow_inactive else "public, max-age=3600, must-revalidate"
    if wants_preview and str(mime_type or "").lower().startswith("image/"):
        preview_cached = _gallery_preview_cache_get(f"construction:{asset_id}", digest)
        if preview_cached is not None:
            data, response_mime, response_digest = preview_cached
            not_modified = _public_conditional_304(response_digest, updated_at, cache_control)
            if not_modified is not None:
                return not_modified
            response = Response(data, mimetype=response_mime)
            safe_name = _construction_safe_filename(filename, "construction-file")
            response.headers["Content-Disposition"] = f"inline; filename*=UTF-8''{quote(safe_name, safe='')}"
            response.set_etag(str(response_digest))
            response.headers["Cache-Control"] = cache_control
            if updated_at:
                try:
                    response.last_modified = updated_at
                except Exception:
                    pass
            response.make_conditional(request)
            return response
    # Preview derivatives use their own ETag, so source-ETag short-circuiting is
    # only correct for original responses.
    if not wants_preview and not allow_inactive:
        cached = _public_conditional_304(digest, updated_at, cache_control)
        if cached is not None:
            return cached

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(f"SELECT file_bytes FROM construction_portfolio_assets WHERE {where}", (asset_id,))
            row = cur.fetchone()
    if not row:
        abort(404)
    data = bytes(row[0] or b"")
    if not data:
        abort(404)

    response_mime = mime_type
    response_digest = digest
    if wants_preview and str(mime_type or "").lower().startswith("image/"):
        data, response_mime, response_digest = _gallery_preview_variant(
            f"construction:{asset_id}", data, mime_type, digest
        )

    response = Response(data, mimetype=response_mime)
    safe_name = _construction_safe_filename(filename, "construction-file")
    disposition = "attachment" if download else "inline"
    response.headers["Content-Disposition"] = f"{disposition}; filename*=UTF-8''{quote(safe_name, safe='')}"
    try:
        response.set_etag(str(response_digest))
    except Exception:
        response.headers["ETag"] = f'"{response_digest}"'
    response.headers["Cache-Control"] = cache_control
    if updated_at:
        try:
            response.last_modified = updated_at
        except Exception:
            pass
    if not allow_inactive:
        response.make_conditional(request)
    return response


