@app.route("/admin/construction-portfolio/profile", methods=["POST"])
@admin_required
def admin_construction_profile_upload():
    validate_csrf()
    upload = request.files.get("profile_pdf")
    if not upload or not upload.filename:
        return redirect(url_for("admin_construction_portfolio", message="Choose a PDF company profile first.", message_type="err"))
    try:
        data = _construction_read_upload(upload, CONSTRUCTION_MAX_PROFILE_BYTES)
        if not data.lstrip().startswith(b"%PDF-"):
            raise ValueError("The selected company profile is not a valid PDF file.")
        filename = _construction_safe_filename(upload.filename, "BUA-Company-Profile.pdf")
        if not filename.lower().endswith(".pdf"):
            filename += ".pdf"
        digest = hashlib.sha256(data).hexdigest()
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE construction_portfolio_assets SET is_active=FALSE,updated_at=NOW() WHERE asset_type='PROFILE_PDF' AND is_active=TRUE"
                )
                cur.execute(
                    """
                    INSERT INTO construction_portfolio_assets
                        (asset_type,filename,mime_type,file_bytes,byte_size,sha256,caption,alt_text,display_order,is_active)
                    VALUES('PROFILE_PDF',%s,'application/pdf',%s,%s,%s,NULL,NULL,0,TRUE)
                    """,
                    (filename, data, len(data), digest),
                )
            conn.commit()
        print(f"CONSTRUCTION PROFILE PUBLISHED: filename={filename} bytes={len(data)}", flush=True)
        return redirect(url_for("admin_construction_portfolio", message="Company profile published successfully."))
    except ValueError as exc:
        return redirect(url_for("admin_construction_portfolio", message=str(exc), message_type="err"))


@app.route("/admin/construction-portfolio/profile/remove", methods=["POST"])
@admin_required
def admin_construction_profile_remove():
    validate_csrf()
    if request.form.get("_ibrows_confirmed_action") != "1":
        return redirect(url_for(
            "admin_construction_portfolio",
            message="Confirmation was not received, so nothing was removed. Refresh the page and try again.",
            message_type="err",
        ))
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE construction_portfolio_assets SET is_active=FALSE,updated_at=NOW() WHERE asset_type='PROFILE_PDF' AND is_active=TRUE"
            )
        conn.commit()
    print("CONSTRUCTION PROFILE REMOVED FROM PUBLIC VIEW", flush=True)
    return redirect(url_for("admin_construction_portfolio", message="Company profile removed from public view."))


@app.route("/admin/construction-portfolio/images", methods=["POST"])
@admin_required
def admin_construction_images_upload():
    validate_csrf()
    uploads = [item for item in request.files.getlist("images") if item and item.filename]
    if not uploads:
        return redirect(url_for("admin_construction_portfolio", message="Choose at least one construction photo.", message_type="err"))
    if len(uploads) > CONSTRUCTION_MAX_IMAGES_PER_UPLOAD:
        return redirect(url_for("admin_construction_portfolio", message=f"Upload no more than {CONSTRUCTION_MAX_IMAGES_PER_UPLOAD} photos at a time.", message_type="err"))
    caption = " ".join(str(request.form.get("caption") or "").split()).strip()[:180]
    prepared = []
    batch_total = 0
    try:
        for upload in uploads:
            data = _construction_read_upload(upload, CONSTRUCTION_MAX_IMAGE_BYTES)
            batch_total += len(data)
            if batch_total > CONSTRUCTION_MAX_IMAGE_BATCH_BYTES:
                raise ValueError("Keep each construction photo upload batch at 12 MB or less.")
            mime_type, extension = _construction_detect_image_type(data)
            filename = _construction_safe_filename(upload.filename, f"construction{extension}")
            stem = os.path.splitext(filename)[0].strip(" .") or "construction"
            filename = f"{stem}{extension}"
            prepared.append((filename, mime_type, data, hashlib.sha256(data).hexdigest()))
    except ValueError as exc:
        return redirect(url_for("admin_construction_portfolio", message=str(exc), message_type="err"))

    inserted = 0
    duplicates = 0
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(display_order),0) FROM construction_portfolio_assets WHERE asset_type='IMAGE'")
            next_order = int(cur.fetchone()[0] or 0) + 10
            for filename, mime_type, data, digest in prepared:
                cur.execute(
                    """
                    INSERT INTO construction_portfolio_assets
                        (asset_type,filename,mime_type,file_bytes,byte_size,sha256,caption,alt_text,display_order,is_active)
                    VALUES('IMAGE',%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
                    ON CONFLICT DO NOTHING
                    RETURNING id
                    """,
                    (
                        filename, mime_type, data, len(data), digest,
                        caption or None,
                        caption or "BUA construction project work",
                        next_order,
                    ),
                )
                if cur.fetchone():
                    inserted += 1
                    next_order += 10
                else:
                    duplicates += 1
        conn.commit()
    message = f"Uploaded {inserted} construction photo{'s' if inserted != 1 else ''}."
    if duplicates:
        message += f" Skipped {duplicates} duplicate{'s' if duplicates != 1 else ''}."
    print(f"CONSTRUCTION PHOTOS UPLOADED: inserted={inserted} duplicates={duplicates}", flush=True)
    return redirect(url_for("admin_construction_portfolio", message=message))


@app.route("/admin/construction-portfolio/images/bulk-update", methods=["POST"])
@admin_required
def admin_construction_images_bulk_update():
    validate_csrf()
    raw_ids = request.form.getlist("image_id")
    image_ids = []
    seen = set()
    for raw_id in raw_ids:
        try:
            image_id = int(raw_id)
        except Exception:
            abort(400)
        if image_id <= 0 or image_id in seen:
            abort(400)
        seen.add(image_id)
        image_ids.append(image_id)
    if not image_ids:
        return redirect(url_for("admin_construction_portfolio", message="No construction photos were available to save.", message_type="err"))

    prepared = []
    for image_id in image_ids:
        caption = " ".join(str(request.form.get(f"caption_{image_id}") or "").split()).strip()[:180]
        alt_text = " ".join(str(request.form.get(f"alt_text_{image_id}") or "").split()).strip()[:220]
        try:
            display_order = max(0, min(9999, int(request.form.get(f"display_order_{image_id}") or 0)))
        except Exception:
            display_order = 0
        is_active = request.form.get(f"is_active_{image_id}") == "1"
        prepared.append((image_id, caption, alt_text, display_order, is_active))

    ordered_ids = sorted(image_ids)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id
                FROM construction_portfolio_assets
                WHERE asset_type='IMAGE' AND id = ANY(%s)
                ORDER BY id
                FOR UPDATE
                """,
                (ordered_ids,),
            )
            locked_ids = [int(row[0]) for row in cur.fetchall()]
            if locked_ids != ordered_ids:
                conn.rollback()
                abort(409)
            for image_id, caption, alt_text, display_order, is_active in prepared:
                cur.execute(
                    """
                    UPDATE construction_portfolio_assets
                    SET caption=%s,alt_text=%s,display_order=%s,is_active=%s,updated_at=NOW()
                    WHERE id=%s AND asset_type='IMAGE'
                    """,
                    (caption or None, alt_text or None, display_order, is_active, image_id),
                )
        conn.commit()
    print(f"CONSTRUCTION PHOTOS BULK UPDATED: count={len(prepared)}", flush=True)
    return redirect(url_for("admin_construction_portfolio", message=f"Saved all {len(prepared)} construction photos successfully."))


@app.route("/admin/construction-portfolio/images/<int:asset_id>/update", methods=["POST"])
@admin_required
def admin_construction_image_update(asset_id):
    validate_csrf()
    caption_key = f"caption_{asset_id}"
    alt_key = f"alt_text_{asset_id}"
    order_key = f"display_order_{asset_id}"
    active_key = f"is_active_{asset_id}"
    caption = " ".join(str(request.form.get(caption_key, request.form.get("caption")) or "").split()).strip()[:180]
    alt_text = " ".join(str(request.form.get(alt_key, request.form.get("alt_text")) or "").split()).strip()[:220]
    try:
        display_order = max(0, min(9999, int(request.form.get(order_key, request.form.get("display_order")) or 0)))
    except Exception:
        display_order = 0
    if active_key in request.form:
        is_active = request.form.get(active_key) == "1"
    elif caption_key in request.form or alt_key in request.form or order_key in request.form:
        is_active = False
    else:
        is_active = request.form.get("is_active") == "1"
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE construction_portfolio_assets
                SET caption=%s,alt_text=%s,display_order=%s,is_active=%s,updated_at=NOW()
                WHERE id=%s AND asset_type='IMAGE'
                RETURNING id
                """,
                (caption or None, alt_text or None, display_order, is_active, asset_id),
            )
            if not cur.fetchone():
                abort(404)
        conn.commit()
    return redirect(url_for("admin_construction_portfolio", message="Construction photo updated."))


@app.route("/admin/construction-portfolio/images/<int:asset_id>/delete", methods=["POST"])
@admin_required
def admin_construction_image_delete(asset_id):
    validate_csrf()
    if request.form.get("_ibrows_confirmed_action") != "1":
        abort(400)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "DELETE FROM construction_portfolio_assets WHERE id=%s AND asset_type='IMAGE' RETURNING id",
                (asset_id,),
            )
            if not cur.fetchone():
                abort(404)
        conn.commit()
    print(f"CONSTRUCTION PHOTO DELETED: id={asset_id}", flush=True)
    return redirect(url_for("admin_construction_portfolio", message="Construction photo deleted."))



