def _service_pricing_package(service_key, code):
    code = str(code or "").strip().upper()
    for item in SERVICE_PRICING_PACKAGES.get(str(service_key or "").strip().upper(), []):
        if str(item.get("code") or "").upper() == code:
            return item
    return None


def _service_pricing_summary(service_key):
    return SERVICE_PRICING_PACKAGES.get(str(service_key or "").strip().upper(), [])


def _service_package_guidance(service_key, payload=None, selected_code=None):
    """Return conservative package guidance for clearly mismatched selections.

    This is sales/UX guidance only. It never marks payment as made and never
    changes the customer's package automatically.
    """
    service_key = str(service_key or "").strip().upper()
    payload = dict(payload or {})
    selected_code = str(
        selected_code if selected_code is not None else request.form.get("package_choice")
        or ""
    ).strip().upper()
    if not selected_code:
        return None

    def raw(name, limit=500):
        return _service_clean(request.form.get(name), limit).upper()

    def raw_text(name, limit=1000):
        return _service_clean_multiline(request.form.get(name), limit).lower()

    recommended = ""
    acceptable = set()
    reason = ""

    if service_key == "CAREER_JOBS":
        support = raw("support_needed", 40)
        vacancy = raw_text("vacancy_details", 600)
        has_cv = raw("has_cv", 30)
        if support == "SINGLE_APPLICATION":
            recommended = "TARGETED_APPLICATION"
            acceptable = {"TARGETED_APPLICATION", "TARGETED_PACK", "PRO_CAREER", "CAREER_ASSIST"}
            reason = "You asked for help with one specific job application."
        elif support in {"CAREER_ASSIST", "VACANCY_SEARCH"}:
            recommended = "CAREER_ASSIST"
            acceptable = {"CAREER_ASSIST"}
            reason = "Your answers describe ongoing vacancy/search support rather than a one-off document service."
        elif support == "CV_COVER":
            if vacancy:
                recommended = "TARGETED_PACK"
                acceptable = {"TARGETED_PACK", "PRO_CAREER", "CAREER_ASSIST"}
                reason = "You supplied a specific vacancy, so a vacancy-targeted application package is the closer fit."
            elif has_cv == "NEED_UPDATE":
                recommended = "CV_COVER"
                acceptable = {"CV_COVER", "TARGETED_PACK", "PRO_CAREER", "CAREER_ASSIST"}
                reason = "You asked for CV and cover-letter support."
            else:
                recommended = "CV_COVER"
                acceptable = {"CV_COVER", "TARGETED_PACK", "PRO_CAREER", "CAREER_ASSIST"}
                reason = "You asked for CV and cover-letter support."
        elif support == "INTERVIEW":
            recommended = "PRO_CAREER"
            acceptable = {"PRO_CAREER", "CAREER_ASSIST"}
            reason = "Interview preparation is included in the fuller career-support package."
        elif support == "PROFILE_REVIEW":
            recommended = "CV_REFRESH"
            acceptable = {"CV_REFRESH", "PRO_CAREER", "CAREER_ASSIST"}
            reason = "Your request is closest to a professional profile/CV review."

    elif service_key == "SCHOLARSHIPS":
        support = raw("support_needed", 40)
        if support == "ELIGIBILITY":
            recommended = "ELIGIBILITY"
            acceptable = {"ELIGIBILITY", "SEARCH_SHORTLIST", "SCHOLARSHIP_ASSIST"}
            reason = "You asked mainly for an eligibility check."
        elif support == "SEARCH":
            recommended = "SEARCH_SHORTLIST"
            acceptable = {"SEARCH_SHORTLIST", "SCHOLARSHIP_ASSIST"}
            reason = "You asked IBROWS to search and shortlist scholarship opportunities."
        elif support in {"APPLICATION_REVIEW", "PERSONAL_STATEMENT", "RESEARCH_PROPOSAL", "DEADLINE_REVIEW"}:
            recommended = "APPLICATION_SUPPORT"
            acceptable = {"APPLICATION_SUPPORT", "SCHOLARSHIP_ASSIST"}
            reason = "Your answers describe support with a specific scholarship application."

    elif service_key == "BUSINESS_REGISTRATION":
        support = raw("support_needed", 40)
        notes = raw_text("notes", 2500)
        if support == "NEW_REGISTRATION":
            if any(k in notes for k in ("sole trader", "sole proprietor", "sole-proprietor")):
                recommended = "SOLE_TRADER"
                acceptable = {"SOLE_TRADER", "COMPANY_SETUP"}
                reason = "You described a sole-trader / sole-proprietor registration."
            elif any(k in notes for k in ("limited company", "ltd", "company registration", "private limited")):
                recommended = "COMPANY_SETUP"
                acceptable = {"COMPANY_SETUP"}
                reason = "You described a company-registration setup rather than a readiness-only check."

    elif service_key == "PHOTO_RESTORATION":
        try:
            count = int(payload.get("photo_count") or 0)
        except (TypeError, ValueError):
            count = 0
        if count:
            if count <= 5:
                recommended = "RESTORE_5"
                acceptable = {"RESTORE_5", "RESTORE_10", "RESTORE_20"}
                reason = f"You uploaded {count} photo{'s' if count != 1 else ''}."
            elif count <= 10:
                recommended = "RESTORE_10"
                acceptable = {"RESTORE_10", "RESTORE_20"}
                reason = f"You uploaded {count} photos, which is above the 5-photo package."
            else:
                recommended = "RESTORE_20"
                acceptable = {"RESTORE_20"}
                reason = f"You uploaded {count} photos, which needs the larger restoration package."

    elif service_key == "CLEANING":
        cleaning_type = raw("cleaning_type", 40)
        property_type = raw("property_type", 30)
        frequency = raw("frequency", 30)
        if cleaning_type in {"OFFICE", "RECURRING"} or (
            property_type in {"OFFICE", "SHOP", "SCHOOL"} and frequency not in {"", "ONCE"}
        ):
            recommended = "OFFICE_CONTRACT"
            acceptable = {"OFFICE_CONTRACT"}
            reason = "Your answers describe recurring or workplace/commercial cleaning."
        elif cleaning_type in {"DEEP", "MOVE", "POST_CONSTRUCTION"}:
            recommended = "DEEP_CLEAN"
            acceptable = {"DEEP_CLEAN", "OFFICE_CONTRACT"}
            reason = "Your request needs more intensive cleaning than a routine home clean."
        elif cleaning_type == "GENERAL" and property_type in {"HOUSE", "APARTMENT"}:
            recommended = "HOME_STANDARD"
            acceptable = {"HOME_STANDARD", "DEEP_CLEAN"}
            reason = "Your answers describe a routine residential clean."

    elif service_key == "CAR_WASH":
        wash_type = raw("wash_type", 40)
        vehicle_count = raw("vehicle_count", 20)
        if wash_type == "EXTERIOR":
            recommended = "EXTERIOR"
            acceptable = {"EXTERIOR", "FULL_WASH", "DETAIL"}
            reason = "You selected an exterior wash."
        elif wash_type in {"FULL", "INTERIOR"}:
            recommended = "FULL_WASH"
            acceptable = {"FULL_WASH", "DETAIL"}
            reason = "Your request includes interior/full cleaning."
        elif wash_type == "DETAILING":
            recommended = "DETAIL"
            acceptable = {"DETAIL"}
            reason = "You requested detailed/intensive vehicle cleaning."
        elif wash_type == "FLEET" or (vehicle_count.isdigit() and int(vehicle_count) > 1):
            # Fleet work is quoted after review; do not force a retail package.
            return None

    elif service_key == "DESIGN_BRANDING":
        service_needed = raw("service_needed", 40)
        design_type = raw_text("design_type", 300)
        quantity = raw_text("quantity", 160)
        combined = f"{design_type} {quantity}"
        if service_needed == "JINGLE_CREATION" or any(k in combined for k in ("jingle", "radio advert", "audio advert")):
            recommended = "JINGLE_STARTER"
            acceptable = {"JINGLE_STARTER"}
