def _service_clean(value, limit=500):
    return " ".join(str(value or "").strip().split())[:limit]


def _service_clean_multiline(value, limit=4000):
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    text = "\n".join(line.rstrip() for line in text.splitlines())
    return text[:limit]


def _service_parse_follow_up_at(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw)
    except Exception as exc:
        raise ValueError("Choose a valid follow-up date and time.") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=ADMIN_TIMEZONE)
    else:
        parsed = parsed.astimezone(ADMIN_TIMEZONE)
    if parsed > datetime.now(ADMIN_TIMEZONE) + timedelta(days=730):
        raise ValueError("Follow-up date cannot be more than two years ahead.")
    return parsed.astimezone(UTC_TIMEZONE)


def _service_valid_email(value):
    value = _service_clean(value, 200)
    if not value:
        return ""
    if len(value) > 200 or not re.fullmatch(r"[^\s@]+@[^\s@]+\.[^\s@]+", value):
        raise ValueError("Enter a valid email address.")
    return value


def _service_whatsapp_number(value):
    digits = re.sub(r"[^0-9]", "", str(value or ""))
    if digits.startswith("00"):
        digits = digits[2:]
    if digits.startswith("0") and len(digits) in {9, 10}:
        digits = "265" + digits[1:]
    return digits[:20]


def get_public_service_csrf(service_key):
    key = str(service_key or "").strip().upper()
    secret = str(FLASK_SECRET_KEY or "").encode("utf-8")
    message = f"ibrows-public-service-v89:{key}".encode("utf-8")
    return hmac.new(secret, message, hashlib.sha256).hexdigest()


def validate_public_service_csrf(service_key):
    supplied = str(request.form.get("csrf_token") or "").strip()
    expected = get_public_service_csrf(service_key)
    if not supplied or not secrets.compare_digest(supplied, expected):
        abort(403)


def _service_form_honeypot_ok():
    return not _service_clean(request.form.get("fax_number"), 120)


def _service_read_image_upload(upload, max_bytes=SERVICE_REQUEST_MAX_IMAGE_BYTES):
    data = _construction_read_upload(upload, max_bytes)
    mime_type, extension = _construction_detect_image_type(data)
    filename = _construction_safe_filename(upload.filename, f"client-photo{extension}")
    stem = os.path.splitext(filename)[0].strip(" .") or "client-photo"
    # Trust the detected bytes, not the client-supplied extension.
    filename = f"{stem}{extension}"
    return filename, mime_type, data, hashlib.sha256(data).hexdigest()


def _service_optional_image_upload(field_name):
    upload = request.files.get(field_name)
    if not upload or not upload.filename:
        return []
    return [_service_read_image_upload(upload)]



def _service_image_upload_batch(field_name, min_files=1, max_files=20, max_total_bytes=40 * 1024 * 1024):
    uploads = [item for item in request.files.getlist(field_name) if item and item.filename]
    if len(uploads) < int(min_files):
        raise ValueError(f"Please upload at least {int(min_files)} photographs for this package request.")
    if len(uploads) > int(max_files):
        raise ValueError(f"Upload no more than {int(max_files)} photographs in one request.")
    files = []
    total = 0
    seen = set()
    for upload in uploads:
        item = _service_read_image_upload(upload)
        if item[3] in seen:
            continue
        seen.add(item[3])
        total += len(item[2])
        if total > int(max_total_bytes):
            raise ValueError("The combined photo upload is too large. Keep the batch under 40 MB.")
        files.append(item)
    if len(files) < int(min_files):
        raise ValueError(f"Please upload at least {int(min_files)} different photographs.")
    return files


def _service_read_tender_document(upload, max_bytes=SERVICE_REQUEST_MAX_DOCUMENT_BYTES):
    data = _construction_read_upload(upload, max_bytes)
    filename = _construction_safe_filename(upload.filename, "tender-document")
    ext = os.path.splitext(filename)[1].lower()
    allowed = {
        ".pdf": ("application/pdf", b"%PDF-"),
        ".docx": ("application/vnd.openxmlformats-officedocument.wordprocessingml.document", b"PK\x03\x04"),
        ".xlsx": ("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", b"PK\x03\x04"),
        ".doc": ("application/msword", b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"),
        ".xls": ("application/vnd.ms-excel", b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"),
    }
    if ext not in allowed:
        raise ValueError("Tender documents must be PDF, Word (.doc/.docx) or Excel (.xls/.xlsx).")
    mime_type, signature = allowed[ext]
    if not data.startswith(signature):
        raise ValueError(f"{filename} does not match the expected {ext.upper()} file format.")
    return filename, mime_type, data, hashlib.sha256(data).hexdigest()


def _service_optional_tender_documents(field_name):
    uploads = [item for item in request.files.getlist(field_name) if item and item.filename]
    if not uploads:
        return []
    if len(uploads) > SERVICE_REQUEST_MAX_DOCUMENT_FILES:
        raise ValueError(f"Upload no more than {SERVICE_REQUEST_MAX_DOCUMENT_FILES} tender files at a time.")
    files = []
    total_bytes = 0
    for upload in uploads:
        item = _service_read_tender_document(upload)
        total_bytes += len(item[2])
        if total_bytes > SERVICE_REQUEST_MAX_DOCUMENT_BATCH_BYTES:
            raise ValueError("The combined tender-document upload is too large. Keep the batch under 20 MB.")
        files.append(item)
    return files


def _service_reference_for_id(request_id, created_at=None):
    when = created_at or datetime.now(ADMIN_TIMEZONE)
    return f"IBR-SR-{when.astimezone(ADMIN_TIMEZONE).year}-{int(request_id):04d}"


def _create_website_service_request(service_key, full_name, phone, email, payload, files=None):
    if service_key not in SERVICE_REQUEST_KEYS:
        raise ValueError("Unknown service request type.")
    payload = dict(payload or {})
    available_packages = _service_pricing_summary(service_key)
    package = _service_pricing_package(service_key, request.form.get("package_choice"))
    if available_packages and not package:
        raise ValueError("Please choose the paid service package you want before submitting your request.")
    if package:
        payload["package_choice"] = package["code"]
        payload["package_label"] = package["name"]
        payload["package_price"] = package["price"]
        package_guidance = _service_package_guidance(service_key, payload, package["code"])
        if package_guidance:
            payload["package_check_status"] = "REVIEW"
            payload["package_recommended_code"] = package_guidance["recommended_code"]
            payload["package_recommended_label"] = package_guidance["recommended_name"]
            payload["package_recommended_price"] = package_guidance["recommended_price"]
            payload["package_check_reason"] = package_guidance["reason"]
            payload["package_override_confirmed"] = request.form.get("package_mismatch_confirmed") == "1"
            print(
                f"PACKAGE CHECK REVIEW: service={service_key} "
                f"selected={package['code']} recommended={package_guidance['recommended_code']} "
                f"client_override={payload['package_override_confirmed']}",
                flush=True,
            )
        else:
            payload["package_check_status"] = "MATCH"
    files = files or []
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO website_service_requests
                    (service_key,full_name,phone,email,payload,status,notification_status,created_at,updated_at)
                VALUES (%s,%s,%s,NULLIF(%s,''),%s::jsonb,'NEW','PENDING',NOW(),NOW())
                RETURNING id,created_at
                """,
                (service_key, full_name, phone, email, json.dumps(payload, ensure_ascii=False)),
            )
            request_id, created_at = cur.fetchone()
            reference = _service_reference_for_id(request_id, created_at)
            cur.execute(
                "UPDATE website_service_requests SET reference=%s WHERE id=%s",
                (reference, request_id),
            )
            for filename, mime_type, data, digest in files:
                cur.execute(
                    """
                    INSERT INTO website_service_request_files
                        (request_id,filename,mime_type,file_bytes,byte_size,sha256)
                    VALUES (%s,%s,%s,%s,%s,%s)
                    ON CONFLICT (request_id,sha256) DO NOTHING
                    """,
                    (request_id, filename, mime_type, data, len(data), digest),
                )
        conn.commit()
    print(f"WEBSITE SERVICE REQUEST CREATED: {reference} service={service_key}", flush=True)
    _send_website_service_request_alert(request_id)
    return reference


TENDER_WORKFLOW_STEPS = [
    ("requirements_reviewed", "Tender requirements reviewed"),
    ("compliance_checklist", "Compliance checklist prepared"),
    ("company_docs_verified", "Company documents verified"),
    ("boq_checked", "BOQ prepared / priced / arithmetic checked"),
    ("technical_response", "Technical response / method statements ready"),
    ("programme_ready", "Work programme / implementation schedule ready"),
    ("final_review", "Final bid review completed"),
    ("submission_ready", "Submission package ready"),
    ("bid_submitted", "Bid submitted / submission receipt confirmed"),
]


def _service_tender_deadline_info(payload):
    payload = payload or {}
    raw = _service_clean(payload.get("closing_date"), 40)
    if not raw:
        return None
    try:
        local_dt = datetime.fromisoformat(raw)
        if local_dt.tzinfo is None:
            local_dt = local_dt.replace(tzinfo=ADMIN_TIMEZONE)
        else:
            local_dt = local_dt.astimezone(ADMIN_TIMEZONE)
    except Exception:
        return {
            "raw": raw, "label": raw, "state": "UNKNOWN",
            "remaining": "Closing time could not be parsed", "is_closed": False, "utc": None,
        }
    utc_dt = local_dt.astimezone(UTC_TIMEZONE)
    now = datetime.now(UTC_TIMEZONE)
    delta = utc_dt - now
    seconds = int(delta.total_seconds())
    abs_seconds = abs(seconds)
    days, rem = divmod(abs_seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    if days:
        span = f"{days}d {hours}h"
    elif hours:
        span = f"{hours}h {minutes}m"
    else:
        span = f"{max(0, minutes)}m"
    if seconds < 0:
        state = "CLOSED"
        remaining = f"Closed {span} ago"
    elif seconds <= 4 * 3600:
        state = "CRITICAL"
        remaining = f"{span} remaining"
    elif seconds <= 24 * 3600:
        state = "URGENT"
        remaining = f"{span} remaining"
    elif seconds <= 72 * 3600:
        state = "SOON"
        remaining = f"{span} remaining"
    else:
        state = "OPEN"
        remaining = f"{span} remaining"
    return {
        "raw": raw,
        "label": local_dt.strftime("%d %b %Y at %H:%M Malawi time"),
        "state": state,
        "remaining": remaining,
        "is_closed": seconds < 0,
        "utc": utc_dt,
    }


def _service_tender_workflow_view(workflow):
    workflow = workflow if isinstance(workflow, dict) else {}
    completed = {str(x) for x in (workflow.get("tender_checklist") or [])}
    steps = [{"key": key, "label": label, "done": key in completed} for key, label in TENDER_WORKFLOW_STEPS]
    done = sum(1 for item in steps if item["done"])
    total = len(steps)
    return {
        "steps": steps,
        "done": done,
        "total": total,
        "percent": int(round((done / total) * 100)) if total else 0,
        "note": _service_clean_multiline(workflow.get("tender_note"), 3000),
        "updated_label": _service_clean(workflow.get("tender_updated_label"), 80),
    }


def _get_website_service_request(request_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id,reference,service_key,full_name,phone,email,payload,status,admin_note,
                       follow_up_at,follow_up_notified_at,follow_up_notification_claimed_at,follow_up_notification_error,
                       notification_status,notification_error,notification_sent_at,created_at,updated_at,admin_workflow
                FROM website_service_requests WHERE id=%s
                """,
                (request_id,),
            )
            row = cur.fetchone()
            if not row:
                return None
            cur.execute(
                """
                SELECT id,filename,mime_type,byte_size,created_at
                FROM website_service_request_files
                WHERE request_id=%s ORDER BY id
                """,
                (request_id,),
            )
            file_rows = cur.fetchall()
    payload = row[6] if isinstance(row[6], dict) else json.loads(row[6] or "{}")
    workflow = row[18] if isinstance(row[18], dict) else json.loads(row[18] or "{}")
    now_utc = datetime.now(UTC_TIMEZONE)
    if row[12]:
        reminder_state = "FAILED"
    elif row[10]:
        reminder_state = "SENT"
    elif row[11]:
        reminder_state = "SENDING"
    elif row[9] and row[9] <= now_utc and row[7] not in {"COMPLETED", "CLOSED"}:
        reminder_state = "DUE"
    elif row[9]:
        reminder_state = "SCHEDULED"
    else:
        reminder_state = "NOT_SCHEDULED"
    return {
        "id": row[0], "reference": row[1], "service_key": row[2],
        "service_label": SERVICE_REQUEST_KEYS.get(row[2], row[2]),
        "full_name": row[3], "phone": row[4], "email": row[5] or "",
        "payload": payload or {}, "status": row[7], "admin_note": row[8] or "",
        "follow_up_at": row[9], "follow_up_notified_at": row[10],
        "follow_up_notification_claimed_at": row[11], "follow_up_notification_error": row[12] or "",
        "notification_status": row[13], "notification_error": row[14] or "",
        "notification_sent_at": row[15], "created_at": row[16], "updated_at": row[17],
        "admin_workflow": workflow or {},
        "tender_deadline": _service_tender_deadline_info(payload) if row[2] == "CONSTRUCTION_TENDER" else None,
        "tender_workflow": _service_tender_workflow_view(workflow) if row[2] == "CONSTRUCTION_TENDER" else None,
        "created_label": row[16].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[16] else "",
        "updated_label": row[17].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[17] else "",
        "follow_up_label": row[9].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[9] else "",
        "follow_up_input": row[9].astimezone(ADMIN_TIMEZONE).strftime("%Y-%m-%dT%H:%M") if row[9] else "",
        "follow_up_due": reminder_state == "DUE",
        "follow_up_notified_label": row[10].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[10] else "",
        "follow_up_claimed_label": row[11].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[11] else "",
        "reminder_state": reminder_state,
        "files": [
            {"id": f[0], "filename": f[1], "mime_type": f[2], "byte_size": int(f[3] or 0),
             "size_label": f"{int(f[3] or 0)/1024/1024:.1f} MB", "created_at": f[4]}
            for f in file_rows
        ],
    }


def _website_service_request_rows(service_key="", status="", search_q=""):
    where = []
    params = []
    if service_key in SERVICE_REQUEST_KEYS:
        where.append("r.service_key=%s")
        params.append(service_key)
    if status in SERVICE_REQUEST_STATUSES:
        where.append("r.status=%s")
        params.append(status)
    search_q = _service_clean(search_q, 120)
    if search_q:
        term = f"%{search_q}%"
        where.append("(r.reference ILIKE %s OR r.full_name ILIKE %s OR r.phone ILIKE %s OR COALESCE(r.email,'') ILIKE %s)")
        params.extend([term, term, term, term])
    clause = ("WHERE " + " AND ".join(where)) if where else ""
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT r.id,r.reference,r.service_key,r.full_name,r.phone,r.email,r.status,
                       r.created_at,r.updated_at,r.follow_up_at,r.follow_up_notified_at,
                       r.follow_up_notification_claimed_at,r.follow_up_notification_error,
                       (SELECT COUNT(*) FROM website_service_request_files f WHERE f.request_id=r.id) AS file_count,
                       r.payload,r.admin_workflow
                FROM website_service_requests r
                {clause}
                ORDER BY CASE r.status WHEN 'NEW' THEN 0 WHEN 'REVIEWING' THEN 1 WHEN 'CONTACTED' THEN 2 WHEN 'IN_PROGRESS' THEN 3 ELSE 4 END,
                         r.created_at DESC,r.id DESC
                LIMIT 250
                """,
                tuple(params),
            )
            rows = cur.fetchall()
    result = []
    for row in rows:
        wa_number = _service_whatsapp_number(row[4])
        msg = f"Hello {row[3]}. This is IBROWS Enterprise following up on your {SERVICE_REQUEST_KEYS.get(row[2], row[2])} request {row[1]}."
        row_payload = row[14] if isinstance(row[14], dict) else json.loads(row[14] or "{}")
        row_workflow = row[15] if isinstance(row[15], dict) else json.loads(row[15] or "{}")
        now_utc = datetime.now(UTC_TIMEZONE)
        if row[12]:
            reminder_state = "FAILED"
        elif row[10]:
            reminder_state = "SENT"
        elif row[11]:
            reminder_state = "SENDING"
        elif row[9] and row[9] <= now_utc and row[6] not in {"COMPLETED", "CLOSED"}:
            reminder_state = "DUE"
        elif row[9]:
            reminder_state = "SCHEDULED"
        else:
            reminder_state = "NOT_SCHEDULED"
        email_subject = f"IBROWS follow-up: {row[1]}"
        result.append({
            "id": row[0], "reference": row[1], "service_key": row[2],
            "service_label": SERVICE_REQUEST_KEYS.get(row[2], row[2]),
            "full_name": row[3], "phone": row[4], "email": row[5] or "", "status": row[6],
            "status_label": SERVICE_REQUEST_STATUSES.get(row[6], row[6]),
            "created_at": row[7], "updated_at": row[8], "follow_up_at": row[9], "file_count": int(row[13] or 0),
            "created_label": row[7].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[7] else "",
            "updated_label": row[8].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[8] else "",
            "follow_up_label": row[9].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[9] else "",
            "follow_up_notified_label": row[10].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[10] else "",
            "follow_up_claimed_label": row[11].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[11] else "",
            "follow_up_error": row[12] or "",
            "reminder_state": reminder_state,
            "follow_up_due": reminder_state == "DUE",
            "whatsapp_url": f"https://wa.me/{wa_number}?text={quote(msg, safe='')}" if wa_number else "",
            "tel_url": f"tel:+{wa_number}" if wa_number else "",
            "email_url": f"mailto:{row[5]}?subject={quote(email_subject, safe='')}" if row[5] else "",
            "tender_deadline": _service_tender_deadline_info(row_payload) if row[2] == "CONSTRUCTION_TENDER" else None,
            "tender_workflow": _service_tender_workflow_view(row_workflow) if row[2] == "CONSTRUCTION_TENDER" else None,
        })
    return result


def _service_request_counts():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT COUNT(*),
                       COUNT(*) FILTER (WHERE status='NEW'),
                       COUNT(*) FILTER (WHERE status IN ('REVIEWING','CONTACTED','IN_PROGRESS')),
                       COUNT(*) FILTER (WHERE status IN ('COMPLETED','CLOSED'))
                FROM website_service_requests
                """
            )
            row = cur.fetchone() or (0, 0, 0, 0)
    return {"total": int(row[0] or 0), "new": int(row[1] or 0), "active": int(row[2] or 0), "finished": int(row[3] or 0)}


def _service_reference_exists(service_key, reference):
    if service_key not in SERVICE_REQUEST_KEYS or not reference:
        return False
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM website_service_requests WHERE service_key=%s AND reference=%s LIMIT 1",
                (service_key, reference),
            )
            return bool(cur.fetchone())


def _service_public_submission_summary(service_key, reference):
    """Return only non-sensitive information safe for the browser success screen."""
    if service_key not in SERVICE_REQUEST_KEYS or not reference:
        return {}
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT payload
                FROM website_service_requests
                WHERE service_key=%s AND reference=%s
                LIMIT 1
                """,
                (service_key, reference),
            )
            row = cur.fetchone()
    if not row:
        return {}
    payload = row[0] if isinstance(row[0], dict) else json.loads(row[0] or "{}")
    return {
        "package_label": _service_clean(payload.get("package_label"), 180),
        "package_price": _service_clean(payload.get("package_price"), 80),
        "package_check_status": _service_clean(payload.get("package_check_status"), 20).upper(),
        "recommended_label": _service_clean(payload.get("package_recommended_label"), 180),
        "recommended_price": _service_clean(payload.get("package_recommended_price"), 80),
        "package_check_reason": _service_clean_multiline(payload.get("package_check_reason"), 500),
    }


def _send_website_service_request_alert(request_id):
    if not BREVO_API_KEY or not NOTIFICATION_EMAIL or not BREVO_SENDER_EMAIL:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE website_service_requests SET notification_status='FAILED',notification_error='Brevo notification is not configured',updated_at=NOW() WHERE id=%s",
                    (request_id,),
                )
            conn.commit()
        return False
    item = _get_website_service_request(request_id)
    if not item:
        return False
    admin_base = LEAD_DASHBOARD_URL.rsplit("/admin/leads", 1)[0]
    admin_url = f"{admin_base}/admin/service-requests/{request_id}"
    email_role = _website_request_email_role(item.get("service_key"))
    body = (
        f"A new IBROWS website service request has been submitted.\n\n"
        f"Reference: {item['reference']}\n"
        f"Service: {item['service_label']}\n"
        f"Client: {item['full_name']}\n"
        f"Phone: {item['phone']}\n"
        f"Email: {item['email'] or '-'}\n"
        f"Files: {len(item['files'])}\n\n"
        f"Review: {admin_url}\n"
    )
    payload = {
        "sender": _brevo_sender_payload(email_role),
        "replyTo": _brevo_reply_to_payload(email_role),
        "to": [{"email": NOTIFICATION_EMAIL, "name": "IBROWS Enterprise"}],
        "subject": f"New website request: {item['reference']} · {item['service_label']}",
        "textContent": body,
    }
    ok = False
    error = ""
    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={"api-key": BREVO_API_KEY, "Content-Type": "application/json"},
            json=payload,
            timeout=8,
        )
        ok = 200 <= response.status_code < 300
        if not ok:
            error = f"Brevo HTTP {response.status_code}"
    except Exception as exc:
        error = type(exc).__name__
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE website_service_requests
                SET notification_status=%s,notification_error=%s,
                    notification_sent_at=CASE WHEN %s THEN NOW() ELSE notification_sent_at END,
                    updated_at=NOW()
                WHERE id=%s
                """,
                ("SENT" if ok else "FAILED", None if ok else error, ok, request_id),
            )
        conn.commit()
    return ok


def claim_due_website_service_follow_up_reminders(limit=20):
    """Atomically claim due website-service follow-ups for admin email reminders."""
    limit = max(1, min(int(limit), 50))
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id,reference,service_key,full_name,phone,email,follow_up_at,admin_note
                FROM website_service_requests
                WHERE status NOT IN ('COMPLETED','CLOSED')
                  AND follow_up_at IS NOT NULL
                  AND follow_up_at <= NOW()
                  AND follow_up_notified_at IS NULL
                  AND (
                        follow_up_notification_claimed_at IS NULL
                        OR follow_up_notification_claimed_at < NOW() - INTERVAL '15 minutes'
                  )
                ORDER BY follow_up_at ASC
                LIMIT %s
                FOR UPDATE SKIP LOCKED
                """,
                (limit,),
            )
            rows = cur.fetchall()
            for row in rows:
                cur.execute(
                    """
                    UPDATE website_service_requests
                    SET follow_up_notification_claimed_at=NOW(),
                        follow_up_notification_error=NULL
                    WHERE id=%s
                      AND follow_up_notified_at IS NULL
                    """,
                    (row[0],),
                )
        conn.commit()
    return [
        {
            "id": r[0], "reference": r[1], "service_key": r[2],
            "service_label": SERVICE_REQUEST_KEYS.get(r[2], r[2]),
            "full_name": r[3], "phone": r[4], "email": r[5] or "",
            "follow_up_at": r[6], "admin_note": r[7] or "",
        }
        for r in rows
    ]


def finish_website_service_follow_up_reminder(request_id, success, error=None):
    with get_db() as conn:
        with conn.cursor() as cur:
            if success:
                cur.execute(
                    """
                    UPDATE website_service_requests
                    SET follow_up_notified_at=NOW(),
                        follow_up_notification_claimed_at=NULL,
                        follow_up_notification_error=NULL
                    WHERE id=%s
                    """,
                    (request_id,),
                )
            else:
                cur.execute(
                    """
                    UPDATE website_service_requests
                    SET follow_up_notification_claimed_at=NULL,
                        follow_up_notification_error=%s
                    WHERE id=%s
                    """,
                    (str(error or "Unknown reminder error")[:500], request_id),
                )
        conn.commit()


def send_website_service_follow_up_reminder_email(item):
    if not BREVO_API_KEY or not NOTIFICATION_EMAIL or not BREVO_SENDER_EMAIL:
        return False, "Brevo configuration incomplete"
    when_local = item["follow_up_at"].astimezone(ADMIN_TIMEZONE)
    wa_number = _service_whatsapp_number(item.get("phone"))
    admin_base = LEAD_DASHBOARD_URL.rsplit("/admin/leads", 1)[0]
    admin_url = f"{admin_base}/admin/service-requests/{item['id']}"
    email_role = _website_request_email_role(item.get("service_key"))
    body = (
        "An IBROWS website-service follow-up is due.\n\n"
        f"Reference: {item['reference']}\n"
        f"Client: {item['full_name']}\n"
        f"Service: {item['service_label']}\n"
        f"Phone: {item['phone']}\n"
        f"Email: {item['email'] or '-'}\n"
        f"Scheduled follow-up: {when_local.strftime('%d %B %Y at %H:%M')} Malawi time\n\n"
        f"Internal note:\n{item['admin_note'] or 'No internal note recorded.'}\n\n"
        f"Review request: {admin_url}\n"
        + (f"WhatsApp: https://wa.me/{wa_number}\n" if wa_number else "")
        + "\nIBROWS Enterprise\nKupanga zofanana, mosiyana\n"
    )
    payload = {
        "sender": _brevo_sender_payload(email_role),
        "replyTo": _brevo_reply_to_payload(email_role),
        "to": [{"email": NOTIFICATION_EMAIL, "name": "IBROWS Enterprise"}],
        "subject": f"IBROWS follow-up due: {item['reference']} · {item['full_name']}",
        "textContent": body,
    }
    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={"api-key": BREVO_API_KEY, "Content-Type": "application/json"},
            json=payload,
            timeout=10,
        )
        if 200 <= response.status_code < 300:
            print(f"WEBSITE SERVICE FOLLOW-UP EMAIL SENT: {item['reference']}", flush=True)
            return True, None
        error = f"Brevo HTTP {response.status_code}"
    except Exception as exc:
        error = f"{type(exc).__name__}: {str(exc)[:180]}"
    print(f"WEBSITE SERVICE FOLLOW-UP EMAIL FAILED: {item['reference']} — {error}", flush=True)
    return False, error


def process_due_website_service_follow_up_reminders(limit=20):
    claimed = claim_due_website_service_follow_up_reminders(limit=limit)
    sent = failed = 0
    for item in claimed:
        success, error = send_website_service_follow_up_reminder_email(item)
        finish_website_service_follow_up_reminder(item["id"], success, error)
        if success:
            sent += 1
        else:
            failed += 1
    print(
        f"WEBSITE SERVICE FOLLOW-UP CHECK: due={len(claimed)} sent={sent} failed={failed}",
        flush=True,
    )
    return {"claimed": len(claimed), "sent": sent, "failed": failed}


REMINDER_TASK_KEY = "FOLLOWUP_REMINDERS"
REMINDER_TASK_STALE_MINUTES = 35


def _record_task_health(task_key, source, ok, summary=None, error=None):
    """Best-effort task telemetry. Never let health logging break reminders."""
    task_key = _service_clean(task_key, 80).upper() or "UNKNOWN"
    source = _service_clean(source, 30).upper() or "UNKNOWN"
    try:
        summary_json = json.dumps(summary or {}, separators=(",", ":"), default=str)
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO ibrows_task_health(task_key,source,last_run_at,last_ok,last_summary,last_error)
                    VALUES(%s,%s,NOW(),%s,%s::jsonb,%s)
                    ON CONFLICT(task_key,source) DO UPDATE SET
                        last_run_at=EXCLUDED.last_run_at,
                        last_ok=EXCLUDED.last_ok,
                        last_summary=EXCLUDED.last_summary,
                        last_error=EXCLUDED.last_error
                    """,
                    (task_key, source, bool(ok), summary_json, _service_clean(str(error or ""), 600) or None),
                )
            conn.commit()
    except Exception as exc:
        print(f"TASK HEALTH WRITE FAILED: {task_key}/{source} — {type(exc).__name__}: {str(exc)[:180]}", flush=True)


def _task_health_snapshot(task_key=REMINDER_TASK_KEY, source="CRON"):
    source = str(source or "CRON").upper()
    row = None
    try:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT last_run_at,last_ok,last_summary,last_error FROM ibrows_task_health WHERE task_key=%s AND source=%s",
                    (task_key, source),
                )
                row = cur.fetchone()
    except Exception as exc:
        return {
            "state": "ERROR", "label": "Health check unavailable", "last_run_label": "Not available",
            "age_minutes": None, "summary": {}, "error": f"{type(exc).__name__}: {str(exc)[:180]}",
        }
    if not row:
        return {
            "state": "UNKNOWN", "label": "No automatic check recorded yet" if source == "CRON" else "No manual check recorded yet",
            "last_run_label": "Not yet", "age_minutes": None, "summary": {}, "error": "",
        }
    last_run_at, last_ok, summary, error = row
    now_utc = datetime.now(UTC_TIMEZONE)
    age_minutes = max(0, int((now_utc - last_run_at.astimezone(UTC_TIMEZONE)).total_seconds() // 60))
    if not last_ok:
        state, label = "ERROR", "Last check reported a problem"
    elif source == "CRON" and age_minutes > REMINDER_TASK_STALE_MINUTES:
        state, label = "STALE", f"Automatic task is stale ({age_minutes} min since last check)"
    else:
        state, label = "HEALTHY", "Automatic task is healthy" if source == "CRON" else "Manual check completed"
    return {
        "state": state, "label": label,
        "last_run_label": last_run_at.astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M"),
        "age_minutes": age_minutes, "summary": summary or {}, "error": error or "",
    }


