def _public_service_common_fields(require_email=False):
    if not _service_form_honeypot_ok():
        abort(400)
    if request.form.get("consent") != "1":
        raise ValueError("Please confirm that IBROWS may use the submitted details to review your enquiry.")
    full_name = _service_clean(request.form.get("full_name"), 160)
    phone = _service_clean(request.form.get("phone"), 60)
    email = _service_valid_email(request.form.get("email"))
    if not full_name or len(full_name) < 2:
        raise ValueError("Please enter your name.")
    if not phone or len(re.sub(r"\D", "", phone)) < 7:
        raise ValueError("Please enter a valid phone or WhatsApp number.")
    if require_email and not email:
        raise ValueError("Please enter your email address.")
    return full_name, phone, email


@app.route("/career-jobs", methods=["GET", "POST"])
def career_jobs_service():
    service_key = "CAREER_JOBS"
    if request.method == "GET":
        return _render_service_request_page(service_key), 200
    validate_public_service_csrf(service_key)
    field_names = ("full_name","phone","email","support_needed","target_role","current_location","work_preference","experience_level","has_cv","vacancy_details","preferred_timeframe","notes")
    values = {k: request.form.get(k, "") for k in field_names}
    try:
        full_name, phone, email = _public_service_common_fields(require_email=True)
        support_needed = _service_clean(request.form.get("support_needed"), 40).upper()
        target_role = _service_clean(request.form.get("target_role"), 240)
        current_location = _service_clean(request.form.get("current_location"), 180)
        work_preference = _service_clean(request.form.get("work_preference"), 30).upper()
        experience_level = _service_clean(request.form.get("experience_level"), 30).upper()
        has_cv = _service_clean(request.form.get("has_cv"), 30).upper()
        if support_needed not in {"CV_COVER","SINGLE_APPLICATION","CAREER_ASSIST","VACANCY_SEARCH","INTERVIEW","PROFILE_REVIEW","OTHER"}:
            raise ValueError("Choose the career support you need.")
        if not target_role:
            raise ValueError("Please enter the role or career field you are targeting.")
        if not current_location:
            raise ValueError("Please enter your current town or country.")
        if work_preference not in {"MALAWI","REMOTE","INTERNATIONAL","FLEXIBLE"}:
            raise ValueError("Choose where you would like to work.")
        if experience_level not in {"ENTRY","EARLY","MID","SENIOR","EXECUTIVE","NOT_SURE"}:
            raise ValueError("Choose your experience level.")
        if has_cv not in {"YES","NEED_UPDATE","NO"}:
            raise ValueError("Tell us whether you already have a CV.")
        support_labels = {
            "CV_COVER":"CV + Cover Letter", "SINGLE_APPLICATION":"Single Job Application",
            "CAREER_ASSIST":"Career Assist", "VACANCY_SEARCH":"Vacancy Search / Job Opportunities",
            "INTERVIEW":"Interview Preparation", "PROFILE_REVIEW":"Professional Profile Review", "OTHER":"Other Career Support"
        }
        work_labels = {"MALAWI":"Malawi","REMOTE":"Remote","INTERNATIONAL":"International / Abroad","FLEXIBLE":"Flexible / Open to Options"}
        experience_labels = {"ENTRY":"Entry Level / Starting Out","EARLY":"1–3 Years","MID":"4–7 Years","SENIOR":"8+ Years / Senior","EXECUTIVE":"Management / Executive","NOT_SURE":"Not Sure"}
        cv_labels = {"YES":"Yes, Up to Date","NEED_UPDATE":"Yes, Needs Updating","NO":"No, Needs Preparation"}
        payload = {
            "support_needed": support_labels[support_needed],
            "target_role": target_role,
            "current_location": current_location,
            "work_preference": work_labels[work_preference],
            "experience_level": experience_labels[experience_level],
            "has_cv": cv_labels[has_cv],
            "vacancy_details": _service_clean(request.form.get("vacancy_details"), 500),
            "preferred_timeframe": _service_clean(request.form.get("preferred_timeframe"), 160),
            "notes": _service_clean_multiline(request.form.get("notes"), 3000),
        }
        ref = _create_website_service_request(service_key, full_name, phone, email, payload)
        return redirect(url_for("career_jobs_service", submitted=ref))
    except ValueError as exc:
        return _render_service_request_page(service_key, str(exc), values), 400


