@app.route("/business-email", methods=["GET", "POST"])
def business_email_service():
    service_key = "BUSINESS_EMAIL"
    if request.method == "GET":
        return _render_service_request_page(service_key), 200
    validate_public_service_csrf(service_key)
    fields = ("full_name", "phone", "email", "business_name", "domain_status", "has_website",
              "preferred_domain", "mailbox_count", "provider", "mailbox_names", "preferred_timeframe", "notes")
    values = {key: request.form.get(key, "") for key in fields}
    try:
        name, phone, email = _public_service_common_fields(require_email=True)
        business_name = _service_clean(request.form.get("business_name"), 200)
        domain_status = _service_clean(request.form.get("domain_status"), 20).upper()
        has_website = _service_clean(request.form.get("has_website"), 20).upper()
        provider = _service_clean(request.form.get("provider"), 30).upper()
        preferred_domain = _service_clean(request.form.get("preferred_domain"), 253).lower().rstrip(".")
        mailbox_count = _service_clean(request.form.get("mailbox_count"), 2)
        mailbox_names = _service_clean_multiline(request.form.get("mailbox_names"), 700)
        if not business_name:
            raise ValueError("Please enter your business or organisation name.")
        if domain_status not in {"NO", "YES", "NOT_SURE"}:
            raise ValueError("Please select whether you already own a domain.")
        if has_website not in {"YES", "NO", "PLANNED"}:
            raise ValueError("Please choose your current website status.")
        if provider not in {"UNSURE", "BASIC", "GOOGLE", "MICROSOFT"}:
            raise ValueError("Please choose your preferred email provider.")
        if not mailbox_count.isdigit() or not 1 <= int(mailbox_count) <= 20:
            raise ValueError("Please select a mailbox count between 1 and 20.")
        if not mailbox_names.strip():
            raise ValueError("Please list the email address names you need, such as info and sales.")
        if preferred_domain and (len(preferred_domain) > 253 or not re.fullmatch(
            r"(?=.{4,253}$)(?!-)[a-z0-9-]+(?:\.[a-z0-9-]+)+", preferred_domain
        ) or any(label.startswith("-") or label.endswith("-") or len(label) > 63
                 for label in preferred_domain.split("."))):
            raise ValueError("Enter a valid domain, for example yourcompany.com, without https:// or @.")
        payload = {
            "business_name": business_name,
            "domain_status": domain_status,
            "has_website": has_website,
            "preferred_domain": preferred_domain,
            "mailbox_count": int(mailbox_count),
            "provider": provider,
            "mailbox_names": mailbox_names,
            "preferred_timeframe": _service_clean(request.form.get("preferred_timeframe"), 100),
            "notes": _service_clean_multiline(request.form.get("notes"), 1800),
            "quotation_required": True,
            "domain_registered_to_client": True,
        }
        ref = _create_website_service_request(service_key, name, phone, email, payload)
        return redirect(url_for("business_email_service", submitted=ref))
    except ValueError as exc:
        return _render_service_request_page(service_key, str(exc), values), 400


