    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("UPDATE website_service_portfolio_assets SET caption=%s,alt_text=%s,display_order=%s,is_active=%s,updated_at=NOW() WHERE id=%s AND service_key=%s RETURNING id", (caption or None,alt_text or None,display_order,is_active,asset_id,service_key))
            if not cur.fetchone(): abort(404)
        conn.commit()
    return redirect(url_for("admin_service_portfolios", message="Portfolio item updated."))


