# =========================================================
# V125 — WHATSAPP WEBHOOK INTEGRITY
# =========================================================
# Meta normally delivers one incoming message per webhook request, but the
# webhook envelope supports multiple entries, changes and messages. Process
# every signed message independently so a batched delivery cannot silently
# acknowledge later messages without handling them.
_V124_RECEIVE_WEBHOOK = app.view_functions.get("receive_webhook")


def _v125_contact_slice(value, message):
    contacts = value.get("contacts") or []
    sender = str((message or {}).get("from") or "")
    for contact in contacts:
        if str((contact or {}).get("wa_id") or "") == sender:
            return [contact]
    return contacts[:1]


def _v125_message_payloads(data):
    payloads = []
    if not isinstance(data, dict):
        return payloads
    entries = data.get("entry") or []
    if not isinstance(entries, list):
        return payloads
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        changes = entry.get("changes") or []
        if not isinstance(changes, list):
            continue
        for change in changes:
            if not isinstance(change, dict):
                continue
            value = change.get("value") or {}
            if not isinstance(value, dict):
                continue
            messages = value.get("messages") or []
            if not isinstance(messages, list):
                continue
            for message in messages:
                if not isinstance(message, dict):
                    continue
                one_value = dict(value)
                one_value["messages"] = [message]
                one_value["contacts"] = _v125_contact_slice(value, message)
                one_change = dict(change)
                one_change["value"] = one_value
                one_entry = dict(entry)
                one_entry["changes"] = [one_change]
                one_data = dict(data)
                one_data["entry"] = [one_entry]
                payloads.append(one_data)
    return payloads


def _receive_webhook_v125():
    data = request.get_json(silent=True) or {}
    message_payloads = _v125_message_payloads(data)

    # Preserve the original handler for status-only events or malformed payloads;
    # it already contains the correct 200/500 behavior for those cases.
    if not message_payloads:
        return _V124_RECEIVE_WEBHOOK()

    any_failed = False
    outer_remote = request.remote_addr
    outer_host = request.host
    outer_scheme = request.scheme

    for one_data in message_payloads:
        # The outer request has already passed the HMAC signature verifier. The
        # inner context is only a safe way to reuse the established single-message
        # processing pipeline without re-parsing or duplicating its business logic.
        with app.test_request_context(
            "/webhook",
            method="POST",
            json=one_data,
            base_url=f"{outer_scheme}://{outer_host}",
            environ_base={"REMOTE_ADDR": outer_remote or "127.0.0.1"},
        ):
            try:
                response = app.make_response(_V124_RECEIVE_WEBHOOK())
                if int(response.status_code) >= 500:
                    any_failed = True
            except Exception as exc:
                any_failed = True
                print(
                    f"BATCHED WHATSAPP MESSAGE FAILED: {type(exc).__name__}",
                    flush=True,
                )

    if len(message_payloads) > 1:
        print(
            f"WHATSAPP BATCH PROCESSED: messages={len(message_payloads)} failed={int(any_failed)}",
            flush=True,
        )
    return ("PROCESSING_FAILED", 500) if any_failed else ("EVENT_RECEIVED", 200)


if _V124_RECEIVE_WEBHOOK is not None:
    app.view_functions["receive_webhook"] = _receive_webhook_v125

